//| label: fig-05-ssim-artefatos
//| fig-cap: "Análise espacial de degradação: imagens reconstruídas e respectivos mapas de erro absoluto normalizados para diferentes fatores de qualidade JPEG."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <filesystem>
#include "morph.hpp"

// Reimplementação da métrica SSIM (Wang et al.) usando apenas OpenCV
cv::Scalar compute_ssim(const cv::Mat& img1, const cv::Mat& img2, cv::Mat& ssim_map) {
    const double C1 = 6.5025;  // (0.01 * 255)^2
    const double C2 = 58.5225; // (0.03 * 255)^2

    cv::Mat img1_f, img2_f;
    img1.convertTo(img1_f, CV_32F);
    img2.convertTo(img2_f, CV_32F);

    cv::Mat mu1, mu2, mu1_sq, mu2_sq, mu1_mu2;
    cv::GaussianBlur(img1_f, mu1, cv::Size(11, 11), 1.5);
    cv::GaussianBlur(img2_f, mu2, cv::Size(11, 11), 1.5);

    cv::pow(mu1, 2, mu1_sq);
    cv::pow(mu2, 2, mu2_sq);
    cv::multiply(mu1, mu2, mu1_mu2);

    cv::Mat sigma1_sq, sigma2_sq, sigma12;
    cv::Mat img1_sq, img2_sq, img1_img2;

    cv::multiply(img1_f, img1_f, img1_sq);
    cv::multiply(img2_f, img2_f, img2_sq);
    cv::multiply(img1_f, img2_f, img1_img2);

    cv::GaussianBlur(img1_sq, sigma1_sq, cv::Size(11, 11), 1.5);
    cv::GaussianBlur(img2_sq, sigma2_sq, cv::Size(11, 11), 1.5);
    cv::GaussianBlur(img1_img2, sigma12, cv::Size(11, 11), 1.5);

    cv::subtract(sigma1_sq, mu1_sq, sigma1_sq);
    cv::subtract(sigma2_sq, mu2_sq, sigma2_sq);
    cv::subtract(sigma12, mu1_mu2, sigma12);

    cv::Mat cs_map, ssim_map_f;
    cv::Mat temp1, temp2;

    cv::add(mu1_mu2 * 2, C1, temp1);
    cv::add(sigma12 * 2, C2, temp2);
    cv::multiply(temp1, temp2, cs_map);

    cv::add(mu1_sq, mu2_sq, temp1);
    cv::add(temp1, C1, temp1);
    cv::add(sigma1_sq, sigma2_sq, temp2);
    cv::add(temp2, C2, temp2);
    cv::multiply(temp1, temp2, temp1);

    cv::divide(cs_map, temp1, ssim_map_f);

    cv::Scalar mssim = cv::mean(ssim_map_f);

    // Normaliza o mapa SSIM para visualização (0-255)
    cv::normalize(ssim_map_f, ssim_map, 0, 255, cv::NORM_MINMAX, CV_8U);

    return mssim;
}

// Função de compressão JPEG com qualidade definida (convertendo mm::Image -> cv::Mat)
cv::Mat jpeg_quality_compress(const mm::Image& img, int qualidade) {
    cv::Mat img_cv(img.h, img.w, CV_8UC1, const_cast<unsigned char*>(img.data.data()));
    std::vector<int> params = {cv::IMWRITE_JPEG_QUALITY, qualidade};
    std::vector<unsigned char> buffer;
    cv::imencode(".jpg", img_cv, buffer, params);
    return cv::imdecode(buffer, cv::IMREAD_GRAYSCALE);
}

// Função auxiliar para converter cv::Mat de um canal em mm::Image
mm::Image mat_to_mm_image(const cv::Mat& mat) {
    mm::Image out(mat.rows, mat.cols, 1);
    if (mat.isContinuous()) {
        std::memcpy(out.data.data(), mat.data, out.data.size());
    } else {
        cv::Mat cont;
        mat.copyTo(cont);
        std::memcpy(out.data.data(), cont.data, out.data.size());
    }
    return out;
}

int main() {
    // Garante a existência do diretório de testes
    std::filesystem::create_directories("imagens/comp_test");

    std::vector<int> qualidades_ssim = {25, 50, 75, 95};
    std::vector<mm::Image> imgs_ssim;
    std::vector<std::string> titles_ssim;

    imgs_ssim.push_back(img_gray);
    titles_ssim.push_back("Original");

    // Converte a imagem original para cv::Mat para processamento
    cv::Mat img_gray_cv(img_gray.h, img_gray.w, CV_8UC1, img_gray.data.data());

    for (int q : qualidades_ssim) {
        std::string path = "imagens/comp_test/camera_ssim_q" + std::to_string(q) + ".jpg";

        // GRAVAÇÃO FORÇADA: Gera e grava o JPEG com a qualidade atual no caminho correto
        cv::Mat img_compactada = jpeg_quality_compress(img_gray, q);
        cv::imwrite(path, img_compactada);

        // Leitura segura do arquivo recém-gravado
        cv::Mat rec = cv::imread(path, cv::IMREAD_GRAYSCALE);

        if (rec.empty()) {
            continue;
        }

        if (rec.size() != img_gray_cv.size()) {
            cv::resize(rec, rec, img_gray_cv.size());
        }

        double psnr_v = cv::PSNR(img_gray_cv, rec);

        // Calcula SSIM
        cv::Mat ssim_map;
        cv::Scalar ssim_scalar = compute_ssim(img_gray_cv, rec, ssim_map);
        double ssim_v = ssim_scalar[0];

        // Diferença absoluta normalizada para evidenciar a estrutura espacial do erro
        cv::Mat img1_f, img2_f, diff;
        img_gray_cv.convertTo(img1_f, CV_32F);
        rec.convertTo(img2_f, CV_32F);
        cv::absdiff(img1_f, img2_f, diff);

        cv::Mat diff_vis;
        cv::normalize(diff, diff_vis, 0, 255, cv::NORM_MINMAX, CV_8U);

        imgs_ssim.push_back(mat_to_mm_image(rec));
        imgs_ssim.push_back(mat_to_mm_image(diff_vis));

        char titulo[100];
        snprintf(titulo, sizeof(titulo), "Q=%d\nPSNR=%.1fdB | SSIM=%.3f", q, psnr_v, ssim_v);
        titles_ssim.push_back(titulo);

        snprintf(titulo, sizeof(titulo), "Mapa de erro (Q=%d)\n(Bordas e blocagem)", q);
        titles_ssim.push_back(titulo);
    }

    // Exibe a grade de imagens
    mm::show(imgs_ssim, MM_OUT, titles_ssim, 3);

    return 0;
}

