//| label: fig-05-conv-teorema
//| fig-cap: "Verificação do Teorema da Convolução: a diferença pixel a pixel entre a convolução espacial (cv2.filter2D) e a multiplicação em frequência (FFT) é numericamente nula — confirmando a equivalência teórica."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <iostream>
#include <vector>
#include <cmath>
#include <string>
#include <algorithm>
#include "morph.hpp"

// Helper function to swap quadrants (fftshift equivalent)
void fftShift(cv::Mat& mat) {
    int cx = mat.cols / 2;
    int cy = mat.rows / 2;

    cv::Mat q0(mat, cv::Rect(0, 0, cx, cy));   // Top-Left
    cv::Mat q1(mat, cv::Rect(cx, 0, cx, cy));  // Top-Right
    cv::Mat q2(mat, cv::Rect(0, cy, cx, cy));  // Bottom-Left
    cv::Mat q3(mat, cv::Rect(cx, cy, cx, cy)); // Bottom-Right

    cv::Mat tmp;
    q0.copyTo(tmp);
    q3.copyTo(q0);
    tmp.copyTo(q3);

    q1.copyTo(tmp);
    q2.copyTo(q1);
    tmp.copyTo(q2);
}

int main() {
    // ── Kernel Gaussiano 11×11 
    double sigma = 3.0;
    int K = 11;
    std::vector<double> ks(K);
    for (int i = 0; i < K; i++) {
        ks[i] = i - K / 2;
    }

    std::vector<double> gauss1d(K);
    double sum = 0.0;
    for (int i = 0; i < K; i++) {
        gauss1d[i] = std::exp(-ks[i] * ks[i] / (2 * sigma * sigma));
        sum += gauss1d[i];
    }
    for (int i = 0; i < K; i++) {
        gauss1d[i] /= sum;
    }

    // kernel 2D separável
    cv::Mat kernel = cv::Mat::zeros(K, K, CV_64F);
    for (int i = 0; i < K; i++) {
        for (int j = 0; j < K; j++) {
            kernel.at<double>(i, j) = gauss1d[i] * gauss1d[j];
        }
    }

    // ── Método 1: Convolução espacial direta ─────────────────────────────────────
    cv::Mat img_gray_mat = img_gray;  // mm::Image -> cv::Mat (implicit)
    cv::Mat f_float;
    img_gray_mat.convertTo(f_float, CV_64F);

    cv::Mat conv_esp;
    cv::filter2D(f_float, conv_esp, -1, kernel, cv::Point(-1, -1), 0, cv::BORDER_CONSTANT);

    // ── Método 2: Multiplicação em frequência (via FFT) ──────────────────────────
    int M = f_float.rows;
    int N = f_float.cols;

    // Padding para convolução linear (evita aliasing circular)
    int Mpad = 1;
    while (Mpad < M + K - 1) Mpad <<= 1;
    int Npad = 1;
    while (Npad < N + K - 1) Npad <<= 1;

    // Posiciona o kernel com a origem no (0,0) e padding com zeros
    cv::Mat kernel_pad = cv::Mat::zeros(Mpad, Npad, CV_64F);
    int kh = kernel.rows;
    int kw = kernel.cols;
    cv::Mat kernel_roi = kernel_pad(cv::Rect(0, 0, kw, kh));
    kernel.copyTo(kernel_roi);

    // FFT da imagem
    cv::Mat f_float_padded;
    cv::copyMakeBorder(f_float, f_float_padded, 0, Mpad - M, 0, Npad - N, cv::BORDER_CONSTANT, cv::Scalar(0));

    cv::Mat F_img;
    cv::Mat f_float_padded_32f;
    f_float_padded.convertTo(f_float_padded_32f, CV_32F);
    cv::dft(f_float_padded_32f, F_img, cv::DFT_COMPLEX_OUTPUT);

    // FFT do kernel
    cv::Mat kernel_pad_32f;
    kernel_pad.convertTo(kernel_pad_32f, CV_32F);
    cv::Mat F_kern;
    cv::dft(kernel_pad_32f, F_kern, cv::DFT_COMPLEX_OUTPUT);

    // Multiplicação em frequência
    cv::Mat F_product;
    cv::mulSpectrums(F_img, F_kern, F_product, 0);

    // IFFT
    cv::Mat conv_freq_full;
    cv::idft(F_product, conv_freq_full, cv::DFT_SCALE | cv::DFT_REAL_OUTPUT);

    // Recorte para compensar o deslocamento introduzido pelo posicionamento do kernel
    int offset = K / 2;
    cv::Mat conv_freq_crop = conv_freq_full(cv::Rect(offset, offset, N, M)).clone();

    // ── Verificação numérica ──────────────────────────────────────────────────────
    cv::Mat diff;
    cv::absdiff(conv_esp, conv_freq_crop, diff);

    double max_diff, mean_diff;
    cv::minMaxLoc(diff, nullptr, &max_diff);
    cv::Scalar mean_scalar = cv::mean(diff);
    mean_diff = mean_scalar[0];

    std::cout << "Diferença máxima  (|conv_esp - conv_freq|): " << max_diff << std::endl;
    std::cout << "Diferença média   (|conv_esp - conv_freq|): " << mean_diff << std::endl;
    std::cout << "→ Teorema da Convolução verificado numericamente." << std::endl;

    cv::Mat conv_esp_vis, conv_freq_vis, diff_vis;
    cv::normalize(conv_esp, conv_esp_vis, 0, 255, cv::NORM_MINMAX, CV_8U);
    cv::normalize(conv_freq_crop, conv_freq_vis, 0, 255, cv::NORM_MINMAX, CV_8U);
    cv::normalize(diff, diff_vis, 0, 255, cv::NORM_MINMAX, CV_8U);

    std::vector<mm::Image> to_show = {
        img_gray,
        mm::Image(conv_esp_vis),
        mm::Image(conv_freq_vis),
        mm::Image(diff_vis)
    };

    std::string diff_title = "Diferença (máx=" + std::to_string(max_diff) + ")";

    mm::show(to_show, MM_OUT, 
        {"Original", "Convolução espacial", "Multiplicação em frequência", diff_title},
        4);

    return 0;
}

