// C++ translation of Python morphology pipeline
#include "morph.hpp"
#include <iostream>
#include <vector>
#include <string>

int main() {
    // Variables img_coins_gray is provided as input

    mm::Image img_prep  = mm::equalize(img_coins_gray);
    mm::Image img_bin   = mm::threshold(img_prep);
    mm::Image img_open  = mm::open(img_bin, mm::sedisk(5));
    mm::Image img_hole  = mm::clohole(img_open);
    mm::Image img_limpo = mm::open(img_hole, mm::sedisk(11));
    mm::Image img_final = mm::edgeoff(img_limpo, mm::sebox(), 1);

    mm::show(
        std::vector<mm::Image>{img_prep, img_bin, img_open, img_hole, img_limpo, img_final},
        MM_OUT,
        std::vector<std::string>{"Realçado", "Otsu", "Abertura (r=9)", "clohole", "Abertura (r=33)", "Final (edgeoff)"},
        6
    );

    return 0;
}

