    var btnReset = root.querySelector('#sim_ep0206_btn_reset');

    var w = 300, h = 300;
    var cx = w / 2, cy = h / 2;

    var size = 70;
    var half = size / 2;

    var squarePoints = [
      { x: -half, y: -half },
      { x:  half, y: -half },
      { x:  half, y:  half },
      { x: -half, y:  half }
    ];

