def dil(f, Bc=np.zeros((3,3),dtype='uint8')):
    """Dilation (OpenCV or with weights)."""
    try:    return cv2.dilate(f, Bc)
    except: return mm.dil1(f, Bc)

def dil0(f, Bc=np.zeros((3,3),dtype='uint8')):
    """Flat dilation strictly following the theory."""
    g = np.empty_like(f) 
    Bc = np.flip(Bc)     # explicit reflection: B̂
    for y in range(f.shape[0]):
        for x in range(f.shape[1]):
            g[y,x] = 0 # Initializes with the minimum value to search for the maximum
            for vy,vx,bv in mm._viz(f,Bc,y,x):
                if bv and g[y,x] < f[vy,vx]:
                    g[y,x] = f[vy,vx]
    return g

# Test and Validation Script
