        <button id="sim_ep0204_btnClear" style="padding:5px 10px;font-size:11px;font-weight:600;border:1px solid #e4dcc8;background:#f1ead7;color:#5e5a4a;cursor:pointer;border-radius:8px;white-space:nowrap;transition:all 0.15s ease;">🗑 Limpiar</button>
