//| label: fig-05-conv-teorema
//| fig-cap: "Verification of the Convolution Theorem: the pixel-by-pixel difference between spatial convolution (cv2.filter2D) and frequency multiplication (FFT) is numerically zero — confirming the theoretical equivalence."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <algorithm>
#include "morph.hpp"

#define MM_OUT "fig-05-conv-teorema.png"

// Helper to compute FFT shift (swap quadrants)
void fftShift(cv::Mat& mat) {
    int cx = mat.cols / 2;
    int cy = mat.rows / 2;

    cv::Mat q0(mat, cv::Rect(0, 0, cx, cy));   // Top-Left
    cv::Mat q1(mat, cv::Rect(cx, 0, cx, cy));  // Top-Right
    cv::Mat q2(mat, cv::Rect(0, cy, cx, cy));  // Bottom-Left
    cv::Mat q3(mat, cv::Rect(cx, cy, cx, cy)); // Bottom-Right

    cv::Mat tmp;
    q0.copyTo(tmp);
    q3.copyTo(q0);
    tmp.copyTo(q3);

    q1.copyTo(tmp);
    q2.copyTo(q1);
    tmp.copyTo(q2);
}

// Helper for 2D FFT with padding
void fft2(cv::Mat& src, cv::Mat& dst, int rows, int cols) {
    cv::Mat padded;
    cv::copyMakeBorder(src, padded, 0, rows - src.rows, 0, cols - src.cols, 
                       cv::BORDER_CONSTANT, cv::Scalar::all(0));

    cv::Mat planes[] = {padded, cv::Mat::zeros(padded.size(), CV_64F)};
    cv::Mat complexI;
    cv::merge(planes, 2, complexI);
    cv::dft(complexI, complexI);
    dst = complexI;
}

// Helper for inverse FFT2 returning real part
void ifft2(cv::Mat& src, cv::Mat& dst) {
    cv::Mat inverse;
    cv::idft(src, inverse, cv::DFT_SCALE | cv::DFT_REAL_OUTPUT);
    dst = inverse;
}

int main() {
    // img_gray is provided as a valid mm::Image variable

    // Convert mm::Image to cv::Mat
    cv::Mat img_cv = img_gray;

    // ── Gaussian Kernel 11×11 
    double sigma = 3.0;
    int K = 11;
    cv::Mat ks(1, K, CV_64F);
    for (int i = 0; i < K; i++) {
        ks.at<double>(0, i) = i - K / 2;
    }

    cv::Mat gauss1d(1, K, CV_64F);
    for (int i = 0; i < K; i++) {
        double val = ks.at<double>(0, i);
        gauss1d.at<double>(0, i) = std::exp(-(val * val) / (2 * sigma * sigma));
    }

    // Normalize gauss1d
    double sum = cv::sum(gauss1d)[0];
    gauss1d /= sum;

    // Kernel 2D separable: outer product
    cv::Mat kernel = gauss1d.t() * gauss1d;

    // ── Method 1: Direct spatial convolution ─────────────────────────────────────────
    cv::Mat f_float;
    img_cv.convertTo(f_float, CV_64F);

    cv::Mat conv_esp;
    cv::filter2D(f_float, conv_esp, -1, kernel, cv::Point(-1, -1), 0, cv::BORDER_CONSTANT);

    // ── Method 2: Frequency multiplication (via FFT) ──────────────────────────────────
    int M = f_float.rows;
    int N = f_float.cols;

    // Padding for linear convolution (avoids circular aliasing)
    int Mpad = 1;
    while (Mpad < M + K - 1) Mpad <<= 1;

    int Npad = 1;
    while (Npad < N + K - 1) Npad <<= 1;

    // Position kernel with origin at (0,0) and zero padding
    cv::Mat kernel_pad = cv::Mat::zeros(Mpad, Npad, CV_64F);
    int kh = kernel.rows;
    int kw = kernel.cols;
    kernel_pad(cv::Rect(0, 0, kw, kh)) = kernel.clone();

    // Compute FFTs
    cv::Mat F_img, F_kern;
    fft2(f_float, F_img, Mpad, Npad);
    fft2(kernel_pad, F_kern, Mpad, Npad);

    // Multiply in frequency domain
    cv::Mat F_product;
    cv::mulSpectrums(F_img, F_kern, F_product, 0);

    // Inverse FFT
    cv::Mat conv_freq_full;
    ifft2(F_product, conv_freq_full);

    // Crop to compensate shift introduced by kernel placement
    int offset = K / 2;
    cv::Mat conv_freq_crop = conv_freq_full(cv::Rect(offset, offset, N, M)).clone();

    // ── Numerical verification ─────────────────────────────────────────────────────────
    cv::Mat diff;
    cv::absdiff(conv_esp, conv_freq_crop, diff);

    double minVal, maxVal;
    cv::minMaxLoc(diff, &minVal, &maxVal);
    cv::Scalar meanVal = cv::mean(diff);

    std::cout << "Maximum difference (|conv_esp - conv_freq|): " << maxVal << std::endl;
    std::cout << "Mean difference  (|conv_esp - conv_freq|): " << meanVal[0] << std::endl;
    std::cout << "→ Convolution Theorem verified numerically." << std::endl;

    // Visualization
    cv::Mat conv_esp_vis, conv_freq_vis, diff_vis;
    cv::normalize(conv_esp, conv_esp_vis, 0, 255, cv::NORM_MINMAX, CV_8U);
    cv::normalize(conv_freq_crop, conv_freq_vis, 0, 255, cv::NORM_MINMAX, CV_8U);
    cv::normalize(diff, diff_vis, 0, 255, cv::NORM_MINMAX, CV_8U);

    std::string title_diff = "Difference (max=" + std::to_string(maxVal) + ")";

    mm::show(
        std::vector<mm::Image>{
            mm::Image(img_cv),
            mm::Image(conv_esp_vis),
            mm::Image(conv_freq_vis),
            mm::Image(diff_vis)
        },
        MM_OUT,
        std::vector<std::string>{
            "Original",
            "Spatial convolution",
            "Frequency multiplication",
            title_diff
        },
        4
    );

    return 0;
}

