<style>
  #sim-07-knn * { box-sizing: border-box; margin: 0; padding: 0; }
  #sim-07-knn canvas { display: block; max-width: 100%; height: auto; border-radius: 8px; border: 1px solid #e4dcc8; background: #ffffff; cursor: crosshair; margin: 0 auto; }
