bool downloadFile(const std::string& url, const std::string& filename) {
    std::string command = "curl -s -o " + filename + " " + url;
    int result = std::system(command.c_str());
    if (result == 0 && std::ifstream(filename).good()) {
        std::cout << "✅ Fichier téléchargé: " << filename << std::endl;
        return true;
    }
    std::cout << "❌ Erreur: Non trouvé" << std::endl;
    return false;
}

int main() {
    // Vérifier si le fichier existe déjà
    std::ifstream fileCheck(file);
    if (!fileCheck.good()) {
        std::string url = BASE_URL + "/" + file;
        downloadFile(url, file);
    }
    return 0;
}

