#include "morph.hpp"
#include <iostream>
#include <cmath>

int main() {
    // img_gray est déjà initialisé comme variable valide

    // Patch 5x5
    mm::Image patch(5, 5);
    for (int y = 0; y < 5; ++y) {
        for (int x = 0; x < 5; ++x) {
            patch.at(y, x) = img_gray.at(250 + y, 250 + x);
        }
    }

    // Convertir en float (comme astype(np.float32))
    float p[5][5];
    for (int y = 0; y < 5; ++y) {
        for (int x = 0; x < 5; ++x) {
            p[y][x] = static_cast<float>(patch.at(y, x));
        }
    }

    // Gx au pixel [1,1] : colonne droite - colonne gauche (pondéré)
    float gx = (p[0][2] + 2*p[1][2] + p[2][2]) - (p[0][0] + 2*p[1][0] + p[2][0]);

    // Gy au pixel [1,1] : ligne inférieure - ligne supérieure (pondéré)
    float gy = (p[2][0] + 2*p[2][1] + p[2][2]) - (p[0][0] + 2*p[0][1] + p[0][2]);

    float mag   = std::sqrt(gx*gx + gy*gy);
    float theta = std::atan2(gy, gx) * 180.0f / M_PI;

    std::cout << "Patch 5x5:" << std::endl;
    std::cout << mm::drawImg(patch) << std::endl;
    std::cout << "Gx en [1,1] : (" << static_cast<int>(p[0][2]) << " + 2*" 
              << static_cast<int>(p[1][2]) << " + " << static_cast<int>(p[2][2]) 
              << ") - (" << static_cast<int>(p[0][0]) << " + 2*" 
              << static_cast<int>(p[1][0]) << " + " << static_cast<int>(p[2][0]) 
              << ") = " << gx << std::endl;
    std::cout << "Gy en [1,1] : (" << static_cast<int>(p[2][0]) << " + 2*" 
              << static_cast<int>(p[2][1]) << " + " << static_cast<int>(p[2][2]) 
              << ") - (" << static_cast<int>(p[0][0]) << " + 2*" 
              << static_cast<int>(p[0][1]) << " + " << static_cast<int>(p[0][2]) 
              << ") = " << gy << std::endl;

    // Remplace | par préfixe mag pour ne pas casser l'interpréteur de tableaux de Quarto
    std::cout << "mag(Grad f)  = sqrt(" << gx << "^2 + " << gy << "^2) = " 
              << mag << std::endl;
    std::cout << "Theta        = arctan(" << gy << "/" << gx << ") = " 
              << theta << " degrés" << std::endl;

    return 0;
}

