#include <iostream>
#include <string>
#include <vector>
#include <utility>
#include <functional>

// Simuler l'utilisation de la mémoire (approximation simple)
// tracemalloc n'a pas d'équivalent direct en C++, on utilise une estimation
size_t mem_usage = 0;
void start_tracing() { mem_usage = 0; }
std::pair<size_t, size_t> get_traced_memory() { return {0, mem_usage}; }
void stop_tracing() {}

std::vector<std::pair<int, int>> lista(int n) {
    std::vector<std::pair<int, int>> result;
    result.reserve(n);
    for (int i = 0; i < n; ++i) {
        result.emplace_back(i, i);
    }
    return result;
}

// Version avec générateur - pas de générateurs natifs en C++, 
// on simule avec un itérateur personnalisé
struct GeraIterator {
    int current;
    int n;
    GeraIterator(int n) : current(0), n(n) {}
    std::pair<int, int> operator*() const { return {current, current}; }
    GeraIterator& operator++() { ++current; return *this; }
    bool operator!=(const GeraIterator& other) const { return current != other.n; }
};
struct Gera {
    int n;
    Gera(int n) : n(n) {}
    GeraIterator begin() const { return GeraIterator(0); }
    GeraIterator end() const { return GeraIterator(n); }
};

int main() {
    std::vector<std::pair<std::string, std::function<std::pair<int, int>()>>> tests;
    // Version avec vecteur
    auto list_test = [&]() -> std::pair<int, int> {
        start_tracing();
        long long sum = 0;
        auto v = lista(9000000);
        mem_usage = v.size() * sizeof(std::pair<int, int>);
        for (const auto& p : v) {
            sum += p.first + p.second;
        }
        auto mem = get_traced_memory();
        stop_tracing();
        return {static_cast<int>(sum), mem.second};
    };

    // Version avec "générateur" (itérateur)
    auto gen_test = [&]() -> std::pair<int, int> {
        start_tracing();
        long long sum = 0;
        Gera g(9000000);
        mem_usage = 0; // pas de stockage complet
        for (auto it = g.begin(); it != g.end(); ++it) {
            auto p = *it;
            sum += p.first + p.second;
        }
        auto mem = get_traced_memory();
        stop_tracing();
        return {static_cast<int>(sum), mem.second};
    };

    tests = {{"LISTA", list_test}, {"YIELD", gen_test}};

    for (const auto& test : tests) {
        auto result = test.second();
        std::cout << test.first << ": " << result.second / 1048576.0 << " MB" << std::endl;
    }
    return 0;
}

