int main() {
    // Exemplo numérico: média vs. mediana com pixel corrompido
    std::vector<int> vizinhanca = {102, 98, 105, 100, 255, 97, 103, 99, 101};

    std::vector<int> ordenado = vizinhanca;
    std::sort(ordenado.begin(), ordenado.end());

    std::cout << "Vizinhança: [";
    for (size_t i = 0; i < ordenado.size(); ++i) {
        std::cout << ordenado[i];
        if (i < ordenado.size() - 1) std::cout << ", ";
    }
    std::cout << "]\n";

    // Cálculo da média
    double soma = std::accumulate(vizinhanca.begin(), vizinhanca.end(), 0.0);
    double media = soma / vizinhanca.size();
    std::cout << "Média:      " << media << "  (deslocada pelo outlier 255)\n";

    // Cálculo da mediana (os dados já estão ordenados)
    int mediana = ordenado[ordenado.size() / 2];
    std::cout << "Mediana:    " << mediana << "    (ignora o outlier)\n";

    std::cout << "Valor original:  ~100\n";

    return 0;
}

