// Function to check if a file exists
bool fileExists(const std::string& path) {
    struct stat buffer;
    return (stat(path.c_str(), &buffer) == 0);
}

// Simplified download function (requires libcurl or implement with system calls)
bool downloadFile(const std::string& url, const std::string& path) {
    std::string command = "cd $(dirname " + path + ") && curl -L -o $(basename " + path + ") \"" + url + "\"";
    int result = system(command.c_str());
    return result == 0;
}

int main() {
    std::string barcode_path = "dados/barcode.png";
    std::string url_github = 
        "https://raw.githubusercontent.com/fzampirolli/"
        "pdi-vc/master/all/cap06/dados/barcode.png";

    // If file doesn't exist locally, download automatically from GitHub
    if (!fileExists(barcode_path)) {
        std::cout << "[DOWNLOAD] Downloading barcode from GitHub: " << url_github << "\n";
        // Create directory if needed
        std::string dir = "dados";
        std::string mkdir_cmd = "mkdir -p " + dir;
        system(mkdir_cmd.c_str());

        if (downloadFile(url_github, barcode_path)) {
            std::cout << "[DOWNLOAD] Image downloaded successfully!\n";
        } else {
            std::cout << "[DOWNLOAD] Failed to download the file\n";
        }
    }

    mm::Image image;
    if (fileExists(barcode_path)) {
        image = mm::read(barcode_path);
    } else {
        // Synthetic fallback: generates a vertical bar pattern simulating Code-128
        std::cout << "[WARNING] File 'dados/barcode.png' not found.\n";
        std::cout << "        Using synthetic image for pipeline demonstration.\n";
        int h = 100, w = 400;
        mm::Image img_synth(h, w);
        std::fill(img_synth.data.begin(), img_synth.data.end(), 255);
        // Dark bars in regular positions (simplified pattern)
        for (int x = 20; x < w - 20; x += 8) {
            if ((x / 8) % 3 != 0) {
                for (int y = 0; y < h; y++) {
                    for (int dx = 0; dx < 4; dx++) {
                        if (x + dx < w) {
                            img_synth.at(y, x + dx) = 0;
                        }
                    }
                }
            }
        }
        image = img_synth;
    }

    mm::show(image, MM_OUT);

