// 1. Loading and preprocessing of data
// In C++ we don't have scikit-learn or PyTorch equivalents,
// so we simulate with a small sample dataset.
// For this example, we'll create a small synthetic dataset of 8x8 digit-like images.

// Generate synthetic digit images (8x8) - just for demonstration
std::vector<mm::Image> generate_synthetic_digits(int n) {
    std::vector<mm::Image> digits;
    std::mt19937 rng(42);
    std::uniform_int_distribution<int> dist(0, 15);

    for (int i = 0; i < n; i++) {
        mm::Image img(8, 8);
        for (int y = 0; y < 8; y++) {
            for (int x = 0; x < 8; x++) {
                img.at(y, x) = dist(rng);  // Random pixel values 0-15
            }
        }
        digits.push_back(img);
    }
    return digits;
}

int main() {
    // In this C++ translation, we need to simulate the digit dataset
    // since scikit-learn and PyTorch aren't available.
    // We'll create a small synthetic dataset for demonstration.

    int n_samples = 70;  // Simulated total samples
    std::vector<mm::Image> X = generate_synthetic_digits(n_samples);
    std::vector<int> y(n_samples);

    // Assign synthetic labels (alternating digits)
    for (int i = 0; i < n_samples; i++) {
        y[i] = i % 10;  // Digits 0-9
    }

    // Normalization to range [0, 1] isn't needed for mm::Image (uint8)
    // since we're working with integer pixel values 0-15

    // Train/test split (70/30) - in C++ we'll just take first 70% for training
    int train_size = static_cast<int>(n_samples * 0.7);

    std::vector<mm::Image> X_treino(X.begin(), X.begin() + train_size);
    std::vector<mm::Image> X_teste(X.begin() + train_size, X.end());
    std::vector<int> y_treino(y.begin(), y.begin() + train_size);
    std::vector<int> y_teste(y.begin() + train_size, y.end());

    // Generate a sample to display
