def dil(f, Bc=np.zeros((3,3),dtype='uint8')):
    """Dilatación (OpenCV o con pesos)."""
    try:    return cv2.dilate(f, Bc)
    except: return mm.dil1(f, Bc)

def dil0(f, Bc=np.zeros((3,3),dtype='uint8')):
    """Dilatación plana siguiendo rigurosamente la teoría."""
    g = np.empty_like(f) 
    Bc = np.flip(Bc)     # reflexión explícita: B̂
    for y in range(f.shape[0]):
        for x in range(f.shape[1]):
            g[y,x] = 0 # Inicializa con el valor mínimo para buscar el máximo
            for vy,vx,bv in mm._viz(f,Bc,y,x):
                if bv and g[y,x] < f[vy,vx]:
                    g[y,x] = f[vy,vx]
    return g

# Script de Prueba y Validación
