    <label style="font-size:11px;font-weight:600;white-space:nowrap;">Elemento estructurante — sebox(<span id="qr_kVal">1</span>):</label>
      <input type="range" id="qr_kSlider" min="0" max="3" step="1" value="1" style="width:140px;">
