void contarShapes(const fs::path& raiz, const std::vector<std::string>& splits = {"train", "valid", "test"}) {
    /* Compte les formes (hauteur, largeur, canaux) des images par split. */
    for (const auto& split : splits) {
        fs::path pasta = raiz / split / "images";
        if (!fs::exists(pasta)) {
            std::cout << split << ": pasta não encontrada" << std::endl;
            continue;
        }

        // map pour compter les occurrences de chaque forme
        std::map<std::string, int> shapes; // clé: "heightxwidthxchannels"

        for (const auto& arquivo : fs::directory_iterator(pasta)) {
            if (fs::is_regular_file(arquivo.path())) {
                RGB img = getImageDimensions(arquivo.path());
                std::string key = std::to_string(img.height) + "x" + 
                                 std::to_string(img.width) + "x" + 
                                 std::to_string(img.channels);
                shapes[key]++;
            }
        }

        // Construire la chaîne de sortie
        std::string txt;
        bool first = true;
        for (const auto& [shape, count] : shapes) {
            if (!first) txt += ", ";
            txt += shape + ": " + std::to_string(count);
            first = false;
        }
        std::cout << split << ": " << txt << std::endl;
    }
}

