//| label: fig-05-ssim-artefatos
//| fig-cap: "Análise espacial de degradação: imagens reconstruídas e respectivos mapas de erro absoluto normalizados para diferentes fatores de qualidade JPEG."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <vector>
#include <string>
#include <cmath>
#include <cstdio>
#include "morph.hpp"

// Função SSIM (Wang et al.) com janela gaussiana
double ssim_full(const cv::Mat& img1, const cv::Mat& img2, cv::Mat& ssim_map) {
    const double C1 = 6.5025, C2 = 58.5225;
    cv::Mat I1, I2;
    img1.convertTo(I1, CV_64F);
    img2.convertTo(I2, CV_64F);

    cv::Mat I1_2 = I1.mul(I1);
    cv::Mat I2_2 = I2.mul(I2);
    cv::Mat I1_I2 = I1.mul(I2);

    cv::Mat mu1, mu2;
    cv::GaussianBlur(I1, mu1, cv::Size(11, 11), 1.5);
    cv::GaussianBlur(I2, mu2, cv::Size(11, 11), 1.5);

    cv::Mat mu1_2 = mu1.mul(mu1);
    cv::Mat mu2_2 = mu2.mul(mu2);
    cv::Mat mu1_mu2 = mu1.mul(mu2);

    cv::Mat sigma1_2, sigma2_2, sigma12;
    cv::GaussianBlur(I1_2, sigma1_2, cv::Size(11, 11), 1.5);
    sigma1_2 -= mu1_2;
    cv::GaussianBlur(I2_2, sigma2_2, cv::Size(11, 11), 1.5);
    sigma2_2 -= mu2_2;
    cv::GaussianBlur(I1_I2, sigma12, cv::Size(11, 11), 1.5);
    sigma12 -= mu1_mu2;

    cv::Mat t1, t2, t3;
    cv::Mat ssim_map_t;
    t1 = 2 * mu1_mu2 + C1;
    t2 = 2 * sigma12 + C2;
    t3 = t1.mul(t2);
    cv::divide(t3, (mu1_2 + mu2_2 + C1).mul(sigma1_2 + sigma2_2 + C2), ssim_map_t);

    cv::Scalar mssim = cv::mean(ssim_map_t);
    ssim_map = ssim_map_t;
    return mssim[0];
}

int main() {
    // Cameraman (asset do capítulo), 256x256 — mesma imagem da trilha py.
    cv::Mat img_cv = cv::imread("imagens/cameraman.png", cv::IMREAD_GRAYSCALE);
    if (img_cv.empty()) {
        return 1;
    }
    cv::resize(img_cv, img_cv, cv::Size(256, 256));
    mm::Image img_gray;
    cv::Mat img_gray_mat = img_gray;
    img_gray = mm::Image(img_cv);

    std::vector<mm::Image> imgs_ssim;
    std::vector<std::string> titles_ssim;
    imgs_ssim.push_back(img_gray);
    titles_ssim.push_back("Original");

    int qs[] = {25, 50, 75, 95};
    for (int idx = 0; idx < 4; idx++) {
        int q = qs[idx];
        mm::Image rec = mm::jpegCompress(img_gray, q);  // DCT 8x8 -> quant -> IDCT
        double psnr_v = mm::psnr(img_gray, rec);

        cv::Mat img_gray_cv = img_gray;
        cv::Mat rec_cv = rec;
        cv::Mat ssim_map;
        double ssim_v = ssim_full(img_gray_cv, rec_cv, ssim_map);

        cv::Mat diff, diff_vis_cv;
        cv::absdiff(img_gray_cv, rec_cv, diff);
        cv::normalize(diff, diff_vis_cv, 0, 255, cv::NORM_MINMAX, CV_8U);
        mm::Image diff_vis = diff_vis_cv;

        imgs_ssim.push_back(rec);
        imgs_ssim.push_back(diff_vis);

        char title1[256], title2[256];
        snprintf(title1, sizeof(title1), "Q=%d (PSNR=%.1fdB | SSIM=%.3f)", q, psnr_v, ssim_v);
        snprintf(title2, sizeof(title2), "Mapa de erro (Q=%d) - bordas e blocagem", q);
        titles_ssim.push_back(std::string(title1));
        titles_ssim.push_back(std::string(title2));
    }

    mm::show(imgs_ssim, MM_OUT, titles_ssim, 3);
    return 0;
}

