        <div style="width:18px;height:18px;background:#fbeaf0;border:1.5px solid #c0392b;border-radius:3px;"></div>
        <span style="font-size:10.5px;color:#5e5a4a;">Maschera Positiva/Negativa</span>
      </div>
    </div>

