//| label: fig-04-componentes
//| fig-cap: "Componentes conexos após o *pipeline* de segmentação, rotulados por `mm::label0`. A tabela lista área e caixa de cada objeto. (Cores aleatórias e texto sobre a imagem ficam na trilha Python.)"
//| echo: true
//| output: true

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <numeric>
#include <set>
#include "morph.hpp"

int main() {
    mm::Image lab = mm::label0(img_final, mm::sebox());

    // Find max label value
    int n = 0;
    for (unsigned char v : lab.data) {
        if ((int)v > n) n = (int)v;
    }

    int H = lab.h;
    int W = lab.w;

    std::cout << "Componentes detectados: " << n << "\n";
    std::cout << "  ID" << "      Área" << "     x0" << "     y0" << "      w" << "      h" << "\n";
    std::cout << "----------------------------------------\n";

    for (int k = 1; k <= n; k++) {
        int area = 0; 
        int x0 = W; 
        int y0 = H; 
        int x1 = 0; 
        int y1 = 0;

        for (int y = 0; y < H; y++) {
            for (int x = 0; x < W; x++) {
                if ((int)lab.at(y, x) == k) {
                    area++;
                    if (x < x0) x0 = x;
                    if (x > x1) x1 = x;
                    if (y < y0) y0 = y;
                    if (y > y1) y1 = y;
                }
            }
        }

        std::cout << std::setw(4) << k 
                  << std::setw(8) << area 
                  << std::setw(6) << x0 
                  << std::setw(6) << y0 
                  << std::setw(6) << (x1 - x0 + 1) 
                  << std::setw(6) << (y1 - y0 + 1) << "\n";
    }

    mm::Image lab_vis = lab;
    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            if (lab_vis.at(y, x)) {
                lab_vis.at(y, x) = (unsigned char)((int)lab_vis.at(y, x) * 255 / std::max(n, 1));
            }
        }
    }

    mm::show({img_coins_gray, img_final, lab_vis},
             MM_OUT,
             {"Original", "Segmentação Final", "Componentes (mm.label0)"}, 3);

    return 0;
}

