      var LL = [], LH = [], HL = [], HH = [];
      for (var r = 0; r < halfH; r++) {
        LL.push(new Array(halfW));
        LH.push(new Array(halfW));
        HL.push(new Array(halfW));
        HH.push(new Array(halfW));
      }

      for(var r=0; r<halfH; r++){
        for(var c=0; c<halfW; c++){
          var a = m[2*r][2*c];
          var b = m[2*r][2*c+1];
          var g = m[2*r+1][2*c];
          var d = m[2*r+1][2*c+1];

          LL[r][c] = (a + b + g + d) / 2.0;
          LH[r][c] = (a - b + g - d) / 2.0;
          HL[r][c] = (a + b - g - d) / 2.0;
          HH[r][c] = (a - b - g + d) / 2.0;
