      var pcts = bars.map(function(b){ return b/total*100; });

      var pad = {l:34, r:10, t:12, b:24};
      var plotH = s.height - pad.t - pad.b;
      var plotW = w - pad.l - pad.r;

      ctx.strokeStyle = 'rgba(0,0,0,.06)'; ctx.lineWidth=0.5;
      for(var j=0;j<=4;j++){
