      ctx.fillStyle = '#8a8371'; ctx.font='9.5px monospace'; ctx.textAlign='right';
      for(var j=0;j<=4;j++){
        var y = pad.t + plotH*j/4;
        ctx.fillText(Math.round(100 - j*25) + '%', pad.l-4, y+3);
      }

      var bw = plotW/pcts.length;
      var barW = bw*0.6;
