    std::vector<int> viz_orig, viz_corr;
    for (int y = 0; y < 3; y++) {
        for (int x = 0; x < 3; x++) {
            viz_orig.push_back((int)patch.at(y, x));
            viz_corr.push_back((int)corrompido.at(y, x));
        }
    }
    std::sort(viz_orig.begin(), viz_orig.end());
    std::sort(viz_corr.begin(), viz_corr.end());

    std::cout << "Patch original:\n";
    std::cout << mm::drawImg(patch);
    std::cout << "\nPatch com pixel corrompido [1,1]=255:\n";
    std::cout << mm::drawImg(corrompido);

    std::cout << "\nVizinhança 3×3 original (ordenada):   ";
    for (int v : viz_orig) std::cout << v << " ";
    std::cout << "\nMediana original:                       " << viz_orig[4] << "\n";

    std::cout << "\nVizinhança 3×3 corrompida (ordenada): ";
    for (int v : viz_corr) std::cout << v << " ";
    std::cout << "\nMediana corrompida:                     " << viz_corr[4] << "  ← ignora o 255\n";

