      <button id="sim_ep0103_sc2" style="padding:6px 12px;font-size:11px;font-weight:600;border:1px solid #e4dcc8;background:#f1ead7;color:#5e5a4a;cursor:pointer;border-radius:9px;white-space:nowrap;transition:all 0.15s ease;">Détecteur quasi parfait</button>
      <button id="sim_ep0103_sc3" style="padding:6px 12px;font-size:11px;font-weight:600;border:1px solid #e4dcc8;background:#f1ead7;color:#5e5a4a;cursor:pointer;border-radius:9px;white-space:nowrap;transition:all 0.15s ease;">Détecteur aléatoire</button>
      <button id="sim_ep0103_sc4" style="padding:6px 12px;font-size:11px;font-weight:600;border:1px solid #e4dcc8;background:#f1ead7;color:#5e5a4a;cursor:pointer;border-radius:9px;white-space:nowrap;transition:all 0.15s ease;">Beaucoup de faux positifs</button>
    </div>

    <!-- Grid Principal: Entradas | Resultados -->
    <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(280px, 1fr));gap:16px;">

      <!-- Coluna Esquerda: Tabela Editável de Amostras -->
      <div style="background:#fafaf7;border:1px solid #e9e3d3;border-radius:12px;padding:12px;">
        <div style="font-size:9.5px;font-weight:700;color:#8a8371;margin-bottom:10px;letter-spacing:.3px;">ÉCHANTILLONS (CLASSE RÉELLE | CONFIANCE)</div>

        <div style="display:grid;grid-template-columns:28px 1fr 1fr 24px;gap:4px;margin-bottom:6px;font-size:10px;font-weight:700;color:#5e5a4a;text-align:center;">
          <span>#</span>
