        </div>

        <!-- Lista de Amostras Gerada via JS -->
        <div id="sim_ep0103_rows" style="display:flex;flex-direction:column;gap:6px;max-height:260px;overflow-y:auto;padding-right:2px;"></div>

        <!-- Botão Adicionar -->
        <button id="sim_ep0103_add" style="margin-top:10px;width:100%;font-size:11px;font-weight:700;padding:6px 0;border-radius:8px;border:1px dashed #b8b09d;background:#f1ead7;color:#26241d;cursor:pointer;">+ Ajouter un échantillon</button>

        <div style="border-top:1px solid #e4dcc8;margin:12px 0;"></div>

        <!-- Controle de Limiar -->
        <div style="font-size:9.5px;font-weight:700;color:#8a8371;margin-bottom:6px;letter-spacing:.3px;">SEUIL POUR MÉTRIQUES INDIVIDUELLES</div>
        <div style="display:flex;align-items:center;gap:8px;">
          <input type="range" id="sim_ep0103_thr" min="0" max="10" value="9" step="1" style="flex:1;cursor:pointer;">
          <span id="sim_ep0103_thr_val" style="font-size:12px;font-family:monospace;font-weight:700;min-width:36px;text-align:right;color:#26241d;">0.85</span>
        </div>
        <div style="font-size:9px;color:#8a8371;margin-top:4px;font-family:monospace;text-align:center;">Seuils : 0.00 · 0.09 · 0.21 · 0.31 · 0.39 · 0.52 · 0.60 · 0.71 · 0.81 · 0.89 · 1.00</div>
      </div>

      <!-- Coluna Direita: Métricas + Gráfico P-S -->
      <div style="display:flex;flex-direction:column;gap:12px;">

        <!-- Matriz de Confusão e Métricas no Limiar -->
        <div style="background:#fafaf7;border:1px solid #e9e3d3;border-radius:12px;padding:12px;">
          <div style="font-size:9.5px;font-weight:700;color:#8a8371;margin-bottom:8px;letter-spacing:.3px;">
            MÉTRIQUES AU SEUIL <span id="sim_ep0103_thr_label" style="color:#26241d;font-family:monospace;">0.85</span>
          </div>

          <!-- Matriz Compacta -->
          <div style="display:grid;grid-template-columns:auto 1fr 1fr;gap:4px;align-items:center;font-family:monospace;font-size:10px;margin-bottom:10px;">
            <div></div>
            <div style="text-align:center;font-weight:700;color:#5e5a4a;padding:2px;">Préd +</div>
            <div style="text-align:center;font-weight:700;color:#5e5a4a;padding:2px;">Préd −</div>

            <div style="font-weight:700;color:#5e5a4a;text-align:right;padding-right:4px;">Réel +</div>
