};

cv::Mat Q_luma(8, 8, CV_64F, const_cast<double*>(Q_luma_data));

// Helper para DCT-II 2D (separável) usando cv::dct
cv::Mat dct2(const cv::Mat& bloco) {
    cv::Mat bloco_float;
    bloco.convertTo(bloco_float, CV_64F);
    cv::Mat temp;
    cv::dct(bloco_float, temp);  // DCT nas linhas
    cv::Mat transposed = temp.t();
    cv::Mat temp2;
    cv::dct(transposed, temp2); // DCT nas colunas
    return temp2.t();
}

// Helper para IDCT-II 2D
cv::Mat idct2(const cv::Mat& coefs) {
    cv::Mat temp;
    cv::idct(coefs, temp);  // IDCT nas linhas
    cv::Mat transposed = temp.t();
    cv::Mat temp2;
    cv::idct(transposed, temp2); // IDCT nas colunas
    return temp2.t();
}

// Função para comprimir bloco 8x8: DCT -> quantização -> dequantização -> IDCT
cv::Mat jpeg_compress_block(const cv::Mat& bloco, const cv::Mat& Q_table) {
    cv::Mat bloco_float;
    bloco.convertTo(bloco_float, CV_64F);

    // Subtrai 128 para centrar em torno de zero
    cv::Mat bloco_centralizado = bloco_float - 128.0;

    // DCT
    cv::Mat C = dct2(bloco_centralizado);

    // Quantização e dequantização
    cv::Mat Cq;
    cv::divide(C, Q_table, Cq);
    cv::Mat Cq_rounded;
    cv::Mat(Cq).convertTo(Cq_rounded, CV_64F);
    // Arredondamento manual
    for (int i = 0; i < Cq_rounded.rows; i++) {
        for (int j = 0; j < Cq_rounded.cols; j++) {
            Cq_rounded.at<double>(i, j) = std::round(Cq_rounded.at<double>(i, j));
        }
    }
    cv::multiply(Cq_rounded, Q_table, Cq_rounded);

    // IDCT e reconstrução
    cv::Mat reconstruido = idct2(Cq_rounded);
    reconstruido += 128.0;

    // Clip entre 0 e 255
    cv::Mat resultado;
    cv::max(reconstruido, 0.0, resultado);
    cv::min(resultado, 255.0, resultado);

    cv::Mat resultado_uint8;
    resultado.convertTo(resultado_uint8, CV_8U);
    return resultado_uint8;
}

// Função para compressão JPEG simplificada da imagem inteira em blocos 8x8
cv::Mat jpeg_quality_compress(const cv::Mat& img, int qualidade = 50) {
    double escala;
    if (qualidade < 50) {
        escala = 5000.0 / qualidade;
    } else {
        escala = 200.0 - 2.0 * qualidade;
    }

    // Calcula a tabela de quantização escalada
    cv::Mat Q_escalada = Q_luma * (escala / 100.0);
    cv::Mat Q_clip;
    cv::max(Q_escalada, 1.0, Q_clip);
    cv::min(Q_clip, 255.0, Q_clip);

    int h = img.rows, w = img.cols;
    cv::Mat resultado = cv::Mat::zeros(h, w, CV_8U);

    for (int r = 0; r <= h - 8; r += 8) {
        for (int c = 0; c <= w - 8; c += 8) {
            cv::Mat bloco = img(cv::Rect(c, r, 8, 8)).clone();
            cv::Mat bloco_comprimido = jpeg_compress_block(bloco, Q_clip);
            bloco_comprimido.copyTo(resultado(cv::Rect(c, r, 8, 8)));
        }
    }
    return resultado;
}

int main() {
    // Carregar imagem Cameraman (inerente ao OpenCV não tem, então criamos uma aproximação)
    cv::Mat img_gray = cv::imread("cameraman.png", cv::IMREAD_GRAYSCALE);

    // Se não carregar, gerar uma imagem sintética de teste (gradiente com textura)
    if (img_gray.empty()) {
        img_gray = cv::Mat::zeros(256, 256, CV_8U);
        for (int i = 0; i < 256; i++) {
            for (int j = 0; j < 256; j++) {
                // Padrão que se aproxima de uma imagem de teste
                img_gray.at<uchar>(i, j) = static_cast<uchar>(
                    (i + j) / 2 + 50 * std::sin(i * 0.1) * std::cos(j * 0.1) + 100
                );
            }
        }
    }

    // Redimensiona levemente para 256x256 para manter o padrão
    cv::resize(img_gray, img_gray, cv::Size(256, 256));

    // Comparação de fatores de qualidade
    std::vector<int> qualidades = {10, 25, 50, 75, 90};
    std::vector<cv::Mat> imgs_jpeg;
    std::vector<std::string> titles_jpeg;

    imgs_jpeg.push_back(img_gray);
    titles_jpeg.push_back("Original\n(Cameraman)");

    for (int q : qualidades) {
        cv::Mat rec = jpeg_quality_compress(img_gray, q);
        double psnr = cv::PSNR(img_gray, rec);
        imgs_jpeg.push_back(rec);
        titles_jpeg.push_back("Q=" + std::to_string(q) + "\nPSNR=" + 
                             std::to_string(psnr).substr(0, 4) + "dB");
    }

    // Criar imagem composta para visualização
    int cols = 3;
    int rows = (imgs_jpeg.size() + cols - 1) / cols;
    int cell_w = 256, cell_h = 256;
    int gap = 20;
    int label_h = 30;

    cv::Mat display = cv::Mat::zeros(rows * (cell_h + label_h) + (rows - 1) * gap, 
                                    cols * (cell_w + gap), CV_8U);

    for (size_t i = 0; i < imgs_jpeg.size(); i++) {
        int r = i / cols;
        int c = i % cols;
        int y = r * (cell_h + label_h) + r * gap;
        int x = c * (cell_w + gap);

        // Copiar imagem
        cv::Mat roi = display(cv::Rect(x, y, cell_w, cell_h));
        cv::resize(imgs_jpeg[i], roi, cv::Size(cell_w, cell_h));

        // Desenhar borda
        cv::rectangle(display, cv::Rect(x, y, cell_w, cell_h), cv::Scalar(200), 1);

        // Adicionar título
        if (i < titles_jpeg.size()) {
            cv::putText(display, titles_jpeg[i], 
                       cv::Point(x + 10, y + cell_h + 20),
                       cv::FONT_HERSHEY_SIMPLEX, 0.5, cv::Scalar(255), 1);
        }
    }

    // Salvar resultado
    cv::imwrite("fig-05-jpeg-pipeline.png", display);

    return 0;
}

