              cr.style.transform = 'scale(1)';
              cr.style.boxShadow = 'none';
              cr.style.background = 'rgb(' + resVal + ',' + resVal + ',' + resVal + ')';
              cr.style.color = textColor(resVal);
              resetDebug();
              resetVector();
            });
          })(r, c, res);
        }
        gridRes.appendChild(cr);
