//| label: fig-05-pipeline-denoising
//| fig-cap: "*Pipeline* completo de remoção de ruído misto: (1) adição de ruído gaussiano e periódico; (2) identificação de picos de interferência no espectro de frequências; (3) aplicação de máscara *notch* com atenuação gaussiana suave; (4) pós-processamento via filtro bilateral para eliminação do ruído estocástico residual."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <iostream>
#include <cmath>
#include <vector>
#include <string>
#include <random>
#include "morph.hpp"

// Função para suprimir pico gaussiano na máscara
cv::Mat suprimir_pico_gaussiano(const cv::Mat& mask, int cy, int cx, double sigma = 3.0) {
    int h = mask.rows, w = mask.cols;
    cv::Mat notch = cv::Mat::zeros(h, w, CV_64F);

    for (int y = 0; y < h; ++y) {
        for (int x = 0; x < w; ++x) {
            double dist2 = (y - cy) * (y - cy) + (x - cx) * (x - cx);
            notch.at<double>(y, x) = std::exp(-dist2 / (2 * sigma * sigma));
        }
    }

    cv::Mat result;
    cv::multiply(mask, 1.0 - notch, result);
    return result;
}

cv::Mat mm_fft_shift(const cv::Mat& input) {
    cv::Mat output;
    int cx = input.cols / 2;
    int cy = input.rows / 2;

    cv::Mat q0(input, cv::Rect(0, 0, cx, cy));   // Top-Left - create a ROI per quadrant
    cv::Mat q1(input, cv::Rect(cx, 0, cx, cy));  // Top-Right
    cv::Mat q2(input, cv::Rect(0, cy, cx, cy));  // Bottom-Left
    cv::Mat q3(input, cv::Rect(cx, cy, cx, cy)); // Bottom-Right

    cv::Mat tmp;
    q0.copyTo(tmp);
    q3.copyTo(q0);
    tmp.copyTo(q3);

    q1.copyTo(tmp);
    q2.copyTo(q1);
    tmp.copyTo(q2);

    return input;
}

int main() {
    // Cameraman (asset do capítulo), 256x256 — mesma imagem da trilha py.
    cv::Mat img_gray_mat = cv::imread("imagens/cameraman.png", cv::IMREAD_GRAYSCALE);
    cv::resize(img_gray_mat, img_gray_mat, cv::Size(256, 256));
    mm::Image img_gray_mm = img_gray_mat;  // Conversão implícita
    // Se precisar do mm::Image, converter de cv::Mat
    // Se img_gray for mm::Image, acesse .h e .w; caso contrário use .rows e .cols
    mm::Image img_gray = img_gray_mm;  // Manter nome original
    int h_img, w_img;
    // Se for mm::Image
    h_img = img_gray.h;
    w_img = img_gray.w;

    // ── 1. Ruído misto: gaussiano + periódico ───────────────────────────────────
    cv::RNG rng(42);

    // Criar meshgrid X2, Y2
    cv::Mat X2 = cv::Mat::zeros(h_img, w_img, CV_64F);
    cv::Mat Y2 = cv::Mat::zeros(h_img, w_img, CV_64F);
    for (int y = 0; y < h_img; ++y) {
        for (int x = 0; x < w_img; ++x) {
            X2.at<double>(y, x) = x;
            Y2.at<double>(y, x) = y;
        }
    }

    double u0 = 15, v0 = 10;
    // Ruído gaussiano
    cv::Mat ruido_gauss(h_img, w_img, CV_64F);
    rng.fill(ruido_gauss, cv::RNG::NORMAL, 0, 15);

    // Ruído periódico
    cv::Mat ruido_period(h_img, w_img, CV_64F);
    for (int y = 0; y < h_img; ++y) {
        for (int x = 0; x < w_img; ++x) {
            ruido_period.at<double>(y, x) = 30 * std::sin(2 * M_PI * (u0 * x / w_img + v0 * y / h_img));
        }
    }

    // Imagem ruidosa: converter img_gray para float e somar ruídos
    cv::Mat img_gray_float;
    img_gray_mat.convertTo(img_gray_float, CV_64F);

    cv::Mat img_noisy_float = img_gray_float + ruido_gauss + ruido_period;
    cv::Mat img_noisy;
    cv::threshold(img_noisy_float, img_noisy_float, 0, 255, cv::THRESH_TRUNC);  // clip superior
    cv::threshold(img_noisy_float, img_noisy_float, 0, 255, cv::THRESH_TOZERO); // clip inferior
    img_noisy_float.convertTo(img_noisy, CV_8U);

    // ── 2. Espectro (log-magnitude) da imagem ruidosa ──────────────────────────
    mm::Image mag_n = mm::spectrumMag(img_noisy);

    // ── 3. Máscara notch gaussiana nos 4 picos periódicos ──────────────────────
    int cy0 = h_img / 2, cx0 = w_img / 2;
    cv::Mat mascara_notch = cv::Mat::ones(h_img, w_img, CV_64F);

    // Vetor de deslocamentos
    std::vector<std::pair<int, int>> offsets = {
        {(int)v0, (int)u0}, {(int)-v0, (int)-u0}, {(int)v0, (int)-u0}, {(int)-v0, (int)u0}
    };
    for (auto& off : offsets) {
        mascara_notch = suprimir_pico_gaussiano(mascara_notch, cy0 + off.first, cx0 + off.second, 3.0);
    }

    // ── 4. Filtragem: notch no domínio da frequência + bilateral ───────────────
    mm::Image img_notch = mm::freqFilter(img_noisy, mascara_notch);

    // Converter img_notch para cv::Mat para bilateral
    cv::Mat img_notch_mat = img_notch;  // Conversão implícita
    cv::Mat img_den_mat;
    cv::bilateralFilter(img_notch_mat, img_den_mat, 7, 25, 7);
    mm::Image img_den = img_den_mat;

    // Máscara visual
    cv::Mat mascara_vis_float;
    cv::multiply(mascara_notch, 255, mascara_vis_float);
    cv::Mat mascara_vis_mat;
    mascara_vis_float.convertTo(mascara_vis_mat, CV_8U);
    mm::Image mascara_vis = mascara_vis_mat;

    double psnr_n = mm::psnr(img_gray, img_noisy);
    double psnr_no = mm::psnr(img_gray, img_notch);
    double psnr_d = mm::psnr(img_gray, img_den);
    std::cout << "Ruidosa: PSNR=" << psnr_n << " dB | Apos notch: " << psnr_no << " dB | Notch+bilateral: " << psnr_d << " dB" << std::endl;

    std::vector<mm::Image> images = {img_gray, mm::Image(img_noisy), mag_n, mascara_vis, img_notch, img_den};
    std::vector<std::string> titles = {
        "Original",
        "Ruidosa (PSNR=" + std::to_string(psnr_n) + " dB)",
        "Espectro (picos visiveis)",
        "Mascara notch (gaussiana)",
        "Apos notch (PSNR=" + std::to_string(psnr_no) + " dB)",
        "Notch + bilateral (PSNR=" + std::to_string(psnr_d) + " dB)"
    };

    mm::show(images, MM_OUT, titles, 6);

    return 0;
}

