int main() {
    // #| label: fig-09-pets-amostras
    // #| fig-cap: "Amostras reais de treino do *Oxford-IIIT Pet Dataset* (Parkhi et al., 2012, licença CC BY-SA 4.0): *Pug* e *Boxer*, raças escolhidas para simular um cenário real de escassez de dados."
    // #| echo: true
    // #| output: true
    // #| eval: false

    std::vector<std::string> RACAS_ALVO = {"Pug", "Boxer"};
    int N_TREINO_POR_CLASSE = 15;
    int N_TESTE_POR_CLASSE = 20;

    // 1. Download do dataset completo (37 raças) — licença CC BY-SA 4.0
    // Nota: Este dataset específico (Oxford-IIIT Pet) não está disponível diretamente
    // através da biblioteca mm.*. Este código simula a estrutura esperada.
    // Em uma implementação real, você precisaria baixar e carregar os dados manualmente.

    // Simulação das classes e dados
    std::vector<std::string> nomes_racas = {
        "Abyssinian", "Bengal", "Birman", "Bombay", "British_Shorthair",
        "Egyptian_Mau", "Maine_Coon", "Persian", "Ragdoll", "Russian_Blue",
        "Siamese", "Sphynx", "american_bulldog", "american_pit_bull_terrier",
        "basset_hound", "beagle", "boxer", "chihuahua", "english_cocker_spaniel",
        "english_setter", "german_shorthaired", "great_pyrenees", "havanese",
        "japanese_chin", "keeshond", "leonberger", "miniature_pinscher",
        "newfoundland", "pomeranian", "pug", "saint_bernard", "samoyed",
        "scottish_terrier", "shiba_inu", "staffordshire_bull_terrier",
        "wheaten_terrier", "yorkshire_terrier"
    };

    std::vector<int> indices_alvo;
    for (const auto& raca : RACAS_ALVO) {
        auto it = std::find(nomes_racas.begin(), nomes_racas.end(), raca);
        if (it != nomes_racas.end()) {
            indices_alvo.push_back(std::distance(nomes_racas.begin(), it));
        }
    }

    // 2. Filtragem das duas raças de interesse, separadas por classe
    // Nota: Simulação de imagens - na prática, você carregaria imagens reais
    std::vector<std::vector<mm::Image>> por_classe(2);
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 50; j++) {
            mm::Image img(64, 64);
            por_classe[i].push_back(img);
        }
    }

    // 3. Amostragem: poucas imagens de treino, mais imagens de teste
    std::mt19937 rng(42); // seed fixa para reprodutibilidade
    std::vector<mm::Image> imgs_treino, imgs_teste;
    std::vector<int> y_treino, y_teste;

    for (int classe_idx = 0; classe_idx < 2; classe_idx++) {
