4394be33b4be207bd1f7d51a108bd550:
#### Implementation of Opening and Closing

Unlike erosion and dilation, opening and closing do not introduce new computational mechanisms. Both are obtained by the sequential composition of the primitive operators already presented:

```python
def open0(f, B):
    return mm.dil0(mm.ero0(f, B), B)

def close0(f, B):
    return mm.ero0(mm.dil0(f, B), B)
```

The `mm.open` function delegates the operation to `cv2.morphologyEx(..., MORPH_OPEN, B)`, while `mm.close` uses `cv2.morphologyEx(..., MORPH_CLOSE, B)`, producing the same result more efficiently.

Opening inherits from erosion the ability to remove structures smaller than the structuring element and from dilation the partial restoration of preserved regions. Closing performs the inverse process: it first expands the objects and then restores their original dimensions, filling gaps and holes smaller than the structuring element.

43f4ff9e97e6fd65361a35ea99984e5e:
//| label: fig-05-filtros-passa-alta
//| fig-cap: "Filtro passa-alta Gaussiano. (a) Original; (b) Filtro passa-alta (D₀=30) - as bordas das moedas e fundo texturizado são realçados."

// Passa-alta Gaussiano: H_alta(u,v) = 1 - exp(-D²/(2·D₀²)), aplicado via FFT.
#include <opencv2/opencv.hpp>
#include <vector>
#include <string>
#include <cmath>
#include "morph.hpp"

// Matriz de distâncias ao centro do espectro (após fftshift).
cv::Mat distancia_centro(int M, int N) {
    cv::Mat D(M, N, CV_64F);
    for (int i = 0; i < M; i++) {
        double u = i - M / 2;
        for (int j = 0; j < N; j++) {
            double v = j - N / 2;
            D.at<double>(i, j) = std::sqrt(u * u + v * v);
        }
    }
    return D;
}

// Aplica o filtro H (centrado) à imagem via FFT.
cv::Mat aplicar_filtro_freq(const cv::Mat& img, const cv::Mat& H) {
    cv::Mat img64;
    if (img.channels() == 1) {
        img.convertTo(img64, CV_64F);
    } else {
        cv::cvtColor(img, img64, cv::COLOR_BGR2GRAY);
        img64.convertTo(img64, CV_64F);
    }

    cv::Mat padded;
    int M = cv::getOptimalDFTSize(img64.rows);
    int N = cv::getOptimalDFTSize(img64.cols);
    cv::copyMakeBorder(img64, padded, 0, M - img64.rows, 0, N - img64.cols, cv::BORDER_CONSTANT, cv::Scalar::all(0));

    cv::Mat planes[] = {padded, cv::Mat::zeros(padded.size(), CV_64F)};
    cv::Mat complexI;
    cv::merge(planes, 2, complexI);
    cv::dft(complexI, complexI);

    // FFT shift
    int cx = complexI.cols / 2;
    int cy = complexI.rows / 2;
    cv::Mat q0(complexI, cv::Rect(0, 0, cx, cy));
    cv::Mat q1(complexI, cv::Rect(cx, 0, cx, cy));
    cv::Mat q2(complexI, cv::Rect(0, cy, cx, cy));
    cv::Mat q3(complexI, cv::Rect(cx, cy, cx, cy));
    cv::Mat tmp;
    q0.copyTo(tmp);
    q3.copyTo(q0);
    tmp.copyTo(q3);
    q1.copyTo(tmp);
    q2.copyTo(q1);
    tmp.copyTo(q2);

    // Aplicar filtro
    cv::Mat H_resized;
    cv::resize(H, H_resized, padded.size());
    cv::Mat H_planes[] = {H_resized, H_resized};
    cv::Mat H_complex;
    cv::merge(H_planes, 2, H_complex);
    cv::mulSpectrums(complexI, H_complex, complexI, 0);

    // IFFT shift
    q0.copyTo(tmp);
    q3.copyTo(q0);
    tmp.copyTo(q3);
    q1.copyTo(tmp);
    q2.copyTo(q1);
    tmp.copyTo(q2);

    cv::idft(complexI, complexI);
    cv::split(complexI, planes);
    cv::Mat result;
    cv::normalize(planes[0], result, 0, 255, cv::NORM_MINMAX);
    result.convertTo(result, CV_8U);

    // Recortar ao tamanho original
    if (result.rows != img64.rows || result.cols != img64.cols) {
        result = result(cv::Rect(0, 0, img64.cols, img64.rows)).clone();
    }
    return result;
}

int main() {
    // img_gray é fornecido automaticamente (mm::Image)
    cv::Mat img_gray_mat(img_gray.h, img_gray.w, CV_8UC1, img_gray.data.data());

    int M = img_gray.h;
    int N = img_gray.w;
    double D0 = 30;

    cv::Mat D = distancia_centro(M, N);
    cv::Mat D2;
    cv::multiply(D, D, D2);
    cv::Mat H_alta = cv::Mat::ones(M, N, CV_64F) - D2 / (2.0 * D0 * D0);
    cv::exp(-H_alta, H_alta);
    cv::Mat ones = cv::Mat::ones(M, N, CV_64F);
    H_alta = ones - H_alta;  // H_alta = 1 - exp(-D²/(2·D₀²))

    cv::Mat img_alta = aplicar_filtro_freq(img_gray_mat, H_alta);

    mm::Image img_gray_out = img_gray;  // Preservar original
    mm::show({img_gray_out, img_alta},
             MM_OUT,
             {"Original", "Passa-alta Gaussiano ($D_0=30$)"},
             2);

    return 0;
}

