// Compile with: g++ -std=c++17 -I. program.cpp -o program && ./program
#include "morph.hpp"
#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
#include <random>

// Note: This translation assumes the availability of load_digits(), train_test_split,
// and PyTorch tensor operations. Since these are not part of the mm.* library,
// we simulate the data loading and preprocessing here.

// Simplified stand-in for load_digits() - generates random digit-like data
mm::Image load_digits_data() {
    // Create a larger dataset (we'll simulate 100 samples of 8x8 digits)
    // In practice, you would load the actual dataset
    mm::Image dataset(100, 8*8); // 100 samples, each 64 pixels
    std::mt19937 gen(42);
    std::uniform_int_distribution<int> dist(0, 15);
    for (int i = 0; i < 100; ++i) {
        for (int j = 0; j < 64; ++j) {
            dataset.at(i, j) = dist(gen);
        }
    }
    return dataset;
}

// Simplified stand-in for train_test_split with stratification
void split_data(const mm::Image& X, const std::vector<int>& y,
                mm::Image& X_train, mm::Image& X_test,
                std::vector<int>& y_train, std::vector<int>& y_test,
                double test_size = 0.3) {
    // Simple split without stratification (in practice, use scikit-learn)
    int n_samples = X.h;
    int n_train = static_cast<int>(n_samples * (1 - test_size));

    X_train = mm::Image(n_train, X.w);
    X_test = mm::Image(n_samples - n_train, X.w);

    for (int i = 0; i < n_train; ++i) {
        for (int j = 0; j < X.w; ++j) {
            X_train.at(i, j) = X.at(i, j);
        }
        y_train.push_back(y[i]);
    }

    for (int i = n_train; i < n_samples; ++i) {
        for (int j = 0; j < X.w; ++j) {
            X_test.at(i - n_train, j) = X.at(i, j);
        }
        y_test.push_back(y[i]);
    }
}

// Simulate PyTorch tensor operations
// We represent tensors as nested vectors for clarity
struct Tensor4D {
    int N, C, H, W;
    std::vector<std::vector<std::vector<std::vector<float>>>> data;

    Tensor4D(int n, int c, int h, int w) : N(n), C(c), H(h), W(w) {
        data.resize(N, std::vector<std::vector<std::vector<float>>>(
            C, std::vector<std::vector<float>>(
                H, std::vector<float>(W, 0.0f))));
    }
};

int main() {
    // 1. Chargement et prétraitement des données
    // Load digits (simulated here)
    mm::Image digits = load_digits_data();

    // Normalize to [0, 1] range
    int n_samples = digits.h;
    int n_features = digits.w;
    mm::Image X(n_samples, n_features);
    std::vector<int> y(n_samples);

    // Generate labels (0-9)
    for (int i = 0; i < n_samples; ++i) {
        y[i] = i % 10;
        for (int j = 0; j < n_features; ++j) {
            X.at(i, j) = digits.at(i, j); // / 16.0 would be for normalization
        }
    }

    // Division stratifiée en ensembles d'entraînement (70%) et de test (30%)
    mm::Image X_train, X_test;
    std::vector<int> y_train, y_test;
    split_data(X, y, X_train, X_test, y_train, y_test, 0.3);

    // Adaptation à la dimension attendue par PyTorch : (N_échantillons, Canaux, Hauteur, Largeur)
    int n_samples_train = X_train.h;
    int n_samples_test = X_test.h;
    int img_h = 8, img_w = 8; // 8x8 digits

    // Simulate PyTorch tensors
    Tensor4D X_train_t(n_samples_train, 1, img_h, img_w);  // Dimension : (N, 1, 8, 8)
    Tensor4D X_test_t(n_samples_test, 1, img_h, img_w);

    // Fill tensors from images
    for (int i = 0; i < n_samples_train; ++i) {
        for (int j = 0; j < 64; ++j) {
            int h = j / 8, w = j % 8;
            X_train_t.data[i][0][h][w] = X_train.at(i, j) / 16.0f; // Normalisation
        }
    }

    for (int i = 0; i < n_samples_test; ++i) {
        for (int j = 0; j < 64; ++j) {
            int h = j / 8, w = j % 8;
            X_test_t.data[i][0][h][w] = X_test.at(i, j) / 16.0f;
        }
    }

    // Afficher un échantillon
    int n_samples_show = 8;
    std::vector<mm::Image> imgs;
    std::vector<std::string> imgs_titles;

    for (int i = 0; i < n_samples_show && i < n_samples_train; ++i) {
        // Créer une image 8x8 à partir du tenseur
        mm::Image img(8, 8);
        for (int h = 0; h < 8; ++h) {
            for (int w = 0; w < 8; ++w) {
                // Convertir de [0,1] vers [0,255] pour l'affichage
                img.at(h, w) = static_cast<unsigned char>(X_train_t.data[i][0][h][w] * 255.0f);
            }
        }
        imgs.push_back(img);
        imgs_titles.push_back(std::to_string(y_train[i]));
    }

    mm::show(imgs, MM_OUT, imgs_titles, 8);

    return 0;
}

