// Função para adicionar ruído sal e pimenta
std::pair<mm::Image, int> add_salt_pepper(const mm::Image& img, double prob=0.05, int seed=42) {
    // Adiciona ruído sal e pimenta com probabilidade total prob.
    mm::Image noisy = img;
    std::mt19937 gen(seed);
    std::uniform_real_distribution<double> dis(0.0, 1.0);

    int n_corrompidos = 0;

    for (int y = 0; y < img.h; ++y) {
        for (int x = 0; x < img.w; ++x) {
            double rnd = dis(gen);
            if (rnd < prob / 2) {
                noisy.at(y, x) = 0;    // pimenta
                ++n_corrompidos;
            } else if (rnd > 1 - prob / 2) {
                noisy.at(y, x) = 255;  // sal
                ++n_corrompidos;
            }
        }
    }

    return {noisy, n_corrompidos};
}

int main() {
    // Supondo que img_gray_crop já está definido (carregado de algum lugar)
    // Aqui assumimos que img_gray_crop é uma imagem em escala de cinza
    mm::Image img_gray_crop = mm::read("caminho/para/imagem.jpg", true);

    std::vector<double> probs = {0.02, 0.05, 0.10};
    std::vector<mm::Image> imgs_noise = {img_gray_crop};
    std::vector<std::string> titles_noise = {"Original"};

    for (double p : probs) {
        auto [noisy, n] = add_salt_pepper(img_gray_crop, p);
        imgs_noise.push_back(noisy);
        titles_noise.push_back("Ruído " + std::to_string((int)(p*100)) + "%\n(" + 
                              std::to_string(n) + " pixels)");
    }

    mm::show(imgs_noise, MM_OUT, titles_noise, 4);

    return 0;
}

