#include <opencv2/opencv.hpp>
#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include "morph.hpp"

//| label: fig-05-ruido-periodico
//| fig-cap: "Remoção de ruído periódico via filtro *notch* no domínio da frequência: (a) imagem com ruído senoidal, (b) espectro mostrando os picos do ruído, (c) máscara *notch* centrada nos picos, (d) imagem restaurada."
//| echo: true
//| output: true

// Função para trocar quadrantes (equivalente ao fftshift)
void fftShift(cv::Mat& mat) {
    int cx = mat.cols / 2;
    int cy = mat.rows / 2;

    cv::Mat q0(mat, cv::Rect(0, 0, cx, cy));   // Quadrante superior esquerdo
    cv::Mat q1(mat, cv::Rect(cx, 0, cx, cy));  // Quadrante superior direito
    cv::Mat q2(mat, cv::Rect(0, cy, cx, cy));  // Quadrante inferior esquerdo
    cv::Mat q3(mat, cv::Rect(cx, cy, cx, cy)); // Quadrante inferior direito

    cv::Mat tmp;
    q0.copyTo(tmp);
    q3.copyTo(q0);
    tmp.copyTo(q3);

    q1.copyTo(tmp);
    q2.copyTo(q1);
    tmp.copyTo(q2);
}

// Função para zerar um disco de raio r centrado em (cy, cx)
void suprimirPico(cv::Mat& mask, int cy, int cx, int r) {
    for (int yy = 0; yy < mask.rows; yy++) {
        for (int xx = 0; xx < mask.cols; xx++) {
            double dist = std::sqrt((yy - cy) * (yy - cy) + (xx - cx) * (xx - cx));
            if (dist <= r) {
                mask.at<double>(yy, xx) = 0;
            }
        }
    }
}

double calcularSSIM(const cv::Mat& img1, const cv::Mat& img2, int dataRange = 255) {
    // Implementação padrão do SSIM com janela gaussiana (Wang et al.)
    const double C1 = 6.5025;  // (0.01 * 255)^2
    const double C2 = 58.5225; // (0.03 * 255)^2

    cv::Mat img1f, img2f;
    img1.convertTo(img1f, CV_32F);
    img2.convertTo(img2f, CV_32F);

    cv::Mat mu1, mu2;
    cv::GaussianBlur(img1f, mu1, cv::Size(11, 11), 1.5);
    cv::GaussianBlur(img2f, mu2, cv::Size(11, 11), 1.5);

    cv::Mat mu1_sq = mu1.mul(mu1);
    cv::Mat mu2_sq = mu2.mul(mu2);
    cv::Mat mu1_mu2 = mu1.mul(mu2);

    cv::Mat sigma1_sq, sigma2_sq, sigma12;
    cv::GaussianBlur(img1f.mul(img1f), sigma1_sq, cv::Size(11, 11), 1.5);
    sigma1_sq -= mu1_sq;

    cv::GaussianBlur(img2f.mul(img2f), sigma2_sq, cv::Size(11, 11), 1.5);
    sigma2_sq -= mu2_sq;

    cv::GaussianBlur(img1f.mul(img2f), sigma12, cv::Size(11, 11), 1.5);
    sigma12 -= mu1_mu2;

    cv::Mat ssim_map;
    cv::Mat temp1 = (2 * mu1_mu2 + C1).mul(2 * sigma12 + C2);
    cv::Mat temp2 = (mu1_sq + mu2_sq + C1).mul(sigma1_sq + sigma2_sq + C2);
    cv::divide(temp1, temp2, ssim_map);

    cv::Scalar mssim = cv::mean(ssim_map);
    return mssim.val[0];
}

int main() {
    // As variáveis de entrada (img_gray) já estão inicializadas aqui

    int h_img = img_gray.h;
    int w_img = img_gray.w;

    // Converter para cv::Mat para processamento
    cv::Mat imgGrayMat(h_img, w_img, CV_8UC1, img_gray.data.data());

    // ── Imagem com ruído periódico sintético ──────────────────────────────────────
    cv::Mat imgRuidoFloat(h_img, w_img, CV_64F);

    // Usar frequências inteiras e consistentes (importante para restauração perfeita)
    int u0 = 20, v0 = 20;  // frequências exatas do ruído

    // Gerar ruído senoidal
    for (int yy = 0; yy < h_img; yy++) {
        for (int xx = 0; xx < w_img; xx++) {
            double ruido = 40 * std::sin(2 * M_PI * (u0 * (double)xx / w_img + v0 * (double)yy / h_img));
            imgRuidoFloat.at<double>(yy, xx) = imgGrayMat.at<uchar>(yy, xx) + ruido;
        }
    }

    // Clipar para [0, 255] e converter para uint8
    cv::Mat imgRuidosa;
    cv::normalize(imgRuidoFloat, imgRuidoFloat, 0, 255, cv::NORM_MINMAX);
    imgRuidoFloat.convertTo(imgRuidosa, CV_8U);

    // ── Espectro da imagem ruidosa ───────────────────────────────────────────────
    cv::Mat imgRuidosaFloat;
    imgRuidosa.convertTo(imgRuidosaFloat, CV_32F);

    cv::Mat F_alt;
    cv::dft(imgRuidosaFloat, F_alt, cv::DFT_COMPLEX_OUTPUT);

    // Separar partes real e imaginária
    std::vector<cv::Mat> channels;
    cv::split(F_alt, channels);

    // Fazer fftshift manualmente
    fftShift(channels[0]);
    fftShift(channels[1]);

    // Calcular magnitude
    cv::Mat magnitude;
    cv::magnitude(channels[0], channels[1], magnitude);

    // Log1p da magnitude
    cv::Mat magLog;
    cv::log(magnitude + 1.0, magLog);

    // Normalizar para visualização
    cv::Mat magVis;
    cv::normalize(magLog, magVis, 0, 255, cv::NORM_MINMAX, CV_8U);

    // ── Máscara notch ────────────────────────────────────────────────────────────
    cv::Mat mascara = cv::Mat::ones(h_img, w_img, CV_64F);
    int r_notch = 8;  // raio do notch (ajuste fino se necessário)

    // Coordenadas centrais
    int cy = h_img / 2, cx = w_img / 2;

    // Suprimir os 4 picos simétricos (importante!)
    std::vector<std::pair<int, int>> offsets = {{v0, u0}, {-v0, -u0}, {v0, -u0}, {-v0, u0}};
    for (const auto& offset : offsets) {
        suprimirPico(mascara, cy + offset.first, cx + offset.second, r_notch);
    }

    cv::Mat mascaraVis;
    cv::Mat mascara8u;
    mascara.convertTo(mascara8u, CV_8U, 255.0);
    mascara8u.copyTo(mascaraVis);

    // ── Filtragem e reconstrução ─────────────────────────────────────────────────
    // Aplicar máscara nos canais real e imaginário
    cv::Mat Ffiltrada_real = channels[0].mul(mascara);
    cv::Mat Ffiltrada_imag = channels[1].mul(mascara);

    // Reconstruir espectro complexo
    std::vector<cv::Mat> filteredChannels = {Ffiltrada_real, Ffiltrada_imag};
    cv::Mat F_complex;
    cv::merge(filteredChannels, F_complex);

    // Fazer ifftshift
    cv::Mat F_shifted[2];
    cv::split(F_complex, F_shifted);
    fftShift(F_shifted[0]);
    fftShift(F_shifted[1]);
    cv::merge(F_shifted, 2, F_complex);

    // IDFT com escala
    cv::Mat imgRestored;
    cv::idft(F_complex, imgRestored, cv::DFT_SCALE | cv::DFT_REAL_OUTPUT);

    // Normalizar para visualização
    cv::Mat imgRestVis;
    imgRestored.convertTo(imgRestored, CV_32F);
    cv::normalize(imgRestored, imgRestVis, 0, 255, cv::NORM_MINMAX, CV_8U);

    // Avaliação
    double psnr = cv::PSNR(imgGrayMat, imgRestVis);

    // Calcular SSIM
    double ssim = calcularSSIM(imgGrayMat, imgRestVis, 255);

    std::cout << "PSNR (original vs restaurada): " << psnr << " dB" << std::endl;

    // ── Visualização ─────────────────────────────────────────────────────────────
    // Converter cv::Mat para mm::Image
    mm::Image imgRuidosaMM(w_img, h_img, 1);
    std::memcpy(imgRuidosaMM.data.data(), imgRuidosa.data, imgRuidosa.total());

    mm::Image magVisMM(w_img, h_img, 1);
    std::memcpy(magVisMM.data.data(), magVis.data, magVis.total());

    mm::Image mascaraVisMM(w_img, h_img, 1);
    std::memcpy(mascaraVisMM.data.data(), mascaraVis.data, mascaraVis.total());

    mm::Image imgRestVisMM(w_img, h_img, 1);
    std::memcpy(imgRestVisMM.data.data(), imgRestVis.data, imgRestVis.total());

    // Construir títulos
    char psnrStr[100];
    snprintf(psnrStr, sizeof(psnrStr), "Restaurada (PSNR=%.1f dB)", psnr);

    mm::show(
        {imgRuidosaMM, magVisMM, mascaraVisMM, imgRestVisMM},
        MM_OUT,
        {"Com ruído periódico", "Espectro (log)", "Máscara notch", psnrStr},
        4
    );

    return 0;
}

