    </div>

    <!-- Slider Limiar -->
    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
      <label style="font-size:11px; font-weight:700; color:#5e5a4a;">
        Distance threshold (acceptable reprojection error): <span id="sim08_reg_slVal" style="font-family:monospace; color:#26241d;">12</span> px
      </label>
    </div>
    <input type="range" id="sim08_reg_slider" min="3" max="30" step="1" value="12">

  </div>

  <!-- Canvas -->
  <div style="margin-bottom:14px; text-align:center;">
    <canvas id="sim08_reg_canvas" width="640" height="320"></canvas>
