#include <opencv2/opencv.hpp>
#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <numeric>
#include <string>
#include "morph.hpp"

//| label: fig-05-conv-teorema
//| fig-cap: "Verificação do Teorema da Convolução: a diferença pixel a pixel entre a convolução espacial (cv2.filter2D) e a multiplicação em frequência (FFT) é numericamente nula — confirmando a equivalência teórica."
//| echo: true
//| output: true

// Função para deslocar o espectro (equivalente ao fftshift)
void fftShift(cv::Mat& spectrum) {
    int cx = spectrum.cols / 2;
    int cy = spectrum.rows / 2;
    cv::Mat q0(spectrum, cv::Rect(0, 0, cx, cy));
    cv::Mat q1(spectrum, cv::Rect(cx, 0, cx, cy));
    cv::Mat q2(spectrum, cv::Rect(0, cy, cx, cy));
    cv::Mat q3(spectrum, cv::Rect(cx, cy, cx, cy));

    cv::Mat tmp;
    q0.copyTo(tmp);
    q3.copyTo(q0);
    tmp.copyTo(q3);
    q1.copyTo(tmp);
    q2.copyTo(q1);
    tmp.copyTo(q2);
}

// Função para converter mm::Image para cv::Mat
cv::Mat mmToCv(const mm::Image& img) {
    int type = img.channels == 1 ? CV_8UC1 : CV_8UC3;
    return cv::Mat(img.h, img.w, type, (void*)img.data.data()).clone();
}

// Função para converter cv::Mat para mm::Image
mm::Image cvToMm(const cv::Mat& mat) {
    mm::Image out(mat.rows, mat.cols, mat.channels());
    std::memcpy(out.data.data(), mat.data, out.data.size());
    return out;
}

int main() {
    // img_gray é fornecido automaticamente como mm::Image

    // ── Kernel Gaussiano 11×11 
    double sigma = 3.0;
    int K = 11;

    // Cria o kernel 1D Gaussiano
    cv::Mat ks(1, K, CV_32F);
    for (int i = 0; i < K; i++) {
        ks.at<float>(0, i) = i - K / 2;
    }

    cv::Mat gauss1d(1, K, CV_32F);
    for (int i = 0; i < K; i++) {
        float x = ks.at<float>(0, i);
        gauss1d.at<float>(0, i) = std::exp(-x * x / (2 * sigma * sigma));
    }

    // Normaliza o kernel 1D
    float sum = cv::sum(gauss1d)[0];
    gauss1d /= sum;

    // Cria o kernel 2D separável (produto externo)
    cv::Mat kernel = gauss1d.t() * gauss1d;

    // ── Método 1: Convolução espacial direta ─────────────────────────────────────
    cv::Mat img_cv = mmToCv(img_gray);
    cv::Mat f_float;
    img_cv.convertTo(f_float, CV_64F);

    // Converte o kernel para float64 para corresponder
    cv::Mat kernel64;
    kernel.convertTo(kernel64, CV_64F);

    cv::Mat conv_esp;
    cv::filter2D(f_float, conv_esp, -1, kernel64, cv::Point(-1, -1), 0, cv::BORDER_CONSTANT);

    // ── Método 2: Multiplicação em frequência (via FFT) ──────────────────────────
    int M = img_gray.h;
    int N = img_gray.w;

    // Padding para convolução linear (evita aliasing circular)
    int Mpad = 1;
    int Npad = 1;
    while (Mpad < M + K - 1) Mpad <<= 1;
    while (Npad < N + K - 1) Npad <<= 1;

    // Posiciona o kernel com a origem no (0,0) e padding com zeros
    cv::Mat kernel_pad = cv::Mat::zeros(Mpad, Npad, CV_64F);
    int kh = kernel64.rows;
    int kw = kernel64.cols;
    cv::Mat roi = kernel_pad(cv::Rect(0, 0, kw, kh));
    kernel64.copyTo(roi);

    // Realiza a FFT da imagem e do kernel
    cv::Mat F_img;
    cv::Mat padded_img;
    cv::copyMakeBorder(f_float, padded_img, 0, Mpad - M, 0, Npad - N, cv::BORDER_CONSTANT, 0);
    cv::Mat padded_img_f32;
    padded_img.convertTo(padded_img_f32, CV_32F);
    cv::dft(padded_img_f32, F_img, cv::DFT_COMPLEX_OUTPUT);

    cv::Mat kernel_pad_f32;
    kernel_pad.convertTo(kernel_pad_f32, CV_32F);
    cv::Mat F_kern;
    cv::dft(kernel_pad_f32, F_kern, cv::DFT_COMPLEX_OUTPUT);

    // Multiplica no domínio da frequência
    cv::Mat freq_product;
    cv::mulSpectrums(F_img, F_kern, freq_product, 0);

    // FFT inversa
    cv::Mat conv_freq_full;
    cv::idft(freq_product, conv_freq_full, cv::DFT_SCALE | cv::DFT_REAL_OUTPUT);

    // Converte para float64
    cv::Mat conv_freq64;
    conv_freq_full.convertTo(conv_freq64, CV_64F);

    // Recorte para compensar o deslocamento introduído pelo posicionamento do kernel
    int offset = K / 2;
    cv::Mat conv_freq_crop = conv_freq64(cv::Rect(offset, offset, N, M)).clone();

    // ── Verificação numérica ──────────────────────────────────────────────────────
    cv::Mat diff = cv::abs(conv_esp - conv_freq_crop);
    double max_val, min_val;
    cv::minMaxLoc(diff, &min_val, &max_val);
    double mean_val = cv::mean(diff)[0];

    std::cout << "Diferença máxima  (|conv_esp - conv_freq|): " << max_val << std::endl;
    std::cout << "Diferença média   (|conv_esp - conv_freq|): " << mean_val << std::endl;
    std::cout << "→ Teorema da Convolução verificado numericamente." << std::endl;

    // Normaliza para visualização
    cv::Mat conv_esp_vis, conv_freq_vis, diff_vis;
    cv::normalize(conv_esp, conv_esp_vis, 0, 255, cv::NORM_MINMAX, CV_8U);
    cv::normalize(conv_freq_crop, conv_freq_vis, 0, 255, cv::NORM_MINMAX, CV_8U);
    cv::normalize(diff, diff_vis, 0, 255, cv::NORM_MINMAX, CV_8U);

    // Converte para mm::Image para exibição
    mm::Image img_gray_mm = cvToMm(img_cv);
    mm::Image conv_esp_mm = cvToMm(conv_esp_vis);
    mm::Image conv_freq_mm = cvToMm(conv_freq_vis);
    mm::Image diff_mm = cvToMm(diff_vis);

    char title_diff[256];
    std::sprintf(title_diff, "Diferença (máx=%.1e)", max_val);

    mm::show(
        {img_gray_mm, conv_esp_mm, conv_freq_mm, diff_mm},
        MM_OUT,
        {"Original", "Convolução espacial", "Multiplicação em frequência", title_diff},
        4
    );

    return 0;
}

