        for (var j = 0; j < 4; j++) {
          var srcRow = i - ty;
          var srcCol = j - tx;
          var v = 0;

          if (srcRow >= 0 && srcRow < 4 && srcCol >= 0 && srcCol < 4) {
            v = pixels[srcRow * 4 + srcCol];
          }

