#include <filesystem>
#include <cstdlib>
#include "morph.hpp"

// Note: PDF conversion requires external tools (pdftoppm/poppler)
// This code uses a simpler approach with system calls for demonstration

int main() {
    std::string file = "dados/provas_qrcode_EP.pdf";
    std::string MYFILES = "extra02.qrcode";
    std::string myfile0;
    mm::Image img_inicial;

    // Check if file exists
    std::ifstream f(file.c_str());
    if (f.good()) {
        // Since we can't directly use pdf2image in C++, we'll convert using system call
        // This is a simplification - in real use, you'd need poppler tools
        std::string cmd = "pdftoppm -png -r 200 " + file + " " + MYFILES + "_p";
        int result = system(cmd.c_str());

        // Find the converted pages
        int numPAGES = 0;
        bool foundMore = true;
        while (foundMore) {
            myfile0 = MYFILES + "_p" + std::to_string(numPAGES) + ".png";
            std::ifstream imgFile(myfile0.c_str());
            if (imgFile.good()) {
                std::cout << "[INGESTÃO] Página convertida: " << myfile0 << "\n";
                numPAGES++;
            } else {
                foundMore = false;
            }
        }

        if (numPAGES > 0) {
            // Read the last converted page
            myfile0 = MYFILES + "_p" + std::to_string(numPAGES - 1) + ".png";
            mm::Image img_color = mm::read(myfile0);
            img_inicial = mm::gray(img_color);
        } else {
            // Fallback if conversion failed
            std::cout << "[AVISO] Falha na conversão do PDF. Usando imagem substituta.\n";
            img_inicial = mm::randomImage(512, 512, 255);
        }
    } else {
        std::cout << "[AVISO] Arquivo 'dados/provas_qrcode.pdf' não encontrado.\n";
        std::cout << "        Usando imagem substituta.\n";
        img_inicial = mm::randomImage(512, 512, 255);
    }

    mm::show(img_inicial, MM_OUT);

    return 0;
}

