#include "morph.hpp"
#include <iostream>
#include <iomanip>

int main() {
    //| label: fig-04-componentes
    //| fig-cap: "Componentes conexos após o pipeline de segmentação, rotulados por mm::label0. A tabela lista área e caixa de cada objeto. (Cores aleatórias e texto sobre a imagem ficam na trilha Python.)"
    //| echo: true
    //| output: true

    mm::Image lab = mm::label0(img_final, mm::sebox());
    int n = 0;
    for (unsigned char v : lab.data) {
        if ((int)v > n) n = (int)v;
    }
    int H = lab.h;
    int W = lab.w;
    std::cout << "Componentes detectados: " << n << "\n";
    std::cout << std::setw(4) << "ID" << std::setw(8) << "Área" << std::setw(6) << "x0" << std::setw(6) << "y0" << std::setw(6) << "w" << std::setw(6) << "h" << "\n";
    std::cout << std::string(40, '-') << "\n";
    for (int k = 1; k <= n; ++k) {
        int area = 0; int x0 = W; int y0 = H; int x1 = 0; int y1 = 0;
        for (int y = 0; y < H; ++y) {
            for (int x = 0; x < W; ++x) {
                if (lab.at(y, x) == k) {
                    area += 1;
                    if (x < x0) x0 = x;
                    if (x > x1) x1 = x;
                    if (y < y0) y0 = y;
                    if (y > y1) y1 = y;
                }
            }
        }
        std::cout << std::setw(4) << k << std::setw(8) << area << std::setw(6) << x0 << std::setw(6) << y0 << std::setw(6) << (x1 - x0 + 1) << std::setw(6) << (y1 - y0 + 1) << "\n";
    }

    mm::Image lab_vis = lab;
    for (int y = 0; y < H; ++y) {
        for (int x = 0; x < W; ++x) {
            if (lab_vis.at(y, x)) {
                lab_vis.at(y, x) = (int)(lab_vis.at(y, x) * 255 / std::max(n, 1));
            }
        }
    }

    mm::show(std::vector<mm::Image>{img_coins_gray, img_final, lab_vis},
             MM_OUT,
             std::vector<std::string>{"Original", "Segmentação Final", "Componentes (mm.label0)"}, 3);

    return 0;
}

5f0cb555266b658967db5165522cd027:
### Labeling and Component Statistics

The function `cv2.connectedComponentsWithStats` simultaneously performs labeling of connected components and extraction of basic descriptors for each region. The operator returns:

- a label image (`labels`);
- geometric statistics (`stats`);
- centroid coordinates (`centroids`).

The statistics include area, width, height, and the position of the minimum bounding box aligned with the image axes.

@fig-04-componentes illustrates the application of this operator after the coin segmentation pipeline. Each connected component receives a distinct color, and its area is annotated directly on the image.

