//| label: fig-05-zoom-artefatos
//| fig-cap: "Análise comparativa de artefatos de compressão sob fator de qualidade reduzido ($Q=10$). À esquerda, o artefato de bloco característico da DCT no JPEG. À direita, a atenuação e suavização de bordas do padrão WebP."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <vector>
#include <string>
#include <sys/stat.h>
#include <sys/types.h>
#include "morph.hpp"

cv::Mat zoom(cv::Mat img) {
    cv::Mat crop = img(cv::Rect(150, 120, 80, 80));
    cv::Mat resized;
    cv::resize(crop, resized, cv::Size(320, 320), 0, 0, cv::INTER_NEAREST);
    return resized;
}

int main() {
    mkdir("tmp/comp_test", 0777);
    cv::Mat img_cv = cv::Mat(img_gray.h, img_gray.w, CV_8UC1, img_gray.data.data());
    cv::Mat img_src;
    cv::resize(img_cv, img_src, cv::Size(256, 256));

    std::vector<int> jpeg_params = {cv::IMWRITE_JPEG_QUALITY, 10};
    std::vector<int> webp_params = {cv::IMWRITE_WEBP_QUALITY, 10};
    cv::imwrite("tmp/comp_test/base_q10.jpg", img_src, jpeg_params);
    cv::imwrite("tmp/comp_test/base_q10.webp", img_src, webp_params);

    cv::Mat img_jpeg = cv::imread("tmp/comp_test/base_q10.jpg", cv::IMREAD_GRAYSCALE);
    cv::Mat img_webp = cv::imread("tmp/comp_test/base_q10.webp", cv::IMREAD_GRAYSCALE);

    cv::Mat z_orig = zoom(img_src);
    cv::Mat z_jpeg = zoom(img_jpeg);
    cv::Mat z_webp = zoom(img_webp);

    std::vector<mm::Image> images = {
        mm::Image(z_orig.rows, z_orig.cols, z_orig.channels()),
        mm::Image(z_jpeg.rows, z_jpeg.cols, z_jpeg.channels()),
        mm::Image(z_webp.rows, z_webp.cols, z_webp.channels())
    };
    std::memcpy(images[0].data.data(), z_orig.data, images[0].data.size());
    std::memcpy(images[1].data.data(), z_jpeg.data, images[1].data.size());
    std::memcpy(images[2].data.data(), z_webp.data, images[2].data.size());

    std::vector<std::string> titles = {"Zoom Original", "JPEG Q=10 (Artefato de Bloco)", "WebP Q=10 (Suavização)"};
    mm::show(images, MM_OUT, titles, 3);

    return 0;
}

