//| label: fig-05-ruido-periodico
//| fig-cap: "Remoção de ruído periódico via filtro *notch* no domínio da frequência: (a) imagem com ruído senoidal, (b) espectro mostrando os picos do ruído, (c) máscara *notch* centrada nos picos, (d) imagem restaurada."
//| echo: true
//| output: true

// Ruído senoidal 2D -> espectro -> máscara notch nos 4 picos simétricos -> restauração.

#include <opencv2/opencv.hpp>
#include <vector>
#include <string>
#include <cmath>
#include <iostream>
#include <algorithm>
#include "morph.hpp"

// Helper para fftshift 2D (troca quadrantes)
static cv::Mat fftshift_2d(const cv::Mat& src) {
    int cx = src.cols / 2;
    int cy = src.rows / 2;
    cv::Mat tmp;
    cv::Mat q0(src, cv::Rect(0, 0, cx, cy));   // top-left
    cv::Mat q1(src, cv::Rect(cx, 0, src.cols - cx, cy));   // top-right
    cv::Mat q2(src, cv::Rect(0, cy, cx, src.rows - cy));   // bottom-left
    cv::Mat q3(src, cv::Rect(cx, cy, src.cols - cx, src.rows - cy)); // bottom-right

    cv::hconcat(q3, q2, tmp);
    cv::Mat top;
    cv::hconcat(q1, q0, tmp);
    cv::vconcat(tmp, top, tmp);

    // Reconstrução correta
    cv::Mat result;
    cv::Mat topRow, bottomRow;
    cv::hconcat(q3, q2, topRow);
    cv::hconcat(q1, q0, bottomRow);
    cv::vconcat(topRow, bottomRow, result);
    return result;
}

// Helper para ifftshift 2D
static cv::Mat ifftshift_2d(const cv::Mat& src) {
    int cx = (src.cols + 1) / 2;
    int cy = (src.rows + 1) / 2;
    cv::Mat tmp;
    cv::Mat q0(src, cv::Rect(0, 0, cx, cy));
    cv::Mat q1(src, cv::Rect(cx, 0, src.cols - cx, cy));
    cv::Mat q2(src, cv::Rect(0, cy, cx, src.rows - cy));
    cv::Mat q3(src, cv::Rect(cx, cy, src.cols - cx, src.rows - cy));

    cv::Mat topRow, bottomRow;
    cv::hconcat(q3, q2, topRow);
    cv::hconcat(q1, q0, bottomRow);
    cv::Mat result;
    cv::vconcat(topRow, bottomRow, result);
    return result;
}

int main() {
    // img_gray é fornecido automaticamente como mm::Image (não declarar)

    // Converter para cv::Mat
    cv::Mat img_gray_cv(img_gray.h, img_gray.w, CV_8UC1, img_gray.data.data());
    cv::Mat img_gray_f;
    img_gray_cv.convertTo(img_gray_f, CV_64F);

    const int h_img = img_gray.h;
    const int w_img = img_gray.w;

    // Criar malha X, Y
    cv::Mat X(h_img, w_img, CV_32F);
    cv::Mat Y(h_img, w_img, CV_32F);
    for (int y = 0; y < h_img; y++) {
        for (int x = 0; x < w_img; x++) {
            X.at<float>(y, x) = static_cast<float>(x);
            Y.at<float>(y, x) = static_cast<float>(y);
        }
    }

    const float u0 = 20.0f, v0 = 20.0f;  // frequencias exatas do ruido

    // Ruído senoidal 2D
    cv::Mat ruido(h_img, w_img, CV_64F);
    for (int y = 0; y < h_img; y++) {
        for (int x = 0; x < w_img; x++) {
            double arg = 2.0 * CV_PI * (u0 * x / w_img + v0 * y / h_img);
            ruido.at<double>(y, x) = 40.0 * std::sin(arg);
        }
    }

    // Imagem ruidosa
    cv::Mat img_ruidosa_f = img_gray_f + ruido;
    cv::Mat img_ruidosa;
    cv::threshold(img_ruidosa_f, img_ruidosa_f, 0, 0, cv::THRESH_TRUNC);
    cv::threshold(img_ruidosa_f, img_ruidosa_f, 0, 0, cv::THRESH_TOZERO);
    img_ruidosa_f.convertTo(img_ruidosa, CV_8U);

    // Espectro centrado da imagem ruidosa (FFT 2D)
    cv::Mat img_ruidosa_64f;
    img_ruidosa.convertTo(img_ruidosa_64f, CV_64F);
    cv::Mat F;
    cv::dft(img_ruidosa_64f, F, cv::DFT_COMPLEX_OUTPUT);

    // fftshift manual nos dois canais
    std::vector<cv::Mat> channels;
    cv::split(F, channels);
    channels[0] = fftshift_2d(channels[0]);
    channels[1] = fftshift_2d(channels[1]);
    cv::Mat F_shift;
    cv::merge(channels, F_shift);

    // Magnitude log para visualização
    cv::Mat planes[2];
    cv::split(F_shift, planes);
    cv::Mat mag;
    cv::magnitude(planes[0], planes[1], mag);
    cv::Mat mag_log;
    cv::log(mag + cv::Scalar::all(1.0), mag_log);
    cv::Mat mag_vis;
    cv::normalize(mag_log, mag_vis, 0, 255, cv::NORM_MINMAX, CV_8U);

    // Mascara notch: zera um disco de raio r_notch em cada um dos 4 picos
    cv::Mat mascara = cv::Mat::ones(h_img, w_img, CV_64F);
    const int r_notch = 8;
    const int cy = h_img / 2;
    const int cx = w_img / 2;

    // Coordenadas relativas dos 4 picos simétricos
    std::vector<std::pair<int, int>> picos = {
        {static_cast<int>(v0), static_cast<int>(u0)},
        {-static_cast<int>(v0), -static_cast<int>(u0)},
        {static_cast<int>(v0), -static_cast<int>(u0)},
        {-static_cast<int>(v0), static_cast<int>(u0)}
    };

    for (const auto& p : picos) {
        int pcx = cx + p.second;
        int pcy = cy + p.first;
        for (int y = 0; y < h_img; y++) {
            for (int x = 0; x < w_img; x++) {
                double dist = std::sqrt(std::pow(y - pcy, 2.0) + std::pow(x - pcx, 2.0));
                if (dist <= r_notch) {
                    mascara.at<double>(y, x) = 0.0;
                }
            }
        }
    }

    cv::Mat mascara_vis;
    mascara.convertTo(mascara_vis, CV_8U, 255.0);

    // Filtragem no domínio da frequência
    // Multiplicar F_shift pela máscara (complexo * real)
    std::vector<cv::Mat> F_channels;
    cv::split(F_shift, F_channels);
    for (int y = 0; y < h_img; y++) {
        for (int x = 0; x < w_img; x++) {
            double m = mascara.at<double>(y, x);
            F_channels[0].at<double>(y, x) *= m;
            F_channels[1].at<double>(y, x) *= m;
        }
    }
    cv::Mat F_filtrado;
    cv::merge(F_channels, F_filtrado);

    // ifftshift
    std::vector<cv::Mat> filt_channels;
    cv::split(F_filtrado, filt_channels);
    filt_channels[0] = ifftshift_2d(filt_channels[0]);
    filt_channels[1] = ifftshift_2d(filt_channels[1]);
    cv::Mat F_filt_shift;
    cv::merge(filt_channels, F_filt_shift);

    // IDFT
    cv::Mat img_rest_f;
    cv::idft(F_filt_shift, img_rest_f, cv::DFT_SCALE | cv::DFT_REAL_OUTPUT);

    // Visualização da imagem restaurada
    cv::Mat img_rest_vis;
    cv::normalize(img_rest_f, img_rest_vis, 0, 255, cv::NORM_MINMAX, CV_8U);

    // PSNR
    double psnr = cv::PSNR(img_gray_cv, img_rest_vis);
    std::cout << "PSNR (original vs restaurada): " << psnr << " dB" << std::endl;

    // Exibir resultados
    std::vector<mm::Image> imagens;
    imagens.push_back(mm::Image(img_ruidosa.rows, img_ruidosa.cols, 1));
    std::memcpy(imagens[0].data.data(), img_ruidosa.data, imagens[0].data.size());

    imagens.push_back(mm::Image(mag_vis.rows, mag_vis.cols, 1));
    std::memcpy(imagens[1].data.data(), mag_vis.data, imagens[1].data.size());

    imagens.push_back(mm::Image(mascara_vis.rows, mascara_vis.cols, 1));
    std::memcpy(imagens[2].data.data(), mascara_vis.data, imagens[2].data.size());

    imagens.push_back(mm::Image(img_rest_vis.rows, img_rest_vis.cols, 1));
    std::memcpy(imagens[3].data.data(), img_rest_vis.data, imagens[3].data.size());

    std::vector<std::string> titulos = {
        "Com ruído periódico",
        "Espectro (log)",
        "Máscara notch",
        "Restaurada"
    };

    mm::show(imagens, MM_OUT, titulos, 4);

    return 0;
}

