//| fig-cap: "Análise espacial de degradação: imagens reconstruídas e respectivos mapas de erro absoluto normalizados para diferentes fatores de qualidade JPEG."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <vector>
#include <string>
#include <cmath>
#include "morph.hpp"

// Função SSIM (Wang et al.) com janela Gaussiana
cv::Mat compute_ssim_map(const cv::Mat& img1, const cv::Mat& img2) {
    // Converte para float
    cv::Mat I1, I2;
    img1.convertTo(I1, CV_32F);
    img2.convertTo(I2, CV_32F);

    // Parâmetros SSIM
    double C1 = 6.5025, C2 = 58.5225; // (0.01*255)^2, (0.03*255)^2

    // Janela Gaussiana
    cv::Mat window = cv::getGaussianKernel(11, 1.5);
    cv::Mat window2D = window * window.t();

    // Médias locais
    cv::Mat mu1, mu2;
    cv::filter2D(I1, mu1, -1, window2D);
    cv::filter2D(I2, mu2, -1, window2D);

    // Variâncias e covariância
    cv::Mat mu1_sq, mu2_sq, mu1_mu2;
    cv::multiply(mu1, mu1, mu1_sq);
    cv::multiply(mu2, mu2, mu2_sq);
    cv::multiply(mu1, mu2, mu1_mu2);

    cv::Mat sigma1_sq, sigma2_sq, sigma12;
    cv::filter2D(cv::Mat(I1.mul(I1)), sigma1_sq, -1, window2D);
    sigma1_sq -= mu1_sq;
    cv::filter2D(cv::Mat(I2.mul(I2)), sigma2_sq, -1, window2D);
    sigma2_sq -= mu2_sq;
    cv::filter2D(cv::Mat(I1.mul(I2)), sigma12, -1, window2D);
    sigma12 -= mu1_mu2;

    // Mapa SSIM
    cv::Mat ssim_map;
    cv::Mat numerator = (2 * mu1_mu2 + C1).mul(2 * sigma12 + C2);
    cv::Mat denominator = (mu1_sq + mu2_sq + C1).mul(sigma1_sq + sigma2_sq + C2);
    cv::divide(numerator, denominator, ssim_map);

    return ssim_map;
}

// Calcula SSIM global (média do mapa)
double compute_ssim(const cv::Mat& img1, const cv::Mat& img2) {
    cv::Mat ssim_map = compute_ssim_map(img1, img2);
    cv::Scalar mean = cv::mean(ssim_map);
    return mean[0];
}

int main() {
    // Cameraman (asset do capítulo), 256x256 — mesma imagem da trilha py.
    mm::Image img_gray_mm = mm::gray(mm::resize(mm::read("imagens/cameraman.png"), 256, 256));
    cv::Mat img_gray = img_gray_mm;

    std::vector<mm::Image> imgs_ssim;
    std::vector<std::string> titles_ssim;
    imgs_ssim.push_back(img_gray);
    titles_ssim.push_back("Original");

    for (int q : {25, 50, 75, 95}) {
        mm::Image rec_mm = mm::jpegCompress(img_gray_mm, q);  // DCT 8x8 -> quant -> IDCT
        cv::Mat rec = rec_mm;
        double psnr_v = mm::psnr(img_gray_mm, rec_mm);
        double ssim_v = compute_ssim(img_gray, rec);

        // Mapa de erro absoluto normalizado
        cv::Mat diff;
        cv::absdiff(img_gray, rec, diff);
        cv::Mat diff_vis;
        cv::normalize(diff, diff_vis, 0, 255, cv::NORM_MINMAX, CV_8U);

        imgs_ssim.push_back(rec);
        imgs_ssim.push_back(diff_vis);

        char title1[100], title2[100];
        snprintf(title1, sizeof(title1), "Q=%d (PSNR=%.1fdB | SSIM=%.3f)", q, psnr_v, ssim_v);
        snprintf(title2, sizeof(title2), "Mapa de erro (Q=%d) - bordas e blocagem", q);
        titles_ssim.push_back(title1);
        titles_ssim.push_back(title2);
    }

    mm::show(imgs_ssim, MM_OUT, titles_ssim, 3);
    return 0;
}

