    var slShy    = root.querySelector('#sim_ep0208_sl_shy');
    var vlShx    = root.querySelector('#sim_ep0208_vl_shx');
    var vlShy    = root.querySelector('#sim_ep0208_vl_shy');
    var gOrig    = root.querySelector('#sim_ep0208_grid_orig');
