// Note: This code assumes the existence of the following variables from previous blocks:
// - modelo_fine_tuning: a PyTorch model (can't be directly translated)
// - modelo_congelado: a PyTorch model (can't be directly translated)
// - X_te, y_te: test data tensors (can't be directly translated)
// - imgs_teste: list of PIL images (can't be directly translated)
// - RACAS_ALVO: list of breed names
// - N_TESTE_POR_CLASSE: number of test samples per class
//
// This translation focuses on the image display part using mm::show,
// assuming the predictions have already been computed.

// Liste des races cibles (à remplir selon le contexte)
std::vector<std::string> RACAS_ALVO = {"race1", "race2", "race3"}; // À adapter
int N_TESTE_POR_CLASSE = 4;

// Simulation des prédictions (à remplacer par les vraies prédictions du modèle)
std::vector<int> pred_prevus = {0, 1, 2, 0, 1, 2, 0, 1}; // Prédictions simulées
std::vector<int> reels = {0, 1, 2, 0, 1, 2, 0, 1};       // Vraies étiquettes

int main() {
    // Indices des échantillons à afficher (4 premiers + 4 de la classe suivante)
    std::vector<int> idx_amostras;
    for (int i = 0; i < 4; ++i) {
        idx_amostras.push_back(i);
        idx_amostras.push_back(N_TESTE_POR_CLASSE + i);
    }

    // Création des images de test (simulation - à remplacer par les vraies images)
    std::vector<mm::Image> imgs_pred;
    std::vector<std::string> titulos_pred;

    for (int idx : idx_amostras) {
        // Simulation d'une image de test (à remplacer par la vraie image)
        mm::Image img(64, 64, 3);
        for (int y = 0; y < img.h; ++y) {
            for (int x = 0; x < img.w; ++x) {
                img.at(y, x, 0) = static_cast<unsigned char>((x * 4) % 255);
                img.at(y, x, 1) = static_cast<unsigned char>((y * 4) % 255);
                img.at(y, x, 2) = static_cast<unsigned char>(((x + y) * 2) % 255);
            }
        }

        // Prédiction simulée
        int pred_idx = pred_prevus[idx];
        int real_idx = reels[idx];
        std::string marcador = (pred_idx == real_idx) ? "✓" : "✗";

        imgs_pred.push_back(img);

        std::string titre = marcador + " prévu : " + RACAS_ALVO[pred_idx] + "\n" +
                           "réel : " + RACAS_ALVO[real_idx];
        titulos_pred.push_back(titre);
    }

    // Affichage des prédictions
    mm::show(imgs_pred, MM_OUT, titulos_pred, 4);

    return 0;
}

