//| label: fig-05-pipeline-denoising
//| fig-cap: "*Pipeline* completo de remoção de ruído misto: (1) adição de ruído gaussiano e periódico; (2) identificação de picos de interferência no espectro de frequências; (3) aplicação de máscara *notch* com atenuação gaussiana suave; (4) pós-processamento via filtro bilateral para eliminação do ruído estocástico residual."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <cmath>
#include <vector>
#include <string>
#include <iostream>
#include <iomanip>
#include <random>
#include <algorithm>

#include "morph.hpp"

// Função para suprimir pico gaussiano na máscara
static void suprimirPicoGaussiano(cv::Mat& mask, int cy, int cx, double sigma = 3.0) {
    int h = mask.rows;
    int w = mask.cols;
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            double dist = std::sqrt((y - cy) * (y - cy) + (x - cx) * (x - cx));
            double notch = std::exp(-dist * dist / (2 * sigma * sigma));
            mask.at<double>(y, x) *= (1.0 - notch);
        }
    }
}

// Função para SSIM (Wang et al.)
static double computeSSIM(const cv::Mat& img1, const cv::Mat& img2) {
    const double C1 = 6.5025, C2 = 58.5225;
    cv::Mat I1, I2;
    img1.convertTo(I1, CV_32F);
    img2.convertTo(I2, CV_32F);

    cv::Mat I1_2 = I1.mul(I1);
    cv::Mat I2_2 = I2.mul(I2);
    cv::Mat I1_I2 = I1.mul(I2);

    cv::Mat mu1, mu2;
    cv::GaussianBlur(I1, mu1, cv::Size(11, 11), 1.5);
    cv::GaussianBlur(I2, mu2, cv::Size(11, 11), 1.5);

    cv::Mat mu1_2 = mu1.mul(mu1);
    cv::Mat mu2_2 = mu2.mul(mu2);
    cv::Mat mu1_mu2 = mu1.mul(mu2);

    cv::Mat sigma1_2, sigma2_2, sigma12;
    cv::GaussianBlur(I1_2, sigma1_2, cv::Size(11, 11), 1.5);
    sigma1_2 -= mu1_2;

    cv::GaussianBlur(I2_2, sigma2_2, cv::Size(11, 11), 1.5);
    sigma2_2 -= mu2_2;

    cv::GaussianBlur(I1_I2, sigma12, cv::Size(11, 11), 1.5);
    sigma12 -= mu1_mu2;

    cv::Mat t1 = 2 * mu1_mu2 + C1;
    cv::Mat t2 = 2 * sigma12 + C2;
    cv::Mat t3 = t1.mul(t2);

    cv::Mat t1_2 = mu1_2 + mu2_2 + C1;
    cv::Mat t2_2 = sigma1_2 + sigma2_2 + C2;
    cv::Mat t3_2 = t1_2.mul(t2_2);

    cv::Mat ssim_map;
    cv::divide(t3, t3_2, ssim_map);

    cv::Scalar mssim = cv::mean(ssim_map);
    return mssim[0];
}

// Função para shift do espectro (frequência zero no centro)
static void fftShift(cv::Mat& src) {
    int cx = src.cols / 2;
    int cy = src.rows / 2;

    cv::Mat q0(src, cv::Rect(0, 0, cx, cy));
    cv::Mat q1(src, cv::Rect(cx, 0, cx, cy));
    cv::Mat q2(src, cv::Rect(0, cy, cx, cy));
    cv::Mat q3(src, cv::Rect(cx, cy, cx, cy));

    cv::Mat tmp;
    q0.copyTo(tmp);
    q3.copyTo(q0);
    tmp.copyTo(q3);

    q1.copyTo(tmp);
    q2.copyTo(q1);
    tmp.copyTo(q2);
}

// Função para shift inverso
static void ifftShift(cv::Mat& src) {
    fftShift(src); // ffshift e ifftshift são idênticos para tamanhos pares
}

int main() {
    // img_gray é fornecido automaticamente como mm::Image
    // (a declaração será inserida automaticamente antes deste ponto)

    // ── 1. Construção do ruído misto ─────────────────────────────────────────────
    cv::Mat img_gray_mat(img_gray.h, img_gray.w, CV_8UC1, img_gray.data.data());

    std::mt19937 gen(42);
    std::normal_distribution<double> dist_gauss(0.0, 15.0);

    int h_img = img_gray.h;
    int w_img = img_gray.w;

    // Criação das coordenadas de malha
    cv::Mat X2(h_img, w_img, CV_32F);
    cv::Mat Y2(h_img, w_img, CV_32F);
    for (int y = 0; y < h_img; y++) {
        for (int x = 0; x < w_img; x++) {
            X2.at<float>(y, x) = x;
            Y2.at<float>(y, x) = y;
        }
    }

    int u0 = 15, v0 = 10;
    double sigma_gauss = 15.0;

    // Ruído gaussiano e periódico
    cv::Mat ruido_gauss(h_img, w_img, CV_64F);
    cv::Mat ruido_period(h_img, w_img, CV_64F);
    cv::Mat img_noisy_f(h_img, w_img, CV_64F);

    cv::Mat img_gray_f;
    img_gray_mat.convertTo(img_gray_f, CV_64F);

    for (int y = 0; y < h_img; y++) {
        for (int x = 0; x < w_img; x++) {
            ruido_gauss.at<double>(y, x) = dist_gauss(gen);
            double fase = 2 * M_PI * (u0 * X2.at<float>(y, x) / w_img + 
                                       v0 * Y2.at<float>(y, x) / h_img);
            ruido_period.at<double>(y, x) = 30.0 * std::sin(fase);
            img_noisy_f.at<double>(y, x) = img_gray_f.at<double>(y, x) +
                                           ruido_gauss.at<double>(y, x) +
                                           ruido_period.at<double>(y, x);
        }
    }

    cv::Mat img_noisy;
    cv::normalize(img_noisy_f, img_noisy, 0, 255, cv::NORM_MINMAX, CV_8U);

    // ── 2. Espectro e identificação dos picos ────────────────────────────────────
    cv::Mat img_noisy_64f;
    img_noisy.convertTo(img_noisy_64f, CV_64F);

    // FFT 2D
    cv::Mat F_n_complex;
    cv::dft(img_noisy_64f, F_n_complex, cv::DFT_COMPLEX_OUTPUT);

    // Shift do espectro
    std::vector<cv::Mat> F_n_channels;
    cv::split(F_n_complex, F_n_channels);
    fftShift(F_n_channels[0]);
    fftShift(F_n_channels[1]);
    cv::merge(F_n_channels, F_n_complex);

    // Magnitude do espectro
    cv::Mat mag_n;
    cv::magnitude(F_n_channels[0], F_n_channels[1], mag_n);
    mag_n += 1.0;
    cv::log(mag_n, mag_n);
    cv::normalize(mag_n, mag_n, 0, 255, cv::NORM_MINMAX, CV_8U);

    // ── 3. Notch gaussiano nos picos periódicos ──────────────────────────────────
    int cy0 = h_img / 2;
    int cx0 = w_img / 2;
    cv::Mat mascara_notch = cv::Mat::ones(h_img, w_img, CV_64F);

    // Suprimir os 4 picos
    int picos_dy[4] = {v0, -v0, v0, -v0};
    int picos_dx[4] = {u0, -u0, -u0, u0};
    for (int i = 0; i < 4; i++) {
        suprimirPicoGaussiano(mascara_notch, cy0 + picos_dy[i], cx0 + picos_dx[i], 3.0);
    }

    // Aplicar máscara no espectro
    cv::Mat F_n_shifted_real = F_n_channels[0].clone();
    cv::Mat F_n_shifted_imag = F_n_channels[1].clone();

    F_n_shifted_real = F_n_shifted_real.mul(mascara_notch);
    F_n_shifted_imag = F_n_shifted_imag.mul(mascara_notch);

    // Shift inverso
    ifftShift(F_n_shifted_real);
    ifftShift(F_n_shifted_imag);

    // IFFT 2D
    cv::Mat F_filtered[] = {F_n_shifted_real, F_n_shifted_imag};
    cv::Mat F_filtered_complex;
    cv::merge(F_filtered, 2, F_filtered_complex);

    cv::Mat img_notch_f;
    cv::idft(F_filtered_complex, img_notch_f, cv::DFT_SCALE | cv::DFT_REAL_OUTPUT);

    cv::Mat img_notch;
    cv::normalize(img_notch_f, img_notch, 0, 255, cv::NORM_MINMAX, CV_8U);

    // ── 4. Filtro Bilateral: remoção do ruído gaussiano residual ─────────────────
    cv::Mat img_den;
    cv::bilateralFilter(img_notch, img_den, 7, 25, 7);

    // ── Cálculo das Métricas de Validação ────────────────────────────────────────
    double psnr_n = cv::PSNR(img_gray_mat, img_noisy);
    double ssim_n = computeSSIM(img_gray_mat, img_noisy);

    double psnr_no = cv::PSNR(img_gray_mat, img_notch);
    double ssim_no = computeSSIM(img_gray_mat, img_notch);

    double psnr_d = cv::PSNR(img_gray_mat, img_den);
    double ssim_d = computeSSIM(img_gray_mat, img_den);

    // Impressão das métricas
    std::cout << std::setw(20) << "Etapa" << " | " 
              << std::setw(9) << "PSNR (dB)" << " | " 
              << std::setw(6) << "SSIM" << std::endl;
    std::cout << std::string(42, '-') << std::endl;
    std::cout << std::setw(20) << "Ruidosa (gauss+per)" << " | " 
              << std::setw(9) << std::fixed << std::setprecision(2) << psnr_n << " | " 
              << std::setw(6) << std::setprecision(4) << ssim_n << std::endl;
    std::cout << std::setw(20) << "Após notch" << " | " 
              << std::setw(9) << std::fixed << std::setprecision(2) << psnr_no << " | " 
              << std::setw(6) << std::setprecision(4) << ssim_no << std::endl;
    std::cout << std::setw(20) << "Notch + bilateral" << " | " 
              << std::setw(9) << std::fixed << std::setprecision(2) << psnr_d << " | " 
              << std::setw(6) << std::setprecision(4) << ssim_d << std::endl;

    // Preparação das imagens para visualização
    cv::Mat mascara_vis;
    mascara_notch.convertTo(mascara_vis, CV_8U, 255.0);

    // Conversão para mm::Image para visualização
    std::vector<mm::Image> imagens;

    // Original (img_gray já é mm::Image)
    imagens.push_back(img_gray);

    // Ruidosa
    mm::Image img_noisy_mm(img_noisy.rows, img_noisy.cols, 1);
    std::memcpy(img_noisy_mm.data.data(), img_noisy.data, img_noisy_mm.data.size());
    imagens.push_back(img_noisy_mm);

    // Espectro
    mm::Image mag_n_mm(mag_n.rows, mag_n.cols, 1);
    std::memcpy(mag_n_mm.data.data(), mag_n.data, mag_n_mm.data.size());
    imagens.push_back(mag_n_mm);

    // Máscara notch
    mm::Image mascara_mm(mascara_vis.rows, mascara_vis.cols, 1);
    std::memcpy(mascara_mm.data.data(), mascara_vis.data, mascara_mm.data.size());
    imagens.push_back(mascara_mm);

    // Após notch
    mm::Image img_notch_mm(img_notch.rows, img_notch.cols, 1);
    std::memcpy(img_notch_mm.data.data(), img_notch.data, img_notch_mm.data.size());
    imagens.push_back(img_notch_mm);

    // Denoised
    mm::Image img_den_mm(img_den.rows, img_den.cols, 1);
    std::memcpy(img_den_mm.data.data(), img_den.data, img_den_mm.data.size());
    imagens.push_back(img_den_mm);

    std::vector<std::string> titulos = {
        "Original",
        "Ruidosa\nPSNR=" + std::to_string(psnr_n) + " dB",
        "Espectro\n(picos visíveis)",
        "Máscara notch\n(gaussiana suave)",
        "Após notch\nPSNR=" + std::to_string(psnr_no) + " dB",
        "Notch + bilateral\nPSNR=" + std::to_string(psnr_d) + " dB  SSIM=" + std::to_string(ssim_d)
    };

    mm::show(imagens, MM_OUT, titulos, 6);

    return 0;
}

