  <span style="font-weight:600;color:#26241d;">🌊 Simulator: 2D Wavelet Decomposition</span>
  <span class="sim04_w_pill">Haar Transform</span>
</div>

<div style="padding:16px;background:#ffffff;">

  <!-- Controles Superiores -->
  <div style="display:flex; flex-wrap:wrap; gap:14px; align-items:center; margin-bottom:14px; background:#fafaf7; border:1px solid #e9e3d3; border-radius:12px; padding:12px;">
    <div style="display:flex; flex-direction:column; gap:4px;">
      <label style="font-size:11px; font-weight:700; color:#5e5a4a;">Synthetic Pattern</label>
      <select id="wsim_pattern">
        <option value="combined" selected>Combined (shapes + texture)</option>
        <option value="shapes">Shapes (h/v edges)</option>
        <option value="texture">Texture (high frequency)</option>
        <option value="gradient">Smooth gradient</option>
      </select>
    </div>

    <div style="display:flex; flex-direction:column; gap:4px;">
      <label style="font-size:11px; font-weight:700; color:#5e5a4a;">Decomposition Levels</label>
      <div style="display:flex; gap:12px; height:32px; align-items:center;">
        <label style="display:flex; align-items:center; gap:5px; font-size:11.5px; color:#5e5a4a; font-weight:600; cursor:pointer;"><input type="radio" name="wsim_lv" value="1" style="cursor:pointer;"> 1 level</label>
        <label style="display:flex; align-items:center; gap:5px; font-size:11.5px; color:#5e5a4a; font-weight:600; cursor:pointer;"><input type="radio" name="wsim_lv" value="2" checked style="cursor:pointer;"> 2 levels</label>
      </div>
    </div>

    <div style="display:flex; flex-direction:column; gap:4px; flex:1; min-width:160px;">
      <label style="font-size:11px; font-weight:700; color:#5e5a4a;">Contrast Gain: <span id="wsim_gainv" style="font-weight:700; color:#2980b9;">3.0</span></label>
      <input type="range" id="wsim_gain" min="1" max="8" step="0.5" value="3" style="width:100%; height:4px;">
    </div>
  </div>

  <!-- Imagem Original vs Mosaico Wavelet -->
  <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(240px, 1fr)); gap:14px; margin-bottom:14px;">
    <div class="sim04_w_panel" style="text-align:center;">
