#include <iostream>
#include <cmath>
#include <chrono>

// Compile: g++ -O2 -o benchmark benchmark.cpp -lm

constexpr int N = 50'000'000;

double apenas_soma() {
    double a = 3.0, b = 4.0;
    return a + b;
}

double soma_e_sqrt() {
    double a = 3.0, b = 4.0;
    return std::sqrt(a*a + b*b);
}

int main() {
    // Medição da soma simples
    auto start_soma = std::chrono::high_resolution_clock::now();
    volatile double resultado_soma = 0;
    for (int i = 0; i < N; ++i) {
        resultado_soma = apenas_soma();
    }
    auto end_soma = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> t_soma = end_soma - start_soma;

    // Medição da soma + sqrt
    auto start_sqrt = std::chrono::high_resolution_clock::now();
    volatile double resultado_sqrt = 0;
    for (int i = 0; i < N; ++i) {
        resultado_sqrt = soma_e_sqrt();
    }
    auto end_sqrt = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> t_sqrt = end_sqrt - start_sqrt;

    std::cout << "Soma simples       : " << t_soma.count() << " s" << std::endl;
    std::cout << "Soma + sqrt        : " << t_sqrt.count() << " s" << std::endl;
    std::cout << "Razão (sqrt/soma)  : " << t_sqrt.count() / t_soma.count() << "x" << std::endl;

    // Evita otimização do compilador
    std::cout << "Resultados: " << resultado_soma << " " << resultado_sqrt << std::endl;

    return 0;
}

75a67392b390ab3c54f4a338f7c3c49e:
### Filtres Passe-Bas

Les filtres passe-bas atténuent les composantes haute fréquence, ce qui entraîne un lissage de l'image et une réduction du bruit. Après la centralisation du spectre (FFT Shift), la distance de chaque point au centre est donnée par :

$$
D(u,v) = \sqrt{\left(u - \tfrac{M}{2}\right)^2 + \left(v - \tfrac{N}{2}\right)^2}
$$ {#eq-05-dist-centro}

**Filtre idéal (LPFI) :**
$$
H_{\text{ideal}}(u,v) =
\begin{cases}
1, & D(u,v) \leq D_0 \\
0, & D(u,v) > D_0
\end{cases}
$$ {#eq-05-lpf-ideal}

La coupure brutale à $D_0$ introduit des discontinuités dans le domaine fréquentiel, entraînant des oscillations dans le domaine spatial, connues sous le nom de *ringing*. Cet effet est associé à la convolution avec des fonctions à support infini.

**Filtre gaussien (LPFG) :**
$$
H_{\text{gauss}}(u,v) = e^{-D^2(u,v)/(2\sigma^2)}
$$ {#eq-05-lpf-gauss}

La régularité de la fonction gaussienne dans le domaine fréquentiel évite les discontinuités, ce qui élimine le *ringing* et produit une transition progressive entre les fréquences conservées et atténuées.

**Filtre de Butterworth (LPFB) d'ordre $n$ :**
$$
H_{\text{BW}}(u,v) = \frac{1}{1 + \left[D(u,v)/D_0\right]^{2n}}
$$ {#eq-05-lpf-butterworth}

Le paramètre $n$ contrôle la régularité de la transition entre la transmission et la rejection des fréquences. Les petites valeurs produisent des transitions douces, tandis que les grandes valeurs rapprochent le comportement du filtre idéal, avec un risque accru de *ringing*. Un exemple comparatif est présenté à la @fig-05-filtros-passa-baixa..

