#include <opencv2/opencv.hpp>
#include <vector>
#include <string>

#define MM_OUT "fig-05-dct-basis.png"

#include "morph.hpp"

int main() {
    //| label: fig-05-dct-basis
    //| fig-cap: "The Visual Alphabet of JPEG: The 64 basis functions of DCT-II. The DC coefficient is at top-left (smooth). Going down and moving right, the spatial oscillation increases dramatically."
    //| echo: true
    //| output: true

    // Each basis is the IDCT of a single unit coefficient — assembled into an 8×8 mosaic.
    int tile = 32;
    cv::Mat montagem = cv::Mat::zeros(8 * tile, 8 * tile, CV_8UC1);
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            cv::Mat coef = cv::Mat::zeros(8, 8, CV_64F);
            coef.at<double>(i, j) = 1.0;
            cv::Mat base = mm::idct2(coef);
            cv::Mat base_norm;
            cv::normalize(base, base_norm, 0, 255, cv::NORM_MINMAX, CV_8U);
            cv::Mat base_resized;
            cv::resize(base_norm, base_resized, cv::Size(tile, tile), 0, 0, cv::INTER_NEAREST);
            base_resized.copyTo(montagem(cv::Rect(j * tile, i * tile, tile, tile)));
        }
    }

    mm::Image montage_img = montagem;
    std::vector<mm::Image> imgs = {montage_img};
    std::vector<std::string> titles = {"The 64 DCT-II 8×8 bases (DC at top-left)"};
    mm::show(imgs, MM_OUT, titles, 1);

    return 0;
}

