  <!-- Grid de Visualização dos Blocos -->
  <div style="display:flex; gap:12px; flex-wrap:wrap; align-items:flex-start; justify-content:center; margin-bottom:14px;">
    <div class="sim04_dct_panel" style="text-align:center;">
