// Figure caption: "Visual comparison of different descriptors applied to the same image. Each descriptor reveals distinct aspects of the scene."

// Helper function for local binary pattern (simplified uniform LBP implementation)
mm::Image local_binary_pattern(const mm::Image& img, int P, int R, const std::string& method) {
    int h = img.h, w = img.w;
    mm::Image lbp(h, w);

    // Simple uniform LBP implementation
    for (int y = R; y < h - R; y++) {
        for (int x = R; x < w - R; x++) {
            unsigned char center = img.at(y, x);
            int code = 0;
            int transitions = 0;
            std::vector<int> bits(P);

            for (int p = 0; p < P; p++) {
                double theta = 2.0 * M_PI * p / P;
                int xp = static_cast<int>(x + R * std::cos(theta));
                int yp = static_cast<int>(y + R * std::sin(theta));

                // Ensure coordinates are within bounds
                xp = std::max(0, std::min(w - 1, xp));
                yp = std::max(0, std::min(h - 1, yp));

                bits[p] = (img.at(yp, xp) >= center) ? 1 : 0;
            }

            // Count transitions
            for (int p = 0; p < P; p++) {
                if (bits[p] != bits[(p + 1) % P]) {
                    transitions++;
                }
            }

            if (transitions <= 2) {
                // Uniform pattern - compute the bin index
                int sum = 0;
                for (int p = 0; p < P; p++) {
                    sum += bits[p];
                }
                code = sum;
            } else {
                // Non-uniform pattern (P+1 bins for P=8 means uniform patterns get indices 0-9)
                code = P + 1;
            }

            lbp.at(y, x) = static_cast<unsigned char>(code * (255 / (P + 2)));  // Scale for visualization
        }
    }

    return lbp;
}

// Helper function for HOG (simplified implementation)
std::pair<std::vector<double>, mm::Image> hog(const mm::Image& img, int orientations, 
                                                std::pair<int, int> pixels_per_cell,
                                                std::pair<int, int> cells_per_block,
                                                bool visualize) {
    int h = img.h, w = img.w;
    int cell_size_x = pixels_per_cell.first;
    int cell_size_y = pixels_per_cell.second;
    int ncells_x = w / cell_size_x;
    int ncells_y = h / cell_size_y;
    int block_size_x = cells_per_block.first;
    int block_size_y = cells_per_block.second;

    // Compute gradients
    mm::Image grad_x(h, w);
    mm::Image grad_y(h, w);

    for (int y = 1; y < h - 1; y++) {
        for (int x = 1; x < w - 1; x++) {
            grad_x.at(y, x) = static_cast<unsigned char>(
                std::abs((int)img.at(y, x + 1) - (int)img.at(y, x - 1)));
            grad_y.at(y, x) = static_cast<unsigned char>(
                std::abs((int)img.at(y + 1, x) - (int)img.at(y - 1, x)));
        }
    }

    // Compute magnitudes and orientations
    std::vector<std::vector<double>> magnitudes(ncells_y, std::vector<double>(ncells_x, 0.0));
    std::vector<std::vector<int>> orientations_map(ncells_y, std::vector<int>(ncells_x, 0));

    for (int cy = 0; cy < ncells_y; cy++) {
        for (int cx = 0; cx < ncells_x; cx++) {
            double total_mag = 0.0;
            int total_orient = 0;
            int count = 0;

            for (int y = cy * cell_size_y; y < (cy + 1) * cell_size_y; y++) {
                for (int x = cx * cell_size_x; x < (cx + 1) * cell_size_x; x++) {
                    double mag = std::sqrt((double)grad_x.at(y, x) * grad_x.at(y, x) + 
                                          (double)grad_y.at(y, x) * grad_y.at(y, x));
                    double orient = std::atan2(grad_y.at(y, x), grad_x.at(y, x)) * 180.0 / M_PI;
                    if (orient < 0) orient += 180.0;

                    total_mag += mag;
                    total_orient += static_cast<int>(orient / 20.0) % orientations;
                    count++;
                }
            }

            if (count > 0) {
                magnitudes[cy][cx] = total_mag / count;
                orientations_map[cy][cx] = total_orient / count;
            }
        }
    }

    // Build features vector
    std::vector<double> features;
    for (int by = 0; by <= ncells_y - block_size_y; by++) {
        for (int bx = 0; bx <= ncells_x - block_size_x; bx++) {
            for (int cy = by; cy < by + block_size_y; cy++) {
                for (int cx = bx; cx < bx + block_size_x; cx++) {
                    for (int o = 0; o < orientations; o++) {
                        double sum = 0.0;
                        // Simplified: count orientations per cell
                        for (int y = cy * cell_size_y; y < (cy + 1) * cell_size_y; y++) {
                            for (int x = cx * cell_size_x; x < (cx + 1) * cell_size_x; x++) {
                                double grad_mag = std::sqrt((double)grad_x.at(y, x) * grad_x.at(y, x) + 
                                                           (double)grad_y.at(y, x) * grad_y.at(y, x));
                                double orient = std::atan2(grad_y.at(y, x), grad_x.at(y, x)) * 180.0 / M_PI;
                                if (orient < 0) orient += 180.0;
                                if (static_cast<int>(orient / 20.0) % orientations == o) {
                                    sum += grad_mag;
                                }
                            }
                        }
                        features.push_back(sum);
                    }
                }
            }
        }
    }

    mm::Image hog_img(h, w);
    if (visualize) {
        // Create visualization: intensity proportional to gradient magnitude
        double max_mag = 0.0;
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                double mag = std::sqrt((double)grad_x.at(y, x) * grad_x.at(y, x) + 
                                      (double)grad_y.at(y, x) * grad_y.at(y, x));
                if (mag > max_mag) max_mag = mag;
            }
        }

        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                double mag = std::sqrt((double)grad_x.at(y, x) * grad_x.at(y, x) + 
                                      (double)grad_y.at(y, x) * grad_y.at(y, x));
                hog_img.at(y, x) = static_cast<unsigned char>((mag / (max_mag + 1e-8)) * 255.0);
            }
        }
    }

    return {features, hog_img};
}

int main() {
    // Load example image
    mm::Image imagem = mm::read("camera");
    if (imagem.channels == 3) {
        imagem = mm::gray(imagem);
    }

    // Apply LBP descriptor
    mm::Image lbp_img = local_binary_pattern(imagem, 8, 1, "uniform");

    // Normalize LBP and convert to RGB for easier visualization
    int min_val = 255, max_val = 0;
    for (int y = 0; y < lbp_img.h; y++) {
        for (int x = 0; x < lbp_img.w; x++) {
            int v = lbp_img.at(y, x);
            if (v < min_val) min_val = v;
            if (v > max_val) max_val = v;
        }
    }

    mm::Image lbp_rgb(lbp_img.h, lbp_img.w);
    std::vector<unsigned char> cmap = {80, 0, 80, 200, 0, 200, 255, 0, 255, 255, 128, 255,
                                       255, 255, 0, 255, 200, 0, 255, 128, 0, 200, 80, 0};

    for (int y = 0; y < lbp_img.h; y++) {
        for (int x = 0; x < lbp_img.w; x++) {
            double norm = (lbp_img.at(y, x) - min_val) / (max_val - min_val + 1e-8);
            int idx = std::min(7, (int)(norm * 7.999));
            lbp_rgb.at(y, x, 0) = cmap[idx * 3];
            lbp_rgb.at(y, x, 1) = cmap[idx * 3 + 1];
            lbp_rgb.at(y, x, 2) = cmap[idx * 3 + 2];
        }
    }

    // Apply HOG descriptor
    auto hog_result = hog(imagem, 9, {8, 8}, {2, 2}, true);
    std::vector<double> hog_features = hog_result.first;
    mm::Image hog_img = hog_result.second;

    // Standardized display
    mm::show(
        {imagem, lbp_rgb, hog_img},
        MM_OUT,
        {"Imagem Original\n(como o humano vê)",
         "LBP: Textura\n(cada cor = um código LBP)",
         "HOG: Gradientes e Contornos\n(regiões claras = maior intensidade)"},
        3
    );

    std::cout << "Observe como cada descritor destaca propriedades diferentes:\n";
    std::cout << "• LBP: evidencia padrões locais de textura.\n";
    std::cout << "• HOG: evidencia contornos e orientações das bordas.\n";
    std::cout << "• Imagem original: contém apenas os valores de intensidade.\n";

    return 0;
}

