          });

          var formula = 'v2[' + i + '] = max(';
          formula += i > 0 ? v1[i-1] + ', ' : '';
          formula += '<u>' + v1[i] + '</u>';
          formula += i < n-1 ? ', ' + v1[i+1] : '';
          formula += ') = <b>' + val + '</b>';
          hint.innerHTML = formula;
        });

        c.addEventListener('mouseleave', function() {
          c.style.transform = "scale(1)";
          c.style.borderColor = "#2980b9";

          Array.from(divV1.children).forEach(function(child) {
