//| label: fig-05-pipeline-denoising
//| fig-cap: "*Pipeline* completo de remoção de ruído misto: (1) adição de ruído gaussiano e periódico; (2) identificação de picos de interferência no espectro de frequências; (3) aplicação de máscara *notch* com atenuação gaussiana suave; (4) pós-processamento via filtro bilateral para eliminação do ruído estocástico residual."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <iostream>
#include <cmath>
#include <vector>
#include <string>
#include <random>
#include "morph.hpp"

#define MM_OUT "MM_OUT"

// Helper to create meshgrid indices
void meshgrid_indices(int rows, int cols, cv::Mat& yy, cv::Mat& xx) {
    yy = cv::Mat(rows, cols, CV_32S);
    xx = cv::Mat(rows, cols, CV_32S);
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            yy.at<int>(i, j) = i;
            xx.at<int>(i, j) = j;
        }
    }
}

int main() {
    // Cameraman (asset do capítulo), 256x256 — mesma imagem da trilha py.
    mm::Image img_gray_tmp = mm::gray(mm::resize(mm::read("imagens/cameraman.png"), 256, 256));
    cv::Mat img_gray(img_gray_tmp.h, img_gray_tmp.w, CV_8UC1, img_gray_tmp.data.data());
    int h_img = img_gray_tmp.h;
    int w_img = img_gray_tmp.w;

    // ── 1. Ruído misto: gaussiano + periódico ───────────────────────────────────
    std::mt19937 rng(42);
    std::normal_distribution<double> dist(0.0, 15.0);

    double u0 = 15, v0 = 10;
    cv::Mat X2, Y2;
    meshgrid_indices(h_img, w_img, Y2, X2);

    // Ruído gaussiano
    cv::Mat ruido_gauss(h_img, w_img, CV_64F);
    for (int i = 0; i < h_img; i++) {
        for (int j = 0; j < w_img; j++) {
            ruido_gauss.at<double>(i, j) = dist(rng);
        }
    }

    // Ruído periódico
    cv::Mat ruido_period(h_img, w_img, CV_64F);
    for (int i = 0; i < h_img; i++) {
        for (int j = 0; j < w_img; j++) {
            double x2 = X2.at<int>(i, j);
            double y2 = Y2.at<int>(i, j);
            ruido_period.at<double>(i, j) = 30 * std::sin(2 * M_PI * (u0 * x2 / w_img + v0 * y2 / h_img));
        }
    }

    // Imagem ruidosa
    cv::Mat img_float;
    img_gray.convertTo(img_float, CV_64F);
    cv::Mat img_noisy_float = img_float + ruido_gauss + ruido_period;
    cv::Mat img_noisy_mat;
    cv::normalize(img_noisy_float, img_noisy_mat, 0, 255, cv::NORM_MINMAX, CV_8U);
    mm::Image img_noisy(img_noisy_mat);

    // ── 2. Espectro (log-magnitude) da imagem ruidosa ──────────────────────────
    mm::Image mag_n = mm::spectrumMag(img_noisy);

    // ── 3. Máscara notch gaussiana nos 4 picos periódicos ──────────────────────
    int cy0 = h_img / 2, cx0 = w_img / 2;
    cv::Mat mascara_notch = cv::Mat::ones(h_img, w_img, CV_64F);

    // Função auxiliar para suprimir pico gaussiano
    auto suprimir_pico_gaussiano = [&](cv::Mat& mask, int cy, int cx, double sigma = 3.0) {
        cv::Mat yy_m, xx_m;
        meshgrid_indices(mask.rows, mask.cols, yy_m, xx_m);
        cv::Mat yy_d, xx_d;
        yy_m.convertTo(yy_d, CV_64F);
        xx_m.convertTo(xx_d, CV_64F);
        yy_d -= cy;
        xx_d -= cx;
        cv::Mat dist_sq = yy_d.mul(yy_d) + xx_d.mul(xx_d);
        cv::Mat notch;
        cv::exp(-dist_sq / (2 * sigma * sigma), notch);
        mask = mask.mul(1.0 - notch);
    };

    std::vector<std::pair<int,int>> shifts = {{(int)v0, (int)u0}, {-(int)v0, -(int)u0}, {(int)v0, -(int)u0}, {-(int)v0, (int)u0}};
    for (auto& [dy, dx] : shifts) {
        suprimir_pico_gaussiano(mascara_notch, cy0 + dy, cx0 + dx, 3.0);
    }

    // ── 4. Filtragem: notch no domínio da frequência + bilateral ───────────────
    mm::Image img_notch = mm::freqFilter(img_noisy, mascara_notch);
    cv::Mat img_notch_mat(img_notch.h, img_notch.w, CV_8UC1, img_notch.data.data());
    cv::Mat img_den_mat;
    cv::bilateralFilter(img_notch_mat, img_den_mat, 7, 25, 7);

    cv::Mat mascara_vis_mat;
    mascara_notch.convertTo(mascara_vis_mat, CV_8U, 255.0);

    double psnr_n = cv::PSNR(img_gray, img_noisy_mat);
    double psnr_no = cv::PSNR(img_gray, img_notch_mat);
    double psnr_d = cv::PSNR(img_gray, img_den_mat);

    std::cout << "Ruidosa: PSNR=" << psnr_n << " dB | Apos notch: " << psnr_no << " dB | Notch+bilateral: " << psnr_d << " dB" << std::endl;

    // Preparar imagens para visualização
    std::vector<mm::Image> images = {
        img_gray,
        img_noisy,
        mag_n,
        mm::Image(mascara_vis_mat),
        img_notch,
        mm::Image(img_den_mat)
    };

    std::vector<std::string> titles = {
        "Original",
        "Ruidosa (PSNR=" + std::to_string(psnr_n) + " dB)",
        "Espectro (picos visiveis)",
        "Mascara notch (gaussiana)",
        "Apos notch (PSNR=" + std::to_string(psnr_no) + " dB)",
        "Notch + bilateral (PSNR=" + std::to_string(psnr_d) + " dB)"
    };

    mm::show(images, MM_OUT, titles, 6);

    return 0;
}

