#include <algorithm>

// Função auxiliar para conversão em tensores PyTorch
// (Simulação: criamos vetores de índices para simular os tensores)
std::pair<std::vector<int>, std::vector<int>> para_tensor(
    const std::vector<mm::Image>& Ximg, 
    const std::vector<int>& yarr) {
    // Simula tensores: retorna os índices e rótulos
    std::vector<int> indices(Ximg.size());
    for (size_t i = 0; i < Ximg.size(); ++i) indices[i] = i;
    return {indices, yarr};
}

int main() {
    // Simulação dos dados (sem usar scikit-learn diretamente)
    // Supondo que X e y já foram carregados como imagens MNIST

    // 1. Divisão do dataset em dois domínios disjuntos
    std::vector<int> classes_A = {0, 1, 2, 3, 4};
    std::vector<int> classes_B = {5, 6, 7, 8, 9};

    // Simulação: vetores de índices das amostras
    // (Na prática, você filtraria X e y)
    std::vector<mm::Image> X;
    std::vector<int> y;

    // Aqui assumimos que X e y foram carregados previamente
    // e contêm amostras de dígitos 0-9

    // Filtragem por domínios
    std::vector<mm::Image> XA, XB;
    std::vector<int> yA, yB;

    for (size_t i = 0; i < X.size(); ++i) {
        if (std::find(classes_A.begin(), classes_A.end(), y[i]) != classes_A.end()) {
            XA.push_back(X[i]);
            yA.push_back(y[i]);
        } else if (std::find(classes_B.begin(), classes_B.end(), y[i]) != classes_B.end()) {
            XB.push_back(X[i]);
            yB.push_back(y[i] - 5); // Reindexação dos rótulos para o intervalo [0, 4]
        }
    }

    // Divisão em treino e teste (simulação com indices)
    // Aqui faremos uma divisão simples 75%/25%
    std::vector<size_t> idxA(XA.size()), idxB(XB.size());
    for (size_t i = 0; i < XA.size(); ++i) idxA[i] = i;
    for (size_t i = 0; i < XB.size(); ++i) idxB[i] = i;

    std::mt19937 gen(42);
    std::shuffle(idxA.begin(), idxA.end(), gen);
    std::shuffle(idxB.begin(), idxB.end(), gen);

    size_t test_size_A = XA.size() / 4;
    size_t test_size_B = XB.size() / 4;

    std::vector<size_t> idxA_tr(idxA.begin(), idxA.begin() + (XA.size() - test_size_A));
    std::vector<size_t> idxA_te(idxA.begin() + (XA.size() - test_size_A), idxA.end());
    std::vector<size_t> idxB_tr(idxB.begin(), idxB.begin() + (XB.size() - test_size_B));
    std::vector<size_t> idxB_te(idxB.begin() + (XB.size() - test_size_B), idxB.end());

    std::vector<mm::Image> XA_tr, XA_te, XB_tr, XB_te;
    std::vector<int> yA_tr, yA_te, yB_tr, yB_te;

    for (size_t i : idxA_tr) { XA_tr.push_back(XA[i]); yA_tr.push_back(yA[i]); }
    for (size_t i : idxA_te) { XA_te.push_back(XA[i]); yA_te.push_back(yA[i]); }
    for (size_t i : idxB_tr) { XB_tr.push_back(XB[i]); yB_tr.push_back(yB[i]); }
    for (size_t i : idxB_te) { XB_te.push_back(XB[i]); yB_te.push_back(yB[i]); }

    // Simulação de escassez extrema no domínio de destino: apenas 20 amostras de treino
    std::mt19937 rng(0);
    std::vector<size_t> idx_poucos(XB_tr.size());
    for (size_t i = 0; i < XB_tr.size(); ++i) idx_poucos[i] = i;
    std::shuffle(idx_poucos.begin(), idx_poucos.end(), rng);

    std::vector<mm::Image> XB_tr_poucos;
    std::vector<int> yB_tr_poucos;
    for (size_t i = 0; i < 20 && i < XB_tr.size(); ++i) {
        XB_tr_poucos.push_back(XB_tr[idx_poucos[i]]);
        yB_tr_poucos.push_back(yB_tr[idx_poucos[i]]);
    }

    // Exibição de amostras de ambos os domínios
    int n_amostras = 5;

    // Preparar imagens do domínio A
    std::vector<mm::Image> imgs_A;
    std::vector<std::string> titles_A;
    for (int i = 0; i < n_amostras && i < (int)XA_tr.size(); ++i) {
        imgs_A.push_back(XA_tr[i]);
        titles_A.push_back("A: " + std::to_string(yA_tr[i]));
    }

    // Preparar imagens do domínio B
    std::vector<mm::Image> imgs_B;
    std::vector<std::string> titles_B;
    for (int i = 0; i < n_amostras && i < (int)XB_tr_poucos.size(); ++i) {
        imgs_B.push_back(XB_tr_poucos[i]);
        int rotulo_original = yB_tr_poucos[i] + 5;
        titles_B.push_back("B: " + std::to_string(yB_tr_poucos[i]) + 
                          " (orig: " + std::to_string(rotulo_original) + ")");
    }

    // Concatenar e exibir
    std::vector<mm::Image> todas_imgs;
    std::vector<std::string> todos_titles;

    todas_imgs.insert(todas_imgs.end(), imgs_A.begin(), imgs_A.end());
    todas_imgs.insert(todas_imgs.end(), imgs_B.begin(), imgs_B.end());
    todos_titles.insert(todos_titles.end(), titles_A.begin(), titles_A.end());
    todos_titles.insert(todos_titles.end(), titles_B.begin(), titles_B.end());

    // Exibir figura 12x4.5 (aproximado)
    mm::show(todas_imgs, MM_OUT, todos_titles, n_amostras);

    return 0;
}

