#include "morph.hpp"
#include <iostream>
#include <string>
#include <vector>

int main() {
    // img et img_gray sont déjà initialisés ici

    // 1. Coordonnées du pixel cible (ligne, colonne)
    int r = 600, c = 800;

    // 2. Accès direct aux valeurs du pixel
    unsigned char pixel_cinza = img_gray.at(r, c);
    std::cout << "Pixel cible (" << r << ", " << c << "):\n";
    std::cout << "  Tons de gris (scalaire) : " << (int)pixel_cinza << "\n";
    std::cout << "  Coloré (canaux RGB)     : R=" << (int)img.at(r, c, 0) 
              << ", G=" << (int)img.at(r, c, 1) 
              << ", B=" << (int)img.at(r, c, 2) << "\n";

    // 3. Voisinage 3x3 autour de (r, c); le pixel central est entre crochets
    std::cout << "Matrice de voisinage 3x3 (tons de gris):\n";
    for (int dy = -1; dy <= 1; dy++) {
        std::string ligne = "";
        for (int dx = -1; dx <= 1; dx++) {
            unsigned char v = img_gray.at(r + dy, c + dx);
            if (dy == 0 && dx == 0) {
                ligne += "[" + std::to_string((int)v) + "]";
            } else {
                std::string val = std::to_string((int)v);
                while (val.length() < 3) val = " " + val;
                ligne += " " + val + " ";
            }
        }
        std::cout << "  " << ligne << "\n";
    }

    // 4. Marque la position du pixel avec un carré rouge creux (bordure
    //    de 3 px) sur une copie de l'image et affiche (équivalent du
    //    point matplotlib).
    mm::Image marcada = img;
    int cote = 20;   // demi-côté du carré, en pixels
    int epais = 5;   // épaisseur de la bordure

    for (int x = c - cote; x <= c + cote + 1; x++) {
        for (int w = 0; w < epais; w++) {
            marcada.at(r - cote + w, x, 0) = 255;
            marcada.at(r - cote + w, x, 1) = 0;
            marcada.at(r - cote + w, x, 2) = 0;
            marcada.at(r + cote - w, x, 0) = 255;
            marcada.at(r + cote - w, x, 1) = 0;
            marcada.at(r + cote - w, x, 2) = 0;
        }
    }

    for (int y = r - cote; y <= r + cote + 1; y++) {
        for (int w = 0; w < epais; w++) {
            marcada.at(y, c - cote + w, 0) = 255;
            marcada.at(y, c - cote + w, 1) = 0;
            marcada.at(y, c - cote + w, 2) = 0;
            marcada.at(y, c + cote - w, 0) = 255;
            marcada.at(y, c + cote - w, 1) = 0;
            marcada.at(y, c + cote - w, 2) = 0;
        }
    }

    std::string titre = "Localisation du pixel (" + std::to_string(r) + ", " 
                       + std::to_string(c) + ")";
    mm::show(marcada, MM_OUT, titre);

    return 0;
}

