//| fig-cap: "*Pipeline* JPEG simplificado: DCT em blocos 8×8, quantização com diferentes fatores de qualidade e reconstrução via IDCT. Os artefatos de bloco (*blocking artifacts*) tornam-se visualmente evidentes em fatores de qualidade reduzidos ($Q=10$ e $Q=25$)."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <vector>
#include <string>
#include <cstdio>
#include "morph.hpp"

int main() {
    // Pipeline JPEG (DCT 8×8 -> quantização -> IDCT) via mm.jpegCompress.
    std::vector<mm::Image> imgs = {img_gray};
    std::vector<std::string> titles = {"Original"};
    for (int q : {10, 25, 50, 75, 90}) {
        mm::Image rec = mm::jpegCompress(img_gray, q);
        imgs.push_back(rec);
        char title[64];
        std::snprintf(title, sizeof(title), "Q=%d (PSNR=%.1f dB)", q, mm::psnr(img_gray, rec));
        titles.push_back(title);
    }

    mm::show(imgs, MM_OUT, titles, 3);
    return 0;
}

