// Convert image 4x4 (uint8) and asymmetric 3x3 kernel to Python to C++
#include "morph.hpp"
#include <iostream>

int main() {
    // 4x4 image (uint8) and asymmetric 3x3 kernel
    mm::Image img(4, 4);
    for (int y = 0; y < 4; y++) {
        for (int x = 0; x < 4; x++) {
            img.at(y, x) = static_cast<unsigned char>(y * 4 + x + 1);
        }
    }

    mm::Kernel w{{0, 1, 2}, {0, 0, 0}, {0, 0, 0}};
    mm::Image corr = mm::conv(img, w, mm::Border::CONSTANT); // zero outside the image

    std::cout << "Original image:" << std::endl;          std::cout << mm::drawImg(img) << std::endl;
    std::cout << "Kernel:" << std::endl;                  std::cout << mm::drawImg(w) << std::endl;
    std::cout << "Correlation result:" << std::endl;      std::cout << mm::drawImg(corr) << std::endl;

    return 0;
}

