    imgs.push_back(img_src);
    titles.push_back("Original (Cameraman)");

    for (int q : {10, 25, 50, 75, 90}) {
        mm::Image rec = mm::jpegCompress(img_src, q);
        imgs.push_back(rec);
        char buf[64];
        snprintf(buf, sizeof(buf), "Q=%d (PSNR=%.1f dB)", q, mm::psnr(img_src, rec));
