                char buffer[20];
                snprintf(buffer, sizeof(buffer), "[%3d]", v);
                linha += buffer;
            } else {
                char buffer[20];
                snprintf(buffer, sizeof(buffer), " %3d ", v);
                linha += buffer;
            }
        }
        std::cout << "  " << linha << std::endl;
    }

    // 4. Marca a posicao do pixel com um quadrado vermelho vazado (borda de
    //    3 px) numa copia da imagem e exibe (equivalente ao ponto do matplotlib).
    mm::Image marcada = img;
    int lado = 60;   // meio-lado do quadrado, em pixels
    int esp = 3;     // espessura da borda

    // Bordas horizontais (topo e base)
    for (int x = c - lado; x <= c + lado; x++) {
        for (int w = 0; w < esp; w++) {
            // Topo
            marcada.at(r - lado + w, x, 0) = 255;
            marcada.at(r - lado + w, x, 1) = 0;
            marcada.at(r - lado + w, x, 2) = 0;
            // Base
            marcada.at(r + lado - w, x, 0) = 255;
            marcada.at(r + lado - w, x, 1) = 0;
            marcada.at(r + lado - w, x, 2) = 0;
        }
    }

    // Bordas verticais (esquerda e direita)
    for (int y = r - lado; y <= r + lado; y++) {
        for (int w = 0; w < esp; w++) {
            // Esquerda
            marcada.at(y, c - lado + w, 0) = 255;
            marcada.at(y, c - lado + w, 1) = 0;
            marcada.at(y, c - lado + w, 2) = 0;
            // Direita
            marcada.at(y, c + lado - w, 0) = 255;
            marcada.at(y, c + lado - w, 1) = 0;
            marcada.at(y, c + lado - w, 2) = 0;
        }
    }

    std::string titulo = "Localizacao do pixel (" + std::to_string(r) + ", " + std::to_string(c) + ")";
    mm::show(marcada, MM_OUT, titulo);

    return 0;
}

