//| label: fig-05-pipeline-denoising
//| fig-cap: "*Pipeline* completo de remoção de ruído misto: (1) adição de ruído gaussiano e periódico; (2) identificação de picos de interferência no espectro de frequências; (3) aplicação de máscara *notch* com atenuação gaussiana suave; (4) pós-processamento via filtro bilateral para eliminação do ruído estocástico residual."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <vector>
#include <string>
#include <cmath>
#include <random>
#include <cstdio>
#include "morph.hpp"

// Função para suprimir picos gaussianos na máscara
cv::Mat suprimir_pico_gaussiano(const cv::Mat& mask, int cy, int cx, double sigma = 3.0) {
    int h = mask.rows, w = mask.cols;
    cv::Mat yy(h, w, CV_64F), xx(h, w, CV_64F);
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            yy.at<double>(i, j) = i;
            xx.at<double>(i, j) = j;
        }
    }
    cv::Mat diff_y = yy - cy, diff_x = xx - cx;
    cv::Mat dist2;
    cv::multiply(diff_y, diff_y, diff_y);
    cv::multiply(diff_x, diff_x, diff_x);
    cv::add(diff_y, diff_x, dist2);
    dist2 /= (2 * sigma * sigma);
    cv::exp(-dist2, dist2);
    // notch = exp(-dist2)
    cv::Mat result = mask.mul(1.0 - dist2);
    return result;
}

int main() {
    // Carregar imagem Cameraman e redimensionar para 256x256
    cv::Mat img_gray_full = mm::read("imagens/cameraman.png"); // usar cv::imread se disponível
    if (img_gray_full.empty()) {
        // Se falhar, tenta o caminho relativo
        img_gray_full = cv::imread("imagens/cameraman.png", cv::IMREAD_GRAYSCALE);
    }
    cv::Mat img_gray_resized;
    cv::resize(img_gray_full, img_gray_resized, cv::Size(256, 256));
    cv::Mat img_gray = img_gray_resized;

    int h_img = img_gray.rows;
    int w_img = img_gray.cols;

    // ── 1. Ruído misto: gaussiano + periódico ───────────────────────────────────
    std::mt19937 gen(42); // semente fixa
    std::normal_distribution<double> dist(0.0, 15.0);

    cv::Mat ruido_gauss(h_img, w_img, CV_64F);
    for (int i = 0; i < h_img; i++) {
        for (int j = 0; j < w_img; j++) {
            ruido_gauss.at<double>(i, j) = dist(gen);
        }
    }

    int u0 = 15, v0 = 10;
    cv::Mat ruido_period(h_img, w_img, CV_64F);
    for (int i = 0; i < h_img; i++) {
        for (int j = 0; j < w_img; j++) {
            double x = j * 2 * M_PI * u0 / w_img;
            double y = i * 2 * M_PI * v0 / h_img;
            ruido_period.at<double>(i, j) = 30 * sin(x + y);
        }
    }

    // Convertir img_gray a float64 e somar ruídos
    cv::Mat img_gray_64f;
    img_gray.convertTo(img_gray_64f, CV_64F);
    cv::Mat img_noisy_64f = img_gray_64f + ruido_gauss + ruido_period;

    // Clip entre 0 e 255 e converter para uint8
    cv::Mat img_noisy;
    cv::threshold(img_noisy_64f, img_noisy, 0, 0, cv::THRESH_TOZERO); // clip inferior
    cv::threshold(img_noisy, img_noisy, 255, 0, cv::THRESH_TRUNC);    // clip superior
    img_noisy.convertTo(img_noisy, CV_8U);

    // ── 2. Espectro (log-magnitude) da imagem ruidosa ──────────────────────────
    mm::Image img_noisy_mm = img_noisy; // conversão implícita
    mm::Image mag_n_mm = mm::spectrumMag(img_noisy_mm);
    cv::Mat mag_n = mag_n_mm;

    // ── 3. Máscara notch gaussiana nos 4 picos periódicos ──────────────────────
    int cy0 = h_img / 2, cx0 = w_img / 2;
    cv::Mat mascara_notch(h_img, w_img, CV_64F, cv::Scalar(1.0));

    // Vetor de deslocamentos
    std::vector<std::pair<int, int>> deslocamentos = {{v0, u0}, {-v0, -u0}, {v0, -u0}, {-v0, u0}};
    for (auto& d : deslocamentos) {
        int dy = d.first, dx = d.second;
        mascara_notch = suprimir_pico_gaussiano(mascara_notch, cy0 + dy, cx0 + dx, 3.0);
    }

    // ── 4. Filtragem: notch no domínio da frequência + bilateral ───────────────
    mm::Image img_notch_mm = mm::freqFilter(img_noisy_mm, mascara_notch);
    cv::Mat img_notch = img_notch_mm;

    // Aplicar filtro bilateral
    cv::Mat img_den;
    cv::bilateralFilter(img_notch, img_den, 7, 25, 7);

    // Converter máscara para visualização
    cv::Mat mascara_vis_64f = mascara_notch * 255.0;
    cv::Mat mascara_vis;
    mascara_vis_64f.convertTo(mascara_vis, CV_8U);

    // Calcular PSNR
    cv::Mat img_gray_cv = img_gray;
    double psnr_n  = cv::PSNR(img_gray_cv, img_noisy);
    double psnr_no = cv::PSNR(img_gray_cv, img_notch);
    double psnr_d  = cv::PSNR(img_gray_cv, img_den);

    printf("Ruidosa: PSNR=%.2f dB | Apos notch: %.2f dB | Notch+bilateral: %.2f dB\n", 
           psnr_n, psnr_no, psnr_d);

    // Converter tudo para mm::Image para exibição
    mm::Image img_gray_out = img_gray;
    mm::Image img_noisy_out = img_noisy;
    mm::Image mag_n_out = mag_n;
    mm::Image mascara_vis_out = mascara_vis;
    mm::Image img_notch_out = img_notch;
    mm::Image img_den_out = img_den;

    std::vector<mm::Image> imagens = {img_gray_out, img_noisy_out, mag_n_out,
                                       mascara_vis_out, img_notch_out, img_den_out};
    std::vector<std::string> titulos = {
        "Original",
        "Ruidosa (PSNR=" + std::to_string(psnr_n).substr(0, 4) + " dB)",
        "Espectro (picos visiveis)",
        "Mascara notch (gaussiana)",
        "Apos notch (PSNR=" + std::to_string(psnr_no).substr(0, 4) + " dB)",
        "Notch + bilateral (PSNR=" + std::to_string(psnr_d).substr(0, 4) + " dB)"
    };

    mm::show(imagens, MM_OUT, titulos, 6);

    return 0;
}

97993747737dae527878ce198e6d796a:
### Filtri Passa-Basso

I filtri passa-basso attenuano le componenti ad alta frequenza, producendo un appiattimento dell'immagine e una riduzione del rumore. Dopo la centralizzazione dello spettro (FFT Shift), la distanza di ciascun punto dal centro è data da:

$$
D(u,v) = \sqrt{\left(u - \tfrac{M}{2}\right)^2 + \left(v - \tfrac{N}{2}\right)^2}
$$ {#eq-05-dist-centro}

**Filtro Ideale (LPFI):**
$$
H_{\text{ideal}}(u,v) =
\begin{cases}
1, & D(u,v) \leq D_0 \\
0, & D(u,v) > D_0
\end{cases}
$$ {#eq-05-lpf-ideal}

Il taglio netto a $D_0$ introduce discontinuità nel dominio delle frequenze, causando oscillazioni nel dominio spaziale note come *ringing*. Questo effetto è associato alla convoluzione con funzioni a supporto infinito.

**Filtro Gaussiano (LPFG):**
$$
H_{\text{gauss}}(u,v) = e^{-D^2(u,v)/(2\sigma^2)}
$$ {#eq-05-lpf-gauss}

La regolarità della funzione gaussiana nel dominio delle frequenze evita discontinuità, eliminando il *ringing* e producendo una transizione graduale tra frequenze preservate e attenuate.

**Filtro di Butterworth (LPFB) di ordine $n$:**
$$
H_{\text{BW}}(u,v) = \frac{1}{1 + \left[D(u,v)/D_0\right]^{2n}}
$$ {#eq-05-lpf-butterworth}

Il parametro $n$ controlla la gradualità della transizione tra l'attenuazione e il passaggio delle frequenze. Valori piccoli producono transizioni morbide, mentre valori grandi avvicinano il comportamento al filtro ideale, con un maggiore rischio di *ringing*. Un esempio comparativo è mostrato in @fig-05-filtros-passa-baixa.

