#include "morph.hpp"
#include <opencv2/opencv.hpp>
#include <cstdio>
#include <cstring>
#include <vector>
#include <string>
#include <iostream>
#include <iomanip>

int main() {
    // img_coins_gray e img_final já estão inicializados

    // 1. Rotulagem e estatísticas
    cv::Mat labels_mat, stats_mat, centroids_mat;
    // Converter img_final para cv::Mat
    cv::Mat img_final_cv(img_final.h, img_final.w, CV_8UC1, img_final.data.data());
    int n = cv::connectedComponentsWithStats(img_final_cv, labels_mat, stats_mat, centroids_mat, 8);

    // Converter labels de volta para mm::Image
    mm::Image labels(labels_mat.rows, labels_mat.cols, labels_mat.channels());
    std::memcpy(labels.data.data(), labels_mat.data, labels.data.size());

    // 2. Coloração dos componentes
    cv::RNG rng(4);
    std::vector<cv::Vec3b> colors(n);
    for (int i = 0; i < n; i++) {
        colors[i] = cv::Vec3b(rng.uniform(50, 255), rng.uniform(50, 255), rng.uniform(50, 255));
    }
    colors[0] = cv::Vec3b(0, 0, 0);  // fundo preto

    mm::Image img_colored(img_final.h, img_final.w, 3);
    mm::Image img_annotated = img_colored;

    // Colorir os componentes
    for (int y = 0; y < labels.h; y++) {
        for (int x = 0; x < labels.w; x++) {
            int label = labels.at(y, x);
            img_colored.at(y, x, 0) = colors[label][0];
            img_colored.at(y, x, 1) = colors[label][1];
            img_colored.at(y, x, 2) = colors[label][2];
        }
    }

    // 3. Tabela de descritores
    std::cout << "Componentes detectados (excluindo fundo): " << n - 1 << std::endl;
    std::cout << std::setw(4) << "ID" << std::setw(8) << "Área" 
              << std::setw(6) << "cx" << std::setw(6) << "cy" 
              << std::setw(6) << "w" << std::setw(6) << "h" << std::endl;
    std::cout << std::string(42, '-') << std::endl;

    // Converter img_annotated para cv::Mat para desenhar texto
    cv::Mat img_annotated_cv(img_annotated.h, img_annotated.w, CV_8UC3, img_annotated.data.data());

    for (int i = 1; i < n; i++) {
        int area = stats_mat.at<int>(i, cv::CC_STAT_AREA);
        int cx = (int)centroids_mat.at<double>(i, 0);
        int cy = (int)centroids_mat.at<double>(i, 1);
        int w = stats_mat.at<int>(i, cv::CC_STAT_WIDTH);
        int h = stats_mat.at<int>(i, cv::CC_STAT_HEIGHT);

        std::cout << std::setw(4) << i << std::setw(8) << area 
                  << std::setw(6) << cx << std::setw(6) << cy 
                  << std::setw(6) << w << std::setw(6) << h << std::endl;

        // Desenhar texto com contorno preto e texto azul
        std::string text = std::to_string(i) + ": " + std::to_string(area);
        cv::Point pos(cx - 150, cy + 18);
        cv::putText(img_annotated_cv, text, pos, cv::FONT_HERSHEY_SIMPLEX, 
                    2.0, cv::Scalar(0, 0, 0), 10, cv::LINE_AA);
        cv::putText(img_annotated_cv, text, pos, cv::FONT_HERSHEY_SIMPLEX, 
                    2.0, cv::Scalar(255, 0, 0), 5, cv::LINE_AA);
    }

    // Converter img_annotated de volta para mm::Image (já está atualizado via buffer compartilhado)

    mm::show(
        std::vector<mm::Image>{img_coins_gray, img_final, img_colored, img_annotated},
        MM_OUT,
        std::vector<std::string>{"Original", "Segmentação Final", "Componentes Conexos", "Áreas Anotadas"},
        4
    );

    return 0;
}

