#include "morph.hpp"
#include <iostream>
#include <iomanip>
#include <vector>
#include <algorithm>
#include <numeric>

int main() {
    //#| label: fig-03-equalizacao-didatica
    //#| fig-cap: "Equalização de histograma em imagem 5×5 com 3 bits (L=8): imagem original com tons concentrados em {2,3,4}, imagem equalizada com tons redistribuídos para {1,5,7}, e os respectivos histogramas evidenciando o espalhamento das frequências."
    //#| echo: true
    //#| output: true

    // Cria a imagem 5x5 diretamente
    mm::Image img5(5, 5);
    int vals[5][5] = {{3, 4, 2, 3, 4},
                      {4, 3, 3, 4, 3},
                      {2, 3, 4, 3, 2},
                      {3, 4, 3, 2, 3},
                      {4, 3, 2, 3, 4}};
    for (int y = 0; y < 5; y++)
        for (int x = 0; x < 5; x++)
            img5.at(y, x) = vals[y][x];

    int L = 8;  // 3 bits: níveis 0..7

    // 1. Histograma com tamanho garantido até L
    std::vector<int> h = mm::hist(img5, 3);  // B=3 → 2³=8 níveis, tamanho garantido

    // 2. Probabilidade de cada nível p[k] = h[k] / MN
    int total = std::accumulate(h.begin(), h.end(), 0);
    std::vector<double> p(L);
    for (int k = 0; k < L; k++)
        p[k] = (double)h[k] / total;

    // 3. CDF normalizada
    std::vector<double> cdf(L);
    cdf[0] = p[0];
    for (int k = 1; k < L; k++)
        cdf[k] = cdf[k-1] + p[k]; // cdf[k] = Σ p[j], j=0..k

    // 4. LUT: mapeamento para [0, L-1]
    std::vector<int> lut(L);
    for (int k = 0; k < L; k++)
        lut[k] = (int)std::round(cdf[k] * (L - 1));

    // 5. Aplica LUT pixel a pixel
    mm::Image img5_eq(5, 5);
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++)
            img5_eq.at(i, j) = lut[img5.at(i, j)];  // g[i,j] = lut[f[i,j]]

    std::cout << "Imagem original (5×5, 3 bits):\n";
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++)
            std::cout << (int)img5.at(i, j) << " ";
        std::cout << "\n";
    }
    std::cout << "\n";

    std::cout << std::setw(3) << "k" 
              << std::setw(6) << "h[k]" 
              << std::setw(7) << "p[k]" 
              << std::setw(8) << "CDF[k]" 
              << std::setw(7) << "lut[k]" << "\n";
    std::cout << std::string(3+6+7+8+7, '-') << "\n";
    for (int k = 0; k < L; k++) {
        std::cout << std::setw(3) << k 
                  << std::setw(6) << h[k] 
                  << std::setw(7) << std::fixed << std::setprecision(4) << p[k] 
                  << std::setw(8) << cdf[k] 
                  << std::setw(7) << lut[k] << "\n";
    }
    std::cout << "\n";
    std::cout << "Imagem equalizada (5×5):\n";
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++)
            std::cout << (int)img5_eq.at(i, j) << " ";
        std::cout << "\n";
    }

    // Conta tons distintos
    std::vector<int> orig_vals, eq_vals;
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++) {
            orig_vals.push_back(img5.at(i, j));
            eq_vals.push_back(img5_eq.at(i, j));
        }
    std::sort(orig_vals.begin(), orig_vals.end());
    std::sort(eq_vals.begin(), eq_vals.end());
    auto last_orig = std::unique(orig_vals.begin(), orig_vals.end());
    auto last_eq = std::unique(eq_vals.begin(), eq_vals.end());
    int tons_orig = std::distance(orig_vals.begin(), last_orig);
    int tons_eq = std::distance(eq_vals.begin(), last_eq);

    orig_vals.erase(last_orig, orig_vals.end());
    eq_vals.erase(last_eq, eq_vals.end());

    std::string title1 = "Original (" + std::to_string(tons_orig) + " tons: [";
    for (size_t i = 0; i < orig_vals.size(); i++) {
        title1 += std::to_string(orig_vals[i]);
        if (i < orig_vals.size()-1) title1 += ", ";
    }
    title1 += "])";

    std::string title2 = "Equalizada (" + std::to_string(tons_eq) + " tons: [";
    for (size_t i = 0; i < eq_vals.size(); i++) {
        title2 += std::to_string(eq_vals[i]);
        if (i < eq_vals.size()-1) title2 += ", ";
    }
    title2 += "])";

    mm::show(
        {img5, img5_eq, mm::histImg(img5), mm::histImg(img5_eq)},
        MM_OUT,
        {title1, title2, "Histograma — Original", "Histograma — Equalizada"},
        2
    );

    return 0;
}

