#include <iostream>
#include <algorithm>
#include <vector>
#include <numeric>
#include <cmath>
#include "morph.hpp"

int main() {
    // img_gray já está inicializada

    // Recorta o patch 5×5 a partir de img_gray
    mm::Image patch(5, 5);
    for (int y = 0; y < 5; y++) {
        for (int x = 0; x < 5; x++) {
            patch.at(y, x) = img_gray.at(250 + y, 250 + x);
        }
    }

    // Copia o patch e injeta pixel sal no centro [1,1]
    mm::Image corrompido = patch;
    corrompido.at(1, 1) = 255;

    // Extrai a vizinhança 3×3 centrada em [1,1]
    std::vector<unsigned char> viz_orig, viz_corr;
    for (int y = 0; y < 3; y++) {
        for (int x = 0; x < 3; x++) {
            viz_orig.push_back(patch.at(y, x));
            viz_corr.push_back(corrompido.at(y, x));
        }
    }

    // Ordena as vizinhanças
    std::sort(viz_orig.begin(), viz_orig.end());
    std::sort(viz_corr.begin(), viz_corr.end());

    std::cout << "Patch original:" << std::endl;
    std::cout << mm::drawImg(patch) << std::endl;
    std::cout << "\nPatch com pixel corrompido [1,1]=255:" << std::endl;
    std::cout << mm::drawImg(corrompido) << std::endl;

    // Imprime as vizinhanças ordenadas
    std::cout << "\nVizinhança 3×3 original (ordenada):   [";
    for (size_t i = 0; i < viz_orig.size(); i++) {
        std::cout << (int)viz_orig[i];
        if (i < viz_orig.size() - 1) std::cout << ", ";
    }
    std::cout << "]" << std::endl;
    std::cout << "Mediana original:                       " << (int)viz_orig[4] << std::endl;

    std::cout << "\nVizinhança 3×3 corrompida (ordenada): [";
    for (size_t i = 0; i < viz_corr.size(); i++) {
        std::cout << (int)viz_corr[i];
        if (i < viz_corr.size() - 1) std::cout << ", ";
    }
    std::cout << "]" << std::endl;
    std::cout << "Mediana corrompida:                     " << (int)viz_corr[4] << "  ← ignora o 255" << std::endl;

    // Calcula a média da vizinhança corrompida
    double media_corr = 0.0;
    for (unsigned char v : viz_corr) {
        media_corr += v;
    }
    media_corr /= viz_corr.size();
    std::cout << "Média  corrompida:                  " << media_corr << "  ← distorcida pelo 255" << std::endl;

    return 0;
}

9fbfc89e4d9b4442792f62c1542bd181:
### Transformée *Wavelet* Discrète 2D

La Transformée *Wavelet* Discrète (DWT) applique, séparément dans les directions horizontale et verticale, deux filtres complémentaires : un **passe-bas** $h$ (approximation) et un **passe-haut** $g$ (détails), suivis d'un sous-échantillonnage par un facteur de 2 dans chaque dimension. Ce processus produit quatre sous-bandes, dont les noms indiquent la combinaison des filtres appliqués dans chaque direction (L = *Low-pass*, passe-bas ; H = *High-pass*, passe-haut). Les caractéristiques de chaque sous-bande sont résumées dans la @tbl-05-dwt-subbandas.

$$
\text{DWT}(f)=\{\underbrace{\text{LL}}_{\text{approx.}},\;
\underbrace{\text{LH}}_{\text{détails horizontaux}},\;
\underbrace{\text{HL}}_{\text{détails verticaux}},\;
\underbrace{\text{HH}}_{\text{détails diagonaux}}\}.
$$

| Sous-bande | Filtres appliqués | Contenu visuel |
|:---|:---:|:---|
| **LL** | bas × bas | Approximation de l'image (version lissée et réduite) |
| **LH** | bas × haut | Bords horizontaux et variations verticales |
| **HL** | haut × bas | Bords verticaux et variations horizontales |
| **HH** | haut × haut | Détails diagonaux et textures |

: Sous-bandes produites par la Transformée *Wavelet* Discrète 2D (DWT), indiquant les filtres appliqués dans chaque direction et le contenu prédominant de chaque composante. {#tbl-05-dwt-subbandas}

La décomposition peut être appliquée récursivement sur la sous-bande LL, générant une représentation multi-résolution. Après $J$ niveaux, on obtient une structure avec $3J+1$ sous-bandes, où chaque nouveau niveau réduit la résolution de la composante d'approximation.

::: {.callout-note}
### Lien avec les CNN {.unnumbered}

La décomposition multi-résolution des *wavelets* possède une relation conceptuelle avec les représentations hiérarchiques utilisées dans les réseaux de neurones convolutifs (CNN). Dans les deux cas, des étapes successives de filtrage et de réduction de résolution produisent des descriptions de plus en plus abstraites de l'image. Cependant, les ***wavelets* utilisent des filtres mathématiquement définis et reconstructibles**, tandis que les **CNN apprennent leurs filtres pendant l'entraînement**.
:::

