#include <string>
#include "morph.hpp"

int main() {
    // #| label: fig-06-industrial-defeito
    // #| fig-cap: "Defect detection by image subtraction: reference product, image with simulated defect, and detected anomaly mask."
    // #| echo: true
    // #| output: true

    // Reference image (product without defect)
    mm::Image product_gray = mm::read("https://scikit-image.org/docs/stable/_static/img/coffee.png", true);

    // Insertion of simulated defect: dark scratch of 10x100 px
    mm::Image defect_image = product_gray;
    for(int y = 100; y < 110; y++) {
        for(int x = 200; x < 300; x++) {
            defect_image.at(y, x) = static_cast<unsigned char>(0.1 * 255);
        }
    }

    // Detection by subtraction and thresholding
    mm::Image difference(product_gray.h, product_gray.w);
    for(int y = 0; y < product_gray.h; y++) {
        for(int x = 0; x < product_gray.w; x++) {
            difference.at(y, x) = static_cast<unsigned char>(
                std::abs(static_cast<int>(product_gray.at(y, x)) - static_cast<int>(defect_image.at(y, x)))
            );
        }
    }

    double defect_threshold = 0.15;  // adjustable according to the application
    mm::Image detected_defect(product_gray.h, product_gray.w);
    for(int y = 0; y < product_gray.h; y++) {
        for(int x = 0; x < product_gray.w; x++) {
            if(difference.at(y, x) > defect_threshold * 255) {
                detected_defect.at(y, x) = 255;
            }
        }
    }

    mm::show(
        std::vector<mm::Image>{product_gray, defect_image, detected_defect},
        MM_OUT,
        std::vector<std::string>{"Referência", "Com defeito", "Defeito detectado"},
        3
    );

    bool has_defect = false;
    for(int y = 0; y < detected_defect.h && !has_defect; y++) {
        for(int x = 0; x < detected_defect.w; x++) {
            if(detected_defect.at(y, x) > 0) {
                has_defect = true;
                break;
            }
        }
    }

    if(has_defect) {
        std::cout << "Defeito detectado." << std::endl;
    } else {
        std::cout << "Produto conforme." << std::endl;
    }

    return 0;
}

