#include <vector>

int main() {
    // img_gray is already defined (mm::Image)

    // Extract 5x5 patch from img_gray starting at (250,250)
    mm::Image patch(5, 5);
    for (int y = 0; y < 5; y++) {
        for (int x = 0; x < 5; x++) {
            patch.at(y, x) = img_gray.at(250 + y, 250 + x);
        }
    }

    // Convert to float for calculations
    float p[5][5];
    for (int y = 0; y < 5; y++) {
        for (int x = 0; x < 5; x++) {
            p[y][x] = static_cast<float>(patch.at(y, x));
        }
    }

    // Gx at pixel [1,1]: right column - left column (weighted)
    float gx = (p[0][2] + 2*p[1][2] + p[2][2]) - (p[0][0] + 2*p[1][0] + p[2][0]);

    // Gy at pixel [1,1]: bottom row - top row (weighted)
    float gy = (p[2][0] + 2*p[2][1] + p[2][2]) - (p[0][0] + 2*p[0][1] + p[0][2]);

    float mag = std::sqrt(gx*gx + gy*gy);
    float theta = std::atan2(gy, gx) * 180.0f / M_PI;

    std::cout << "Patch 5x5:" << std::endl;
    std::cout << mm::drawImg(patch) << std::endl;
    std::cout << "Gx em [1,1]: (" << static_cast<int>(p[0][2]) << " + 2*" << static_cast<int>(p[1][2]) 
              << " + " << static_cast<int>(p[2][2]) << ") - (" << static_cast<int>(p[0][0]) 
              << " + 2*" << static_cast<int>(p[1][0]) << " + " << static_cast<int>(p[2][0]) 
              << ") = " << gx << std::endl;
    std::cout << "Gy em [1,1]: (" << static_cast<int>(p[2][0]) << " + 2*" << static_cast<int>(p[2][1]) 
              << " + " << static_cast<int>(p[2][2]) << ") - (" << static_cast<int>(p[0][0]) 
              << " + 2*" << static_cast<int>(p[0][1]) << " + " << static_cast<int>(p[0][2]) 
              << ") = " << gy << std::endl;

    // Note: using mag prefix instead of | to avoid breaking Quarto table parser
    std::cout << "mag(Grad f) = sqrt(" << gx << "^2 + " << gy << "^2) = " << mag << std::endl;
    std::cout << "Theta = arctan(" << gy << "/" << gx << ") = " << theta << " graus" << std::endl;

    return 0;
}

