//| label: fig-05-dft-intro
//| fig-cap: "Experimento de troca de fase: Imagem A (moedas) e Imagem B (padrão geométrico) reconstruídas com magnitudes e fases trocadas. O resultado mostra que a estrutura visual é **muito mais sensível à fase** do que à magnitude: quando a fase de B é mantida, a imagem resultante preserva a organização espacial de B, mesmo com a magnitude de A. A magnitude, por sua vez, influencia principalmente o contraste e a textura. Observe que a qualidade da reconstrução não é perfeita — há artefatos visíveis —, evidenciando a interdependência entre fase e magnitude para uma representação fiel da imagem."
//| echo: true
//| output: true

// ── Experimento: A Importância da Fase ───────────────────────────────────────
// ── Carregamento da imagem ────────────────────────────────────────────────────
#include <opencv2/opencv.hpp>
#include <opencv2/imgproc.hpp>
#include <filesystem>
#include <iostream>
#include <cmath>
#include <vector>
#include <string>
#include "morph.hpp"

// Helper: fftshift manual para espectro complexo (2 canais: real, imag)
void fftshift_complex(cv::Mat& src) {
    int cx = src.cols / 2;
    int cy = src.rows / 2;
    cv::Mat q0(src, cv::Rect(0, 0, cx, cy));
    cv::Mat q1(src, cv::Rect(cx, 0, src.cols - cx, cy));
    cv::Mat q2(src, cv::Rect(0, cy, cx, src.rows - cy));
    cv::Mat q3(src, cv::Rect(cx, cy, src.cols - cx, src.rows - cy));
    cv::Mat tmp;
    q0.copyTo(tmp);
    q3.copyTo(q0);
    tmp.copyTo(q3);
    q1.copyTo(tmp);
    q2.copyTo(q1);
    tmp.copyTo(q2);
}

void ifftshift_complex(cv::Mat& src) {
    // Mesmo que fftshift para dimensões pares (aqui temos 400x400)
    fftshift_complex(src);
}

int main() {
    std::string url = "https://upload.wikimedia.org/wikipedia/commons/2/25/GAZI.MD.AHAD_11.jpg";
    std::string caminho = "imagens/coins.jpg";

    mm::Image img_obj;
    if (!std::filesystem::exists(caminho)) {
        std::filesystem::create_directories("imagens");
        img_obj = mm::read(url, /*pil=*/true);
        mm::write(img_obj, caminho);
    } else {
        img_obj = mm::read(caminho, /*pil=*/true);
    }

    // Converte para cv::Mat e depois para escala de cinza
    cv::Mat img_color_mat = img_obj;  // conversão implícita mm::Image -> cv::Mat
    cv::Mat gray_mat;
    cv::cvtColor(img_color_mat, gray_mat, cv::COLOR_BGR2GRAY);
    mm::Image img_gray(gray_mat);

    cv::Mat img_a;
    cv::resize(gray_mat, img_a, cv::Size(400, 400));

    // Criar uma imagem B sintética (padrão geométrico)
    cv::Mat img_b = cv::Mat::zeros(400, 400, CV_8UC1);
    cv::rectangle(img_b, cv::Point(100, 100), cv::Point(300, 300), cv::Scalar(255), -1);
    cv::circle(img_b, cv::Point(200, 200), 150, cv::Scalar(128), 10);

    // FFT de A e B
    cv::Mat img_a_float, img_b_float;
    img_a.convertTo(img_a_float, CV_32F);
    img_b.convertTo(img_b_float, CV_32F);

    cv::Mat FA_complex, FB_complex;
    cv::dft(img_a_float, FA_complex, cv::DFT_COMPLEX_OUTPUT);
    cv::dft(img_b_float, FB_complex, cv::DFT_COMPLEX_OUTPUT);

    // Fftshift
    fftshift_complex(FA_complex);
    fftshift_complex(FB_complex);

    // Separar canais
    std::vector<cv::Mat> FA_channels, FB_channels;
    cv::split(FA_complex, FA_channels);  // FA_real, FA_imag
    cv::split(FB_complex, FB_channels);  // FB_real, FB_imag

    // Magnitudes e fases
    cv::Mat FA_mag, FA_phase;
    cv::cartToPolar(FA_channels[0], FA_channels[1], FA_mag, FA_phase, true);  // graus? usar radianos com false ou graus com true
    cv::Mat FB_mag, FB_phase;
    cv::cartToPolar(FB_channels[0], FB_channels[1], FB_mag, FB_phase, true);

    // ⚠ Recalcular com ângulos em radianos para exp(1j*phase) correto
    cv::cartToPolar(FA_channels[0], FA_channels[1], FA_mag, FA_phase, false); // rad
    cv::cartToPolar(FB_channels[0], FB_channels[1], FB_mag, FB_phase, false); // rad

    // Reconstruir: |FA| * exp(i * fase_B)
    cv::Mat FA_real_mag, FA_imag_mag;
    cv::polarToCart(FA_mag, FB_phase, FA_real_mag, FA_imag_mag, false);

    // Reconstruir: |FB| * exp(i * fase_A)
    cv::Mat FB_real_mag, FB_imag_mag;
    cv::polarToCart(FB_mag, FA_phase, FB_real_mag, FB_imag_mag, false);

    // Juntar e fazer ifftshift e IDFT
    cv::Mat rec_A_mag_B_fase_complex, rec_B_mag_A_fase_complex;
    cv::Mat rec_A_mag_B_fase_2ch[] = {FA_real_mag, FA_imag_mag};
    cv::merge(rec_A_mag_B_fase_2ch, 2, rec_A_mag_B_fase_complex);
    cv::Mat rec_B_mag_A_fase_2ch[] = {FB_real_mag, FB_imag_mag};
    cv::merge(rec_B_mag_A_fase_2ch, 2, rec_B_mag_A_fase_complex);

    ifftshift_complex(rec_A_mag_B_fase_complex);
    ifftshift_complex(rec_B_mag_A_fase_complex);

    cv::Mat rec_A_mag_B_fase_float, rec_B_mag_A_fase_float;
    cv::idft(rec_A_mag_B_fase_complex, rec_A_mag_B_fase_float, cv::DFT_SCALE | cv::DFT_REAL_OUTPUT);
    cv::idft(rec_B_mag_A_fase_complex, rec_B_mag_A_fase_float, cv::DFT_SCALE | cv::DFT_REAL_OUTPUT);

    // Converter para 8-bit
    cv::Mat rec_A_mag_B_fase_8u, rec_B_mag_A_fase_8u;
    rec_A_mag_B_fase_float.convertTo(rec_A_mag_B_fase_8u, CV_8UC1);
    rec_B_mag_A_fase_float.convertTo(rec_B_mag_A_fase_8u, CV_8UC1);

    // Mostrar
    std::vector<mm::Image> imgs_display = {
        mm::Image(img_a),
        mm::Image(img_b),
        mm::Image(rec_A_mag_B_fase_8u),
        mm::Image(rec_B_mag_A_fase_8u)
    };
    mm::show(imgs_display,
             MM_OUT,
             {"Imagem A", "Imagem B", "Mag(A) + Fase(B)", "Mag(B) + Fase(A)"},
             4);

    std::cout << "💡 A fase preserva bordas e contornos; a magnitude controla contraste e" << std::endl;
    std::cout << "textura. Em áudio estéreo, a fase afeta a localização espacial; em" << std::endl;
