// Compile: g++ -std=c++17 -o fig02 fig02.cpp -I. -I/usr/include/opencv4 $(pkg-config --cflags --libs opencv4) -lm
#include <iostream>
#include <string>
#include <vector>
#include <numeric>
#include <algorithm>
#include "morph.hpp"

int main() {
    // https://commons.wikimedia.org/wiki/File:Mandrill-k-means.png
    std::string url    = "https://upload.wikimedia.org/wikipedia/commons/a/ab/Mandrill-k-means.png";
    std::string caminho = "imagens/mandrill.png";

    // ── Leitura RGB ───────────────────────────────────────────────────────────────
    mm::Image img_rgb;

    // Verifica se o arquivo existe (simplificação: tenta ler diretamente)
    try {
        img_rgb = mm::read(caminho);  // Tenta ler do disco
    } catch (...) {
        // Se falhar, baixa da URL
        img_rgb = mm::read(url);
        // Salva localmente
        mm::write(img_rgb, caminho);
    }

    // Converte para RGB (se necessário)
    // mm::Image já está em RGB por padrão

    // ── Criação do canal alfa (gradiente horizontal) ──────────────────────────────
    int h = img_rgb.h;
    int w = img_rgb.w;

    // Cria canal alfa com gradiente horizontal
    mm::Image alpha(h, w);
    for (int y = 0; y < h; ++y) {
        for (int x = 0; x < w; ++x) {
            alpha.at(y, x) = static_cast<unsigned char>((255.0 * x) / (w - 1));
        }
    }

    // Cria imagem RGBA (4 canais)
    mm::Image img_rgba(h, w, 4);
    for (int y = 0; y < h; ++y) {
        for (int x = 0; x < w; ++x) {
            img_rgba.at(y, x, 0) = img_rgb.at(y, x, 0);  // R
            img_rgba.at(y, x, 1) = img_rgb.at(y, x, 1);  // G
            img_rgba.at(y, x, 2) = img_rgb.at(y, x, 2);  // B
            img_rgba.at(y, x, 3) = alpha.at(y, x);       // A
        }
    }

    // ── Diagnóstico ───────────────────────────────────────────────────────────────
    // Calcula faixa de valores para RGB
    int rgb_min = 255, rgb_max = 0;
    for (int y = 0; y < h; ++y) {
        for (int x = 0; x < w; ++x) {
            for (int c = 0; c < 3; ++c) {
                int v = img_rgb.at(y, x, c);
                rgb_min = std::min(rgb_min, v);
                rgb_max = std::max(rgb_max, v);
            }
        }
    }

    // Calcula faixa de valores para RGBA
    int rgba_min = 255, rgba_max = 0;
    for (int y = 0; y < h; ++y) {
        for (int x = 0; x < w; ++x) {
            for (int c = 0; c < 4; ++c) {
                int v = img_rgba.at(y, x, c);
                rgba_min = std::min(rgba_min, v);
                rgba_max = std::max(rgba_max, v);
            }
        }
    }

    std::cout << "RGB   → shape=(" << h << ", " << w << ", 3), dtype=uint8, "
              << "faixa=[" << rgb_min << ", " << rgb_max << "]\n";
    std::cout << "RGBA  → shape=(" << h << ", " << w << ", 4), dtype=uint8, "
              << "faixa=[" << rgba_min << ", " << rgba_max << "]\n";

    // Pixel (0,0)
    std::cout << "Pixel (0,0): RGB=(" 
              << (int)img_rgb.at(0, 0, 0) << ", "
              << (int)img_rgb.at(0, 0, 1) << ", "
              << (int)img_rgb.at(0, 0, 2) << ")  |  RGBA=("
              << (int)img_rgba.at(0, 0, 0) << ", "
              << (int)img_rgba.at(0, 0, 1) << ", "
              << (int)img_rgba.at(0, 0, 2) << ", "
              << (int)img_rgba.at(0, 0, 3) << ")\n";

    // ── Normalização float32 (padrão scikit-image / PyTorch) ──────────────────────
    // Cria versão normalizada em ponto flutuante
    mm::Image img_rgb_norm(h, w, 3);
    for (int y = 0; y < h; ++y) {
        for (int x = 0; x < w; ++x) {
            for (int c = 0; c < 3; ++c) {
                img_rgb_norm.at(y, x, c) = img_rgb.at(y, x, c);
            }
        }
    }

    // Nota: mm::Image usa unsigned char, então normalização requer conversão manual
    // Para fins de diagnóstico, calcula valores normalizados
    std::vector<float> r_vals, g_vals, b_vals;
    for (int y = 0; y < h; ++y) {
        for (int x = 0; x < w; ++x) {
            r_vals.push_back(img_rgb.at(y, x, 0) / 255.0f);
            g_vals.push_back(img_rgb.at(y, x, 1) / 255.0f);
            b_vals.push_back(img_rgb.at(y, x, 2) / 255.0f);
        }
    }

    float min_val = std::min({*std::min_element(r_vals.begin(), r_vals.end()),
                              *std::min_element(g_vals.begin(), g_vals.end()),
                              *std::min_element(b_vals.begin(), b_vals.end())});
    float max_val = std::max({*std::max_element(r_vals.begin(), r_vals.end()),
                              *std::max_element(g_vals.begin(), g_vals.end()),
                              *std::max_element(b_vals.begin(), b_vals.end())});

    std::cout << "\nNormalizado (float32): faixa=[" << min_val << ", " << max_val << "]\n";
    std::cout << "Pixel (0,0) normalizado: (" 
              << img_rgb.at(0, 0, 0) / 255.0f << ", "
              << img_rgb.at(0, 0, 1) / 255.0f << ", "
              << img_rgb.at(0, 0, 2) / 255.0f << ")\n";

    // ── Visualização ──────────────────────────────────────────────────────────────
    std::vector<mm::Image> images = {img_rgb, img_rgba};
    std::vector<std::string> titles = {
        "RGB  —  $M \\times N \\times 3$",
        "RGBA  —  $M \\times N \\times 4$"
    };
    mm::show(images, MM_OUT, titles, 2);

    return 0;
}

