//| label: fig-05-filtros-passa-alta
//| fig-cap: "Filtro passa-alta Gaussiano. (a) Original; (b) Filtro passa-alta (D₀=30) - as bordas das moedas e fundo texturizado são realçados."

// Filtro passa-alta = complemento do passa-baixa Gaussiano, aplicado via FFT.
#include <opencv2/opencv.hpp>
#include <vector>
#include <string>
#include <cmath>
#include "morph.hpp"

#define MM_OUT "output.png"

int main() {
    // img_gray is provided by the environment (mm::Image)

    int M = img_gray.h;
    int N = img_gray.w;
    double D0 = 30.0;

    // Calculate distance center matrix
    cv::Mat D = mm::distCenter(M, N);

    // Gaussian low-pass filter: H = exp(-(D^2) / (2*D0^2))
    cv::Mat D2;
    cv::multiply(D, D, D2);
    cv::Mat H_gauss;
    cv::exp(-D2 / (2.0 * D0 * D0), H_gauss);

    // High-pass = 1 - low-pass
    cv::Mat H_alta = cv::Mat::ones(M, N, CV_64F) - H_gauss;

    // Apply filter via FFT
    mm::Image img_alta = mm::freqFilter(img_gray, H_alta);

    // Show results
    mm::show(std::vector<mm::Image>{img_gray, img_alta},
             MM_OUT,
             {"Original", "Passa-alta Gaussiano ($D_0=30$)"},
             2);

    return 0;
}

