// Compile: g++ -std=c++17 -o main main.cpp
#include <iostream>
#include <filesystem>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>

// Default location for chave_roboflow.txt
const std::string CHAVE_PATH = "chave_roboflow.txt";
// Default dataset path
const std::string DATASET_PATH = "dados/dataset";

// Placeholder for Roboflow project API
class RoboflowProject {
public:
    std::vector<std::string> versions() const {
        // Placeholder - in real code this would query Roboflow API
        return {"v1"};
    }
};

const RoboflowProject projeto; // Global project instance

// Placeholder for counting shapes in dataset
void contar_shapes(const std::filesystem::path& path) {
    if (!std::filesystem::exists(path)) {
        std::cerr << "Dataset path does not exist: " << path << std::endl;
        return;
    }

    int totalImages = 0;
    int totalBoxes = 0;

    for (const auto& entry : std::filesystem::recursive_directory_iterator(path)) {
        if (entry.path().extension() == ".txt") {
            // Count objects in annotation files
            std::ifstream file(entry.path());
            std::string line;
            while (std::getline(file, line)) {
                if (!line.empty()) totalBoxes++;
            }
        } else if (entry.path().extension() == ".jpg" || entry.path().extension() == ".png") {
            totalImages++;
        }
    }

    std::cout << "Total images: " << totalImages << std::endl;
    std::cout << "Total annotated boxes: " << totalBoxes << std::endl;
}

int main() {
    // Clone dataset if not present
    if (!std::filesystem::exists(DATASET_PATH)) {
        std::string cmd = 
            "git clone --no-checkout --depth 1 --filter=blob:none "
            "https://github.com/fzampirolli/pdi-vc.git tmp_repo && "
            "cd tmp_repo && git sparse-checkout set all/cap09/dados/dataset "
            "&& git checkout && cd .. && mkdir -p dados && "
            "cp -r tmp_repo/all/cap09/dados/dataset dados/dataset && "
            "rm -rf tmp_repo";
        std::system(cmd.c_str());
    }

    // Check if chave_roboflow.txt exists
    std::ifstream chaveFile(CHAVE_PATH);
    if (!chaveFile.is_open()) {
        std::cout << "Chave do Roboflow não encontrada: chave_roboflow.txt" << std::endl;
    } else {
        chaveFile.close();

        // Get latest version
        auto versions = projeto.versions();
        if (!versions.empty()) {
            std::string versao_recente = versions.back();
            std::cout << "Versão mais recente: " << versao_recente << std::endl;
        }

        contar_shapes(std::filesystem::path(DATASET_PATH));
    }

    return 0;
}

