#include <opencv2/opencv.hpp>
#include <vector>
#include <string>
#include <cstdio>
#include "morph.hpp"

// Pipeline JPEG (DCT 8×8 -> quantização -> IDCT) via mm.jpegCompress,
// na imagem clássica do Cameraman (asset do capítulo) reduzida a 256×256.

int main() {
    // Carregar e reduzir a imagem do Cameraman (asset do capítulo) para 256×256
    mm::Image img_temp = mm::read("imagens/cameraman.png");
    cv::Mat img_mat = mm::gray(img_temp);
    cv::Mat img_resized;
    cv::resize(img_mat, img_resized, cv::Size(256, 256));
    mm::Image img_src(img_resized);

    std::vector<mm::Image> imgs;
    imgs.push_back(img_src);
    std::vector<std::string> titles;
    titles.push_back("Original (Cameraman)");

    int qualities[] = {10, 25, 50, 75, 90};
    for (int q : qualities) {
        mm::Image rec = mm::jpegCompress(img_src, q);
        imgs.push_back(rec);
        double psnr_val = mm::psnr(img_src, rec);
        char title_buf[64];
        snprintf(title_buf, sizeof(title_buf), "Q=%d (PSNR=%.1f dB)", q, psnr_val);
        titles.push_back(std::string(title_buf));
    }

    mm::show(imgs, MM_OUT, titles, 3);

    return 0;
}

