//| label: fig-05-filtros-passa-alta
//| fig-cap: "Filtro passa-alta Gaussiano. (a) Original; (b) Filtro passa-alta (D₀=30) - as bordas das moedas e fundo texturizado são realçados."

#include <opencv2/opencv.hpp>
#include <vector>
#include <string>
#include <cmath>
#include <algorithm>
#include "morph.hpp"

// Função para aplicar filtro no domínio da frequência (equivalente a aplicar_filtro_freq)
mm::Image aplicar_filtro_freq_cpp(const mm::Image& img, const cv::Mat& H) {
    // Converte mm::Image para cv::Mat (grayscale)
    cv::Mat img_mat(img.h, img.w, CV_8UC1, const_cast<unsigned char*>(img.data.data()));

    // Converte para float e normaliza para [0, 1]
    cv::Mat img_float;
    img_mat.convertTo(img_float, CV_32F, 1.0/255.0);

    // Calcula a DFT
    cv::Mat padded;
    int m = cv::getOptimalDFTSize(img_float.rows);
    int n = cv::getOptimalDFTSize(img_float.cols);
    cv::copyMakeBorder(img_float, padded, 0, m - img_float.rows, 0, n - img_float.cols, cv::BORDER_CONSTANT, cv::Scalar::all(0));

    cv::Mat planes[] = {padded, cv::Mat::zeros(padded.size(), CV_32F)};
    cv::Mat complexI;
    cv::merge(planes, 2, complexI);
    cv::dft(complexI, complexI);

    // Aplica o filtro (H precisa ser do tamanho da imagem padded)
    cv::Mat H_padded;
    cv::resize(H, H_padded, padded.size());

    // Separa planos e aplica filtro
    cv::Mat planes_out[2];
    cv::split(complexI, planes_out);
    cv::Mat filter_real, filter_imag;
    H_padded.convertTo(filter_real, CV_32F);
    filter_imag = cv::Mat::zeros(H_padded.size(), CV_32F);

    cv::Mat filtered_real = planes_out[0].mul(filter_real) - planes_out[1].mul(filter_imag);
    cv::Mat filtered_imag = planes_out[0].mul(filter_imag) + planes_out[1].mul(filter_real);

    cv::Mat filtered[2] = {filtered_real, filtered_imag};
    cv::Mat filtered_complex;
    cv::merge(filtered, 2, filtered_complex);

    // DFT inversa
    cv::Mat result;
    cv::idft(filtered_complex, result, cv::DFT_SCALE);

    // Extrai a parte real
    cv::Mat result_planes[2];
    cv::split(result, result_planes);

    // Recorta para o tamanho original
    cv::Mat result_real = result_planes[0](cv::Rect(0, 0, img.w, img.h)).clone();

    // Normaliza e converte para uint8
    cv::Mat output;
    cv::normalize(result_real, output, 0, 255, cv::NORM_MINMAX, CV_8U);

    // Converte de volta para mm::Image
    mm::Image out_img(img.h, img.w, 1);
    std::memcpy(out_img.data.data(), output.data, out_img.data.size());

    return out_img;
}

// Função para criar filtro Gaussiano passa-baixa e seu complemento (passa-alta)
void criar_filtros_gaussianos(const mm::Image& img, double D0, cv::Mat& H_gauss, cv::Mat& H_alta) {
    int rows = img.h;
    int cols = img.w;

    // Tamanho padded para DFT ótima
    int m = cv::getOptimalDFTSize(rows);
    int n = cv::getOptimalDFTSize(cols);

    // Cria malha de coordenadas centradas
    cv::Mat H(m, n, CV_32F);

    double center_x = (m - 1) / 2.0;
    double center_y = (n - 1) / 2.0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            double dx = i - center_x;
            double dy = j - center_y;
            double dist = std::sqrt(dx*dx + dy*dy);
            H.at<float>(i, j) = std::exp(-dist*dist / (2.0 * D0 * D0));
        }
    }

    // Shift para centrar (fftshift)
    // Filtro passa-alta: complemento do passa-baixa
    H_alta = 1.0 - H;
}

int main() {
    // img_gray já é fornecido (mm::Image)

    // Parâmetro do filtro Gaussiano
    double D0 = 30.0;

    // Cria os filtros
    cv::Mat H_gauss, H_alta;
    criar_filtros_gaussianos(img_gray, D0, H_gauss, H_alta);

    // Filtro passa-alta: complemento do passa-baixa Gaussiano
    // Aplica o filtro passa-alta
    mm::Image img_alta = aplicar_filtro_freq_cpp(img_gray, H_alta);

    mm::show(
        {img_gray, img_alta},
        MM_OUT,
        {"Original", "Passa-alta Gaussiano ($D_0=30$)"},
        2
    );

    return 0;
}

