#include "morph.hpp"
#include <iostream>
#include <iomanip>
#include <string>
#include <vector>

int main() {
    //| label: fig-04-bbox
    //| fig-cap: "*Bounding boxes* dos componentes conexos (`mm.label0`) sobre a segmentação, com coordenadas normalizadas [0,1] (formato YOLO). (A sobreposição na imagem original e o texto ficam na trilha Python.)"
    //| echo: true
    //| output: true

    mm::Image lab = mm::label0(img_final, mm::sebox());

    // Encontra o maior valor do label (n) e dimensões
    int max_val = 0;
    int H = lab.h;
    int W = lab.w;
    for (int i = 0; i < H * W; i++) {
        if ((int)lab.data[i] > max_val) {
            max_val = (int)lab.data[i];
        }
    }
    int n = max_val;

    mm::Image img_bbox = img_final;  // cópia

    std::cout << std::setw(4) << "cls" << std::setw(9) << "cx_n" 
              << std::setw(9) << "cy_n" << std::setw(9) << "w_n" 
              << std::setw(9) << "h_n" << "  ← YOLO" << std::endl;
    std::cout << std::string(46, '-') << std::endl;

    for (int k = 1; k <= n; k++) {
        int x0 = W; int y0 = H; int x1 = 0; int y1 = 0;
        for (int y = 0; y < H; y++) {
            for (int x = 0; x < W; x++) {
                if ((int)lab.at(y, x) == k) {
                    if (x < x0) x0 = x;
                    if (x > x1) x1 = x;
                    if (y < y0) y0 = y;
                    if (y > y1) y1 = y;
                }
            }
        }
        int w = x1 - x0 + 1;
        int h = y1 - y0 + 1;

        std::cout << std::setw(4) << 0 
                  << std::setw(9) << std::fixed << std::setprecision(4) << (x0 + w / 2.0) / W 
                  << std::setw(9) << std::fixed << std::setprecision(4) << (y0 + h / 2.0) / H 
                  << std::setw(9) << std::fixed << std::setprecision(4) << (double)w / W 
                  << std::setw(9) << std::fixed << std::setprecision(4) << (double)h / H 
                  << std::endl;

        // Desenha retângulo (bordas em valor 128)
        for (int x = x0; x <= x1; x++) {
            img_bbox.at(y0, x) = 128;
            img_bbox.at(y1, x) = 128;
        }
        for (int y = y0; y <= y1; y++) {
            img_bbox.at(y, x0) = 128;
            img_bbox.at(y, x1) = 128;
        }
    }

    mm::show(std::vector<mm::Image>{img_coins_gray, img_final, img_bbox},
             MM_OUT,
             std::vector<std::string>{"Original", "Segmentação Final", "Bounding Boxes (YOLO)"},
             3);

    return 0;
}

