// Fonction de distance de Hamming entre deux entiers
int hamming(uint32_t a, uint32_t b) {
    return __builtin_popcount(a ^ b);
}

int main() {
    uint32_t a = 0b01000000001000110110011111101010;
    uint32_t b = 0b10110000001011100100111111100010;
    std::cout << hamming(a, b) << std::endl;
    return 0;
}

