double calculerPrecision(const Modele& modele, XType& X_t, YType& y_t) {
    // Mode évaluation : désactiver la suppression des opérations (à adapter)
    int n_correct = 0;
    for (size_t i = 0; i < X_t.size(); ++i) {
        // Exécution sans gradient (simulation)
        std::vector<float> predic = modele.forward(X_t[i]);
        // Conversion : argmax et comparaison (à adapter)
        if (predic[0] > y_t[i]) n_correct++;
    }
    return static_cast<double>(n_correct) / X_t.size();
}

// Structures placeholder pour l'optimisation (à adapter avec votre bibliothèque)
struct AdamOptimiseur {
