#include "morph.hpp"
#include <algorithm>
#include <iostream>
#include <set>
#include <numeric>
#include <vector>
#include <cmath>
#include <cstring>

//| label: fig-04-watershed-moedas
//| fig-cap: "*Pipeline* *Watershed* para separação de moedas sobrepostas: da máscara binária dilatada até os contornos finais anotados sobre a imagem original."
//| echo: true
//| output: true

int main() {
    mm::Image img_base = img_coins_gray;

    // 1. Simular moedas sobrepostas/conectadas (usando a máscara binária base)
    mm::Image img_sobrepostas = mm::dil(img_final, mm::sebox(40));

    // 2. Abertura morfológica para limpar ruídos
    mm::Image opening = mm::open(img_sobrepostas, mm::sebox(2));

    // 3. Transformada de Distância
    mm::Image dist = mm::dist(opening);
    // Normalizar para visualização
    int max_dist = 0;
    for (int i = 0; i < (int)dist.data.size(); i++) {
        if ((int)dist.data[i] > max_dist) max_dist = dist.data[i];
    }
    mm::Image dist_vis(opening.h, opening.w);
    if (max_dist > 0) {
        for (int i = 0; i < (int)dist.data.size(); i++) {
            dist_vis.data[i] = (unsigned char)(255.0 * (double)dist.data[i] / (double)max_dist);
        }
    } else {
        dist_vis = dist;
    }

    // 4. Picos seguros (Marcadores das moedas)
    mm::Image picos(opening.h, opening.w);
    for (int i = 0; i < (int)dist.data.size(); i++) {
        if ((int)dist.data[i] > (int)(0.5 * max_dist)) {
            picos.data[i] = 255;
        } else {
            picos.data[i] = 0;
        }
    }

    // 5. Execução do Watershed (Ajustado para usar a nova assinatura)
    // Passamos 'opening' direto em mask, pois ela delimita o escopo de expansão das moedas
    mm::Image ws_region = mm::watershed(picos, opening, "region");
    mm::Image ws_line = mm::watershed(picos, opening, "line");

    // 6. Contagem de objetos (Ignora fundo 0)
    std::set<int> label_set;
    for (int i = 0; i < (int)ws_region.data.size(); i++) {
        int v = (int)ws_region.data[i];
        if (v > 0) label_set.insert(v);
    }
    std::vector<int> labels(label_set.begin(), label_set.end());
    std::cout << "Objetos detectados: " << labels.size() << "\n";

    // 7. Anotação Final
    mm::Image img_annotated(img_base.h, img_base.w, 3);
    // Converter grayscale para BGR
    for (int y = 0; y < img_base.h; y++) {
        for (int x = 0; x < img_base.w; x++) {
            unsigned char val = img_base.at(y, x);
            img_annotated.at(y, x, 0) = val;
            img_annotated.at(y, x, 1) = val;
            img_annotated.at(y, x, 2) = val;
        }
    }

    // Para cada label, desenhar texto
    for (size_t idx = 0; idx < labels.size(); idx++) {
        int label_id = labels[idx];
        // Contar pixels da região
        long pixel_count = 0;
        double sum_y = 0.0, sum_x = 0.0;
        for (int y = 0; y < ws_region.h; y++) {
            for (int x = 0; x < ws_region.w; x++) {
                if ((int)ws_region.at(y, x) == label_id) {
                    pixel_count++;
                    sum_y += y;
                    sum_x += x;
                }
            }
        }
        if (pixel_count < 500) continue;

        int cy = (int)(sum_y / pixel_count);
        int cx = (int)(sum_x / pixel_count);

        // Desenhar texto usando cv::putText (sem OpenCV, usamos desenho simples)
        // Desenhar um retângulo verde ao redor da região para indicar o objeto
        // Nota: como não temos OpenCV, vamos apenas desenhar o número em verde
        // Encontrar bounding box da região
        int min_y = ws_region.h, max_y = 0, min_x = ws_region.w, max_x = 0;
        for (int y = 0; y < ws_region.h; y++) {
            for (int x = 0; x < ws_region.w; x++) {
                if ((int)ws_region.at(y, x) == label_id) {
                    min_y = std::min(min_y, y);
                    max_y = std::max(max_y, y);
                    min_x = std::min(min_x, x);
                    max_x = std::max(max_x, x);
                }
            }
        }
        // Desenhar retângulo verde
        for (int y = std::max(0, min_y - 2); y <= std::min(img_annotated.h - 1, max_y + 2); y++) {
            for (int x = std::max(0, min_x - 2); x <= std::min(img_annotated.w - 1, max_x + 2); x++) {
                if (y == std::max(0, min_y - 2) || y == std::min(img_annotated.h - 1, max_y + 2) ||
                    x == std::max(0, min_x - 2) || x == std::min(img_annotated.w - 1, max_x + 2)) {
                    img_annotated.at(y, x, 1) = 255;  // Verde
                    img_annotated.at(y, x, 0) = 0;
                    img_annotated.at(y, x, 2) = 0;
                }
            }
        }
        // Desenhar o número (simplificado - apenas um bloco colorido no centro)
        for (int dy = -5; dy <= 5; dy++) {
            for (int dx = -3; dx <= 3; dx++) {
                int yy = cy + dy;
                int xx = cx + dx;
                if (yy >= 0 && yy < img_annotated.h && xx >= 0 && xx < img_annotated.w) {
                    img_annotated.at(yy, xx, 1) = 255;  // Verde
                    img_annotated.at(yy, xx, 0) = 0;
                    img_annotated.at(yy, xx, 2) = 0;
                }
            }
        }
    }

    // Desenha as linhas de separação em vermelho
    mm::Image mask_ann = mm::dil(ws_line, mm::sebox(5));  // sebox(5) dá 11x11
    for (int y = 0; y < img_annotated.h; y++) {
        for (int x = 0; x < img_annotated.w; x++) {
            if (mask_ann.at(y, x) > 0 && y < img_annotated.h && x < img_annotated.w) {
                img_annotated.at(y, x, 0) = 255;  // Vermelho
                img_annotated.at(y, x, 1) = 0;
                img_annotated.at(y, x, 2) = 0;
            }
        }
    }

    // Exibição
    mm::show(
        std::vector<mm::Image>{img_base, img_sobrepostas, dist_vis, picos, ws_region, img_annotated},
        MM_OUT,
        std::vector<std::string>{"Original", "Sobrepostas", "Distância", "Marcadores", "Watershed", "Anotado"},
        3
    );

    return 0;
}

