      <div class="sim08_reg_legend"><span class="sim08_reg_line" style="border-color:#8a8371;"></span> No clasificado</div>
      <div class="sim08_reg_legend"><span class="sim08_reg_line" style="border-color:#27ae60;"></span> Inlier</div>
      <div class="sim08_reg_legend"><span class="sim08_reg_line" style="border-color:#c0392b;"></span> Outlier</div>
    </div>
  </div>

