#include "morph.hpp"
#include <cmath>
#include <complex>
#include <iostream>
#include <vector>

// Compile: g++ -std=c++17 -o fourier fourier.cpp -lm

mm::Image fft2Shift(const mm::Image& img) {
    int h = img.h, w = img.w;
    mm::Image shifted(h, w);
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            shifted.at(y, x) = img.at((y + h/2) % h, (x + w/2) % w);
        }
    }
    return shifted;
}

mm::Image fft2MagnitudeLog(const mm::Image& img) {
    int h = img.h, w = img.w;
    // Zero-pad to avoid boundary issues (not needed for 128x128)
    std::vector<std::vector<std::complex<double>>> f(h, std::vector<std::complex<double>>(w));

    // Simple 2D FFT using separability (size must be power of 2)
    // 1D FFT along rows
    for (int y = 0; y < h; y++) {
        std::vector<std::complex<double>> row(w);
        for (int x = 0; x < w; x++) row[x] = img.at(y, x);

        // Bit-reversal permutation
        for (int i = 1, j = 0; i < w; i++) {
            int bit = w >> 1;
            for (; j & bit; bit >>= 1) j ^= bit;
            j ^= bit;
            if (i < j) std::swap(row[i], row[j]);
        }

        // Butterfly operations
        for (int len = 2; len <= w; len <<= 1) {
            double angle = -2 * M_PI / len;
            std::complex<double> wlen(cos(angle), sin(angle));
            for (int i = 0; i < w; i += len) {
                std::complex<double> w(1);
                for (int k = 0; k < len/2; k++) {
                    std::complex<double> u = row[i + k];
                    std::complex<double> v = row[i + k + len/2] * w;
                    row[i + k] = u + v;
                    row[i + k + len/2] = u - v;
                    w *= wlen;
                }
            }
        }

        for (int x = 0; x < w; x++) f[y][x] = row[x];
    }

    // 1D FFT along columns
    for (int x = 0; x < w; x++) {
        std::vector<std::complex<double>> col(h);
        for (int y = 0; y < h; y++) col[y] = f[y][x];

        // Bit-reversal permutation
        for (int i = 1, j = 0; i < h; i++) {
            int bit = h >> 1;
            for (; j & bit; bit >>= 1) j ^= bit;
            j ^= bit;
            if (i < j) std::swap(col[i], col[j]);
        }

        // Butterfly operations
        for (int len = 2; len <= h; len <<= 1) {
            double angle = -2 * M_PI / len;
            std::complex<double> wlen(cos(angle), sin(angle));
            for (int i = 0; i < h; i += len) {
                std::complex<double> w(1);
                for (int k = 0; k < len/2; k++) {
                    std::complex<double> u = col[i + k];
                    std::complex<double> v = col[i + k + len/2] * w;
                    col[i + k] = u + v;
                    col[i + k + len/2] = u - v;
                    w *= wlen;
                }
            }
        }

        for (int y = 0; y < h; y++) f[y][x] = col[y];
    }

    // Compute magnitude log
    mm::Image result(h, w);
    double maxVal = 0;
    std::vector<double> mags(h * w);
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            double mag = std::abs(f[y][x]);
            mags[y * w + x] = std::log1p(mag);
            maxVal = std::max(maxVal, mags[y * w + x]);
        }
    }

    // Normalize to 0-255
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            double val = (mags[y * w + x] / maxVal) * 255.0;
            result.at(y, x) = static_cast<unsigned char>(val);
        }
    }

    return fft2Shift(result);
}

int main() {
    // Créer les signaux (comme np.zeros((128,128)) puis assignations)
    mm::Image img_sinal1(128, 128);
    mm::Image img_sinal2(128, 128);

    // img_sinal1[:, 20:25] = 1; img_sinal1[100:105, :] = 1
    for (int y = 0; y < 128; y++)
        for (int x = 20; x < 25; x++)
            img_sinal1.at(y, x) = 255;
    for (int y = 100; y < 105; y++)
        for (int x = 0; x < 128; x++)
            img_sinal1.at(y, x) = 255;

    // img_sinal2[:, 90:95] = 1; img_sinal2[30:35, :] = 1
    for (int y = 0; y < 128; y++)
        for (int x = 90; x < 95; x++)
            img_sinal2.at(y, x) = 255;
    for (int y = 30; y < 35; y++)
        for (int x = 0; x < 128; x++)
            img_sinal2.at(y, x) = 255;

    // Calculer les magnitudes logarithmiques des spectres de Fourier
    mm::Image mag1 = fft2MagnitudeLog(img_sinal1);
    mm::Image mag2 = fft2MagnitudeLog(img_sinal2);

    // Afficher les résultats
    mm::Image img1_gray = mm::gray(img_sinal1);
    mm::Image img2_gray = mm::gray(img_sinal2);

    mm::show({img1_gray, mag1, img2_gray, mag2},
             MM_OUT,
             {"Sinal A", "Espectro A", "Sinal B (Deslocado)", "Espectro B"},
             4);

    return 0;
}

