        : enc1(canais_entrada, base),
          enc2(base, base * 2),
          enc3(base * 2, base * 4),
          pool(2),
          fundo(base * 4, base * 8),
          up3(base * 8, base * 4, 2, 2),
          dec3(base * 8, base * 4),
          up2(base * 4, base * 2, 2, 2),
          dec2(base * 4, base * 2),
          up1(base * 2, base, 2, 2),
          dec1(base * 2, base),
          saida(base, 1, 1) {}

