// Dice loss function
float perda_dice(const Tensor& logits, const Tensor& alvo, float eps = 1e-6) {
    Tensor probs = sigmoid(logits);

    float intersecao = 0.0f;
    float soma_probs = 0.0f;
    float soma_alvo = 0.0f;

    for (size_t i = 0; i < probs.data.size(); ++i) {
        intersecao += probs.data[i] * alvo.data[i];
        soma_probs += probs.data[i];
        soma_alvo += alvo.data[i];
    }

    float dice = (2.0f * intersecao + eps) / (soma_probs + soma_alvo + eps);
    return 1.0f - dice;
}

// Segmentation loss combining BCE and Dice
float perda_segmentacao(const Tensor& logits, const Tensor& alvo) {
    return binary_cross_entropy_with_logits(logits, alvo) + 
           perda_dice(logits, alvo);
}

