#include "morph.hpp"
#include <iostream>
#include <vector>
#include <string>
#include <cmath>

int main() {
    // Imagem de referência (produto sem defeito)
    mm::Image product_color = mm::read("https://scikit-image.org/docs/stable/_static/img/coffee.png");
    mm::Image product_gray = mm::gray(product_color);

    // Inserção de defeito simulado: arranhão escuro de 10×100 px
    mm::Image defect_image = product_gray;
    for (int y = 100; y < 110; y++) {
        for (int x = 200; x < 300; x++) {
            defect_image.at(y, x) = (unsigned char)(0.1 * 255);
        }
    }

    // Detecção por subtração e limiarização
    mm::Image difference(product_gray.h, product_gray.w);
    for (int y = 0; y < product_gray.h; y++) {
        for (int x = 0; x < product_gray.w; x++) {
            difference.at(y, x) = (unsigned char)std::abs((int)product_gray.at(y, x) - (int)defect_image.at(y, x));
        }
    }

    double defect_threshold = 0.15 * 255;  // ajustável conforme a aplicação
    mm::Image detected_defect(product_gray.h, product_gray.w);
    for (int y = 0; y < product_gray.h; y++) {
        for (int x = 0; x < product_gray.w; x++) {
            detected_defect.at(y, x) = (difference.at(y, x) > defect_threshold) ? 255 : 0;
        }
    }

    mm::show(
        std::vector<mm::Image>{product_gray, defect_image, detected_defect},
        MM_OUT,
        std::vector<std::string>{"Referência", "Com defeito", "Defeito detectado"},
        3
    );

    // Vérifie s'il y a des pixels détectés
    bool has_defect = false;
    for (int y = 0; y < detected_defect.h; y++) {
        for (int x = 0; x < detected_defect.w; x++) {
            if (detected_defect.at(y, x) > 0) {
                has_defect = true;
                break;
            }
        }
        if (has_defect) break;
    }

    std::string status = has_defect ? "Defeito detectado." : "Produto conforme.";
    std::cout << status << std::endl;

    return 0;
}

