// Note: This is a translation of the Python code that uses torchviz for graph visualization.
// Since torchviz is a PyTorch-specific visualization tool, we emulate the structure
// with placeholder operations and generate a synthetic visualization.

int main() {
    // 1. Forward pass avec suivi de gradient activé
    // (Simulation: we create a synthetic image representing the computational graph)
    std::cout << "Simulation du forward pass avec suivi de gradient\n";

    // We simulate the graph visualization with a synthetic image
    // representing the computational graph structure
    mm::Image grafo_simples(300, 400, 3);  // Simulated graph image

    // Fill with some pattern to represent the graph
    for (int y = 0; y < grafo_simples.h; y++) {
        for (int x = 0; x < grafo_simples.w; x++) {
            // Simple pattern to represent the graph structure
            if ((x % 50) < 10 || (y % 30) < 5) {
                grafo_simples.at(y, x, 0) = 100;  // R
                grafo_simples.at(y, x, 1) = 150;  // G
                grafo_simples.at(y, x, 2) = 200;  // B
            } else {
                grafo_simples.at(y, x, 0) = 255;  // R
                grafo_simples.at(y, x, 1) = 255;  // G
                grafo_simples.at(y, x, 2) = 255;  // B
            }
        }
    }

    // 2. Grafo basique : flux d'opérations jusqu'à la sortie
    std::cout << "Génération du graphe computationnel\n";
    std::string caminho_simples = "cnn_digitos_grafo_simples.png";

    // 3. Affichage direct dans l'environnement Quarto/Jupyter
    // Le .render() retourne le chemin du fichier PNG généré; nous devons l'ouvrir comme image
    std::cout << "Affichage du graphe computationnel\n";

    // Create a vector with the simulated graph image
    std::vector<mm::Image> images;
    images.push_back(grafo_simples);

    // Show the image with specified size (approximation of figsize)
    mm::show(images, MM_OUT, {"Grafo computationnel de la CNNDigitos"}, 1);

    return 0;
}

