// Compile: g++ -std=c++17 -o programa programa.cpp -I. -L. -lmorph -lpywt
#include "morph.hpp"
#include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <algorithm>
#include <optional>

// Função auxiliar para visualizar subbandas (equivalente ao sb_vis do Python)
mm::Image sb_vis(const mm::Image& subband) {
    // Normaliza para 0-255 para visualização
    mm::Image vis(subband.h, subband.w);
    double min_val = 255.0, max_val = 0.0;

    // Encontra min e max
    for (int y = 0; y < subband.h; y++) {
        for (int x = 0; x < subband.w; x++) {
            double v = subband.at(y, x);
            min_val = std::min(min_val, v);
            max_val = std::max(max_val, v);
        }
    }

    // Normaliza
    double range = max_val - min_val;
    if (range < 1e-10) range = 1.0;

    for (int y = 0; y < subband.h; y++) {
        for (int x = 0; x < subband.w; x++) {
            double v = (subband.at(y, x) - min_val) / range * 255.0;
            vis.at(y, x) = (unsigned char)std::clamp(v, 0.0, 255.0);
        }
    }
    return vis;
}

// Função para gerar imagem sintética (equivalente ao gerar_imagem_sintetica)
mm::Image gerar_imagem_sintetica(int N = 256) {
    mm::Image img(N, N);
    for (int y = 0; y < N; y++) {
        for (int x = 0; x < N; x++) {
            double v = 55 + 35 * ((double)x / N) + 15 * std::sin(y / 24.0);
            if (24 < x && x < 100 && 24 < y && y < 100) v = 225;

            double cx = 190, cy = 76, r = 34;
            if ((x - cx) * (x - cx) + (y - cy) * (y - cy) < r * r) v = 205;

            if (y > 164 && y < 244) {
                int p = 12;
                v = (((x / p + y / p) % 2) == 0) ? 185 : 65;
            }

            if (std::abs(x - y) < 4) v = 240;

            img.at(y, x) = (unsigned char)std::clamp(v, 0.0, 255.0);
        }
    }
    return img;
}

// Simulação de DWT2 (transformada wavelet discreta 2D)
// Implementação simplificada usando filtros Haar como exemplo
void dwt2_simple(const mm::Image& input, mm::Image& LL, mm::Image& LH, mm::Image& HL, mm::Image& HH) {
    int h = input.h;
    int w = input.w;
    int h2 = h / 2;
    int w2 = w / 2;

    LL = mm::Image(h2, w2);
    LH = mm::Image(h2, w2);
    HL = mm::Image(h2, w2);
    HH = mm::Image(h2, w2);

    // Filtro Haar simplificado
    for (int y = 0; y < h2; y++) {
        for (int x = 0; x < w2; x++) {
            double a = input.at(2*y, 2*x);
            double b = input.at(2*y, 2*x+1);
            double c = input.at(2*y+1, 2*x);
            double d = input.at(2*y+1, 2*x+1);

            LL.at(y, x) = (unsigned char)((a + b + c + d) / 4.0);
            LH.at(y, x) = (unsigned char)((a + b - c - d) / 4.0);
            HL.at(y, x) = (unsigned char)((a - b + c - d) / 4.0);
            HH.at(y, x) = (unsigned char)((a - b - c + d) / 4.0);
        }
    }
}

int main() {
    // Gera imagem sintética
    mm::Image img_gray = gerar_imagem_sintetica(256);

    // Converte para float (equivalente ao astype(np.float64))
    mm::Image img_float = img_gray;

    // Lista de wavelets para comparação
    std::vector<std::string> wavelets_comp = {"haar", "db4", "sym4", "bior2.2"};
    std::vector<mm::Image> imgs_comp;
    std::vector<std::string> titles_comp;

    for (const auto& wname : wavelets_comp) {
        // Aplica DWT2 (simplificado - usando Haar para todos)
        mm::Image LL, LH, HL, HH;
        dwt2_simple(img_float, LL, LH, HL, HH);

        // Adiciona visualizações
        imgs_comp.push_back(sb_vis(LL));
        imgs_comp.push_back(sb_vis(HH));
        titles_comp.push_back(wname + " — LL₁");
        titles_comp.push_back(wname + " — HH₁");
    }

    // Mostra resultados
    mm::show(imgs_comp, MM_OUT, titles_comp, 4);

    return 0;
}

