//| label: fig-05-zoom-artefatos
//| fig-cap: "Análise comparativa de artefatos de compressão sob fator de qualidade reduzido ($Q=10$). À esquerda, observa-se o artefato de bloco característico da discretização por DCT no JPEG. À direita, evidencia-se o efeito de atenuação e suavização de bordas intrínseco ao padrão WebP."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <vector>
#include <string>
#include "morph.hpp"

int main() {
    // img_cam is provided externally as mm::Image

    // Converter mm::Image para cv::Mat para processamento
    cv::Mat cam_mat = img_cam;

    // Salvar com baixa qualidade de compressão
    std::vector<int> jpeg_params = {cv::IMWRITE_JPEG_QUALITY, 10};
    cv::imwrite("tmp/zoom_q10.jpg", cam_mat, jpeg_params);

    std::vector<int> webp_params = {cv::IMWRITE_WEBP_QUALITY, 10};
    cv::imwrite("tmp/zoom_q10.webp", cam_mat, webp_params);

    // Função de zoom com recorte e redimensionamento
    auto zoom = [](const cv::Mat& img) {
        cv::Mat cropped = img(cv::Rect(150, 120, 80, 80));
        cv::Mat resized;
        cv::resize(cropped, resized, cv::Size(320, 320), 0, 0, cv::INTER_NEAREST);
        return resized;
    };

    // Carregar imagens comprimidas e aplicar zoom
    cv::Mat cam_gray;
    cv::cvtColor(cam_mat, cam_gray, cv::COLOR_BGR2GRAY);

    cv::Mat z_orig = zoom(cam_gray);

    cv::Mat jpeg_img = cv::imread("tmp/zoom_q10.jpg", cv::IMREAD_GRAYSCALE);
    cv::Mat z_jpeg = zoom(jpeg_img);

    cv::Mat webp_img = cv::imread("tmp/zoom_q10.webp", cv::IMREAD_GRAYSCALE);
    cv::Mat z_webp = zoom(webp_img);

    // Exibir resultados em grade
    std::vector<mm::Image> images = {
        mm::Image(z_orig),
        mm::Image(z_jpeg),
        mm::Image(z_webp)
    };

    std::vector<std::string> titles = {
        "Zoom Original",
        "JPEG Q=10 (Artefato de Bloco)",
        "WebP Q=10 (Suavizacao)"
    };

    mm::show(images, MM_OUT, titles, 3);

    return 0;
}

