#include "morph.hpp"
#include <vector>
#include <algorithm>
#include <numeric>
#include <cmath>
#include <iostream>
#include <string>

// #| label: fig-01-sim-ep0104-estatisticas
// #| fig-cap: "Simulador EP01_04: Estatísticas de Pixels em Matriz Discreta 5x5"
// #| echo: false
// #| output: true

// Simulação interativa não é diretamente traduzível para C++ estático.
// Esta tradução representa a lógica de cálculo estatístico que o simulador executaria.
// A visualização HTML interativa não tem equivalente direto em C++.

int main() {
    // Simula a matriz 5x5 de pixels
    int width = 5, height = 5;
    std::vector<int> pixels(25, 0);

    // Inicialização aleatória (simula o estado inicial do simulador)
    srand(static_cast<unsigned>(time(nullptr)));
    for (int i = 0; i < 25; ++i) {
        pixels[i] = rand() % 256;
    }

    // Calcula estatísticas
    auto updateStats = [&]() {
        int maxVal = *std::max_element(pixels.begin(), pixels.end());
        int minVal = *std::min_element(pixels.begin(), pixels.end());
        double sum = std::accumulate(pixels.begin(), pixels.end(), 0);
        double avgVal = sum / pixels.size();

        std::cout << "=== Estatísticas da Matriz 5x5 ===" << std::endl;
        std::cout << "Valor Máximo: " << maxVal << std::endl;
        std::cout << "Valor Mínimo: " << minVal << std::endl;
        std::cout << "Média Global (µ): " << avgVal << std::endl;
        std::cout << std::endl;

        // Exibe a matriz
        std::cout << "Matriz:" << std::endl;
        for (int y = 0; y < height; ++y) {
            for (int x = 0; x < width; ++x) {
                std::cout << pixels[y * width + x] << "\t";
            }
            std::cout << std::endl;
        }
    };

    // Apresenta o estado inicial
    updateStats();

    // Simula a ação "Aleatório" (botão 🎲)
    std::cout << "\n--- Ação: Aleatório ---" << std::endl;
    for (int i = 0; i < 25; ++i) {
        pixels[i] = rand() % 256;
    }
    updateStats();

    // Simula a ação "Zerar" (botão ⬛)
    std::cout << "\n--- Ação: Zerar (Min = 0) ---" << std::endl;
    std::fill(pixels.begin(), pixels.end(), 0);
    updateStats();

    // Simula a ação "Máximo" (botão ⬜)
    std::cout << "\n--- Ação: Máximo (Max = 255) ---" << std::endl;
    std::fill(pixels.begin(), pixels.end(), 255);
    updateStats();

    // Simula cliques em pixels (incremento de +51)
    std::cout << "\n--- Simulação de cliques (+51 em 3 pixels) ---" << std::endl;
    pixels[0] = (pixels[0] + 51) % 256;
    pixels[12] = (pixels[12] + 51) % 256;
    pixels[24] = (pixels[24] + 51) % 256;
    updateStats();

    return 0;
}

dd0da3a33655afc6dcc7d5a25f3cd8e2:
### Filtros Pasa-Bajos

Los filtros pasa-bajos atenúan los componentes de alta frecuencia, lo que resulta en un suavizado de la imagen y una reducción del ruido. Tras la centralización del espectro (FFT Shift), la distancia de cada punto al centro viene dada por:

$$
D(u,v) = \sqrt{\left(u - \tfrac{M}{2}\right)^2 + \left(v - \tfrac{N}{2}\right)^2}
$$ {#eq-05-dist-centro}

**Filtro Ideal (LPFI):**
$$
H_{\text{ideal}}(u,v) =
\begin{cases}
1, & D(u,v) \leq D_0 \\
0, & D(u,v) > D_0
\end{cases}
$$ {#eq-05-lpf-ideal}

El corte abrupto en $D_0$ introduce discontinuidades en el dominio de la frecuencia, lo que da lugar a oscilaciones en el dominio espacial conocidas como *ringing*. Este efecto está asociado con la convolución con funciones de soporte infinito.

**Filtro Gaussiano (LPFG):**
$$
H_{\text{gauss}}(u,v) = e^{-D^2(u,v)/(2\sigma^2)}
$$ {#eq-05-lpf-gauss}

La suavidad de la función gaussiana en el dominio de la frecuencia evita discontinuidades, lo que elimina el *ringing* y produce una transición gradual entre las frecuencias preservadas y las atenuadas.

**Filtro de Butterworth (LPFB) de orden $n$:**
$$
H_{\text{BW}}(u,v) = \frac{1}{1 + \left[D(u,v)/D_0\right]^{2n}}
$$ {#eq-05-lpf-butterworth}

El parámetro $n$ controla la suavidad de la transición entre el paso y el rechazo de frecuencias. Los valores pequeños producen transiciones suaves, mientras que los valores grandes aproximan el comportamiento del filtro ideal, con un mayor riesgo de *ringing*. En la @fig-05-filtros-passa-baixa. se presenta un ejemplo comparativo.

