#include "morph.hpp"

// Função para garantir download e retornar caminho local
std::string garantir_e_baixar_arquivo(const std::string& nome_arquivo) {
    std::string diretorio_local = "dados/EP07";
    std::string caminho_local = diretorio_local + "/" + nome_arquivo;

    // Criar o diretório local se ele não existir
    if (!std::filesystem::exists(diretorio_local)) {
        std::filesystem::create_directories(diretorio_local);
    }

    // Se o arquivo não existir localmente, baixa do repositório remoto
    if (!std::filesystem::exists(caminho_local)) {
        std::string url_base = "https://raw.githubusercontent.com/fzampirolli/";
        url_base += "pdi-vc/master/all/cap07/dados/EP07";
        std::string url_arquivo = url_base + "/" + nome_arquivo;
        std::cout << "Baixando " << nome_arquivo << " do GitHub..." << std::endl;

        // Download via curl (sistema)
        std::string comando = "curl -L -o \"" + caminho_local + "\" \"" + url_arquivo + "\"";
        int resultado = system(comando.c_str());
        if (resultado != 0) {
            throw std::runtime_error("Erro ao baixar " + nome_arquivo + 
                                    " do GitHub. Verifique a conexão ou a URL.");
        }
    }

    return caminho_local;
}

mm::Image ler_pgm_p2(const std::string& caminho) {
    std::ifstream arquivo(caminho);
    if (!arquivo.is_open()) {
        throw std::runtime_error("Erro ao abrir arquivo: " + caminho);
    }

    // Ler todos os tokens
    std::vector<std::string> linhas;
    std::string palavra;
    while (arquivo >> palavra) {
        linhas.push_back(palavra);
    }

    if (linhas[0] != "P2") {
        throw std::runtime_error("Formato PGM inválido: não é P2");
    }

    int C = std::stoi(linhas[1]);  // largura
    int L = std::stoi(linhas[2]);  // altura
    int maxv = std::stoi(linhas[3]);

    mm::Image img(L, C);
    for (int i = 0; i < L * C; i++) {
        int valor = std::stoi(linhas[4 + i]);
        img.at(i / C, i % C) = static_cast<unsigned char>(valor);
    }

    return img;
}

int main() {
    // Garante o download e obtém o caminho correto
    std::string arq_caso1 = garantir_e_baixar_arquivo("Caso1_Mosaico_Simples.pgm");
    std::string arq_caso2 = garantir_e_baixar_arquivo("Caso2_Mosaico_Misto.pgm");

    // Lê as matrizes PGM
    mm::Image caso1 = ler_pgm_p2(arq_caso1);
    mm::Image caso2 = ler_pgm_p2(arq_caso2);

    mm::show(
        {caso1, caso2},
        MM_OUT,
        {
            "Caso 1: Mosaico Simples\n(2x2 blocos, 1 amostra/classe)",
            "Caso 2: Mosaico Misto\n(3x3 blocos, classes repetidas)",
        },
        2
    );

    return 0;
}

