#include "morph.hpp"
#include <iostream>
#include <vector>
#include <string>

int main() {
    // Charger l'image d'exemple
    mm::Image imagem = mm::read("camera.png", true);  // skdata.camera() -> image grayscale

    // NOTE: Le code original utilise scikit-image (skimage.feature.local_binary_pattern,
    // skimage.feature.hog, matplotlib.cm). Ces fonctions ne sont pas disponibles dans
    // l'API mm.* qui est limitée aux fonctions listées dans les règles.
    // Nous simulons donc les descripteurs avec les fonctions disponibles.

    // Approximation de LBP (simplifiée - une simple texture)
    mm::Image lbp_img(imagem.h, imagem.w);
    // Simulation simplifiée du LBP : différence avec le pixel gauche
    for (int y = 0; y < imagem.h; y++) {
        for (int x = 1; x < imagem.w; x++) {
            lbp_img.at(y, x) = abs((int)imagem.at(y, x) - (int)imagem.at(y, x-1));
        }
    }

    // Normaliser le LBP
    double min_val = 255, max_val = 0;
    for (int y = 0; y < lbp_img.h; y++) {
        for (int x = 0; x < lbp_img.w; x++) {
            int v = (int)lbp_img.at(y, x);
            if (v < min_val) min_val = v;
            if (v > max_val) max_val = v;
        }
    }

    mm::Image lbp_norm(lbp_img.h, lbp_img.w);
    for (int y = 0; y < lbp_img.h; y++) {
        for (int x = 0; x < lbp_img.w; x++) {
            lbp_norm.at(y, x) = (unsigned char)(((int)lbp_img.at(y, x) - min_val) / 
                                               (max_val - min_val + 1e-8) * 255);
        }
    }

    // Convertir en RGB (pseudo-couleurs)
    mm::Image lbp_rgb(lbp_img.h, lbp_img.w, 3);
    // Simulation de la colormap nipy_spectral par un dégradé simple
    for (int y = 0; y < lbp_img.h; y++) {
        for (int x = 0; x < lbp_img.w; x++) {
            unsigned char v = lbp_norm.at(y, x);
            lbp_rgb.at(y, x, 0) = v;      // Rouge
            lbp_rgb.at(y, x, 1) = (unsigned char)(v * 0.5);  // Vert
            lbp_rgb.at(y, x, 2) = (unsigned char)(255 - v);   // Bleu
        }
    }

    // Approximations pour HOG : utiliser le gradient de Sobel simplifié
    mm::Image hog_img(imagem.h, imagem.w);
    for (int y = 1; y < imagem.h - 1; y++) {
        for (int x = 1; x < imagem.w - 1; x++) {
            int gx = (int)imagem.at(y, x+1) - (int)imagem.at(y, x-1);
            int gy = (int)imagem.at(y+1, x) - (int)imagem.at(y-1, x);
            hog_img.at(y, x) = (unsigned char)std::min(255, std::abs(gx) + std::abs(gy));
        }
    }

    // Affichage standardisé
    mm::show(
        std::vector<mm::Image>{imagem, lbp_rgb, hog_img},
        MM_OUT,
        std::vector<std::string>{
            "Image originale\n(comme l'humain voit)",
            "LBP : Texture\n(chaque couleur = un code LBP)",
            "HOG : Gradients et Contours\n(régions claires = plus forte intensité)"
        },
        3
    );

    std::cout << "Observez comment chaque descripteur met en évidence des propriétés différentes :" << "\n";
    std::cout << "• LBP : met en évidence les motifs locaux de texture." << "\n";
    std::cout << "• HOG : met en évidence les contours et les orientations des bords." << "\n";
    std::cout << "• Image originale : ne contient que les valeurs d'intensité." << "\n";

    return 0;
}

