#include <vector>
#include <algorithm>
#include <cstdlib>
#include <ctime>

// Compilar: g++ -o filtro_maximo filtro_maximo.cpp -std=c++11

int main() {
    // Seed para números aleatórios
    std::srand(std::time(nullptr));

    const int n = 8;
    std::vector<int> v1(n);

    // Preencher v1 com valores aleatórios entre 0 e 49
    for (int i = 0; i < n; i++) {
        v1[i] = std::rand() % 50;
    }

    // Print do vetor original
    std::cout << "Vetor v1 (Entrada): ";
    for (int val : v1) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    std::vector<int> v2(n);

    // Calcular filtro de máximo local 1D com janela 1x3
    for (int i = 0; i < n; i++) {
        int max_val = v1[i];
        if (i > 0) {
            max_val = std::max(max_val, v1[i-1]);
        }
        if (i < n-1) {
            max_val = std::max(max_val, v1[i+1]);
        }
        v2[i] = max_val;
    }

    // Print do vetor resultado
    std::cout << "Vetor v2 (Resultado do Máximo): ";
    for (int val : v2) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    // Explicação do processo em formato textual
    std::cout << "\nAnálise da janela de máximo local:\n";
    for (int i = 0; i < n; i++) {
        std::cout << "v2[" << i << "] = max(";
        if (i > 0) {
            std::cout << v1[i-1] << ", ";
        }
        std::cout << "<u>" << v1[i] << "</u>";
        if (i < n-1) {
            std::cout << ", " << v1[i+1];
        }
        std::cout << ") = <b>" << v2[i] << "</b>\n";
    }

    return 0;
}

