//| label: fig-05-zoom-artefatos
//| fig-cap: "Análise comparativa de artefatos de compressão sob fator de qualidade reduzido ($Q=10$). À esquerda, observa-se o artefato de bloco característico da discretização por DCT no JPEG. À direita, evidencia-se o efeito de atenuação e suavização de bordas intrínseco ao padrão WebP."
//| echo: true
//| output: true

#include <opencv2/opencv.hpp>
#include <iostream>
#include <string>
#include <vector>
#include "morph.hpp"  // For mm:: functions and mm::Image/Mat interop

// Helper function: zoom into a region and resize with nearest interpolation
cv::Mat zoom(const cv::Mat& img) {
    // Extract region [120:200, 150:230] and resize to 320x320 with INTER_NEAREST
    cv::Mat roi = img(cv::Rect(150, 120, 80, 80));
    cv::Mat resized;
    cv::resize(roi, resized, cv::Size(320, 320), 0, 0, cv::INTER_NEAREST);
    return resized;
}

int main() {
    // Mesma imagem do pipeline JPEG (Cameraman) — recorte com zoom 4x nearest.
    cv::Mat img_src = mm::gray(mm::resize(mm::read("imagens/cameraman.png"), 256, 256));

    // Save with JPEG quality 10 and WebP quality 10
    cv::imwrite("tmp/zoom_q10.jpg", img_src, {cv::IMWRITE_JPEG_QUALITY, 10});
    cv::imwrite("tmp/zoom_q10.webp", img_src, {cv::IMWRITE_WEBP_QUALITY, 10});

    // Apply zoom to original and compressed versions
    cv::Mat z_orig = zoom(img_src);
    cv::Mat z_jpeg = zoom(cv::imread("tmp/zoom_q10.jpg", cv::IMREAD_GRAYSCALE));
    cv::Mat z_webp = zoom(cv::imread("tmp/zoom_q10.webp", cv::IMREAD_GRAYSCALE));

    // Display the three images side by side
    std::vector<cv::Mat> images = {z_orig, z_jpeg, z_webp};
    std::vector<std::string> titles = {"Zoom Original", "JPEG Q=10 (Artefato de Bloco)", "WebP Q=10 (Suavizacao)"};

    // Convert to mm::Image vector for show (which accepts both types)
    std::vector<mm::Image> imgs;
    for (const auto& m : images) {
        imgs.push_back(mm::Image(m));
    }
    mm::show(imgs, MM_OUT, titles, 3);

    return 0;
}

