#include <string>

mm::Image norm_label(const mm::Image& lbl, int mx) {
    mm::Image out = lbl;
    for (int y = 0; y < lbl.h; y++) {
        for (int x = 0; x < lbl.w; x++) {
            if (lbl.at(y, x)) {
                out.at(y, x) = (unsigned char)((int)lbl.at(y, x) * 255 / mx);
            }
        }
    }
    return out;
}

int main() {
    // Entrada binária: pixels em diagonal formam componentes
    mm::Image f(10, 10);
    f.at(1,1) = 255; f.at(2,2) = 255; f.at(3,3) = 255;
    f.at(3,6) = 255; f.at(3,7) = 255; f.at(4,6) = 255; f.at(4,7) = 255;
    f.at(6,1) = 255; f.at(6,2) = 255; f.at(6,3) = 255;
    f.at(7,1) = 255; f.at(7,3) = 255;
    f.at(8,1) = 255; f.at(8,2) = 255; f.at(8,3) = 255;
    f.at(7,7) = 255; f.at(8,8) = 255;

    mm::Image B4 = mm::secross();   // conectividade-4
    mm::Image B8 = mm::sebox();     // conectividade-8

    mm::Image lbl4 = mm::label0(f, B4);
    mm::Image lbl8 = mm::label0(f, B8);
    int n4 = 0, n8 = 0;
    for (int y = 0; y < lbl4.h; y++)
        for (int x = 0; x < lbl4.w; x++)
            if ((int)lbl4.at(y,x) > n4) n4 = (int)lbl4.at(y,x);
    for (int y = 0; y < lbl8.h; y++)
        for (int x = 0; x < lbl8.w; x++)
            if ((int)lbl8.at(y,x) > n8) n8 = (int)lbl8.at(y,x);
    std::cout << "Componentes C4: " << n4 << "  |  C8: " << n8 << "\n";

    mm::show(
        std::vector<mm::Image>{f, norm_label(lbl4, std::max(n4, 1)), norm_label(lbl8, std::max(n8, 1))},
        MM_OUT,
        std::vector<std::string>{"f original", "C4 (" + std::to_string(n4) + " comp.)", "C8 (" + std::to_string(n8) + " comp.)"},
        3
    );

    return 0;
}

