// Compile: g++ -std=c++17 -o simulador simulador.cpp -I. && ./simulador

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include "morph.hpp"

// Função para simular o comportamento do simulador EP01_03
void simuladorEP0103() {
    // Constantes
    std::vector<double> LIMIARES = {0.00, 0.09, 0.21, 0.31, 0.39, 0.52, 0.60, 0.71, 0.81, 0.89, 1.00};

    // Cenários pré-definidos
    // sc1: Exemplo do EP
    std::vector<std::pair<int, double>> sc1 = {{0, 0.94}, {1, 0.80}, {1, 0.69}, {0, 0.67}, {1, 0.30}, {1, 0.15}, {1, 0.15}};
    // sc2: Detector Quase Perfeito
    std::vector<std::pair<int, double>> sc2 = {{1, 0.98}, {1, 0.95}, {1, 0.91}, {1, 0.87}, {0, 0.20}, {0, 0.10}, {0, 0.05}};
    // sc3: Detector Aleatório
    std::vector<std::pair<int, double>> sc3 = {{1, 0.55}, {0, 0.52}, {1, 0.48}, {0, 0.50}, {1, 0.51}, {0, 0.49}, {1, 0.53}};
    // sc4: Muitos Falsos Positivos
    std::vector<std::pair<int, double>> sc4 = {{1, 0.90}, {0, 0.88}, {0, 0.85}, {0, 0.80}, {1, 0.75}, {1, 0.70}, {0, 0.65}};

    // Amostras atuais
    std::vector<std::pair<int, double>> amostras = sc1;

    // Funções utilitárias
    auto safe = [](double n, double d) { return d == 0 ? 0.0 : n / d; };
    auto fmt2 = [](double v) { 
        char buffer[10];
        snprintf(buffer, sizeof(buffer), "%.2f", v);
        return std::string(buffer);
    };
    auto pct = [](double v) { return static_cast<int>(v * 100); };
    auto clamp01 = [](double v) { return std::min(1.0, std::max(0.0, v)); };

    // Cálculo de métricas em um limiar específico
    auto calcMetricas = [&](double limiar) {
        int vp = 0, fn = 0, fp = 0, vn = 0;
        for (const auto& s : amostras) {
            int pred = (s.second >= limiar) ? 1 : 0;
            if (s.first == 1 && pred == 1) vp++;
            else if (s.first == 1 && pred == 0) fn++;
            else if (s.first == 0 && pred == 1) fp++;
            else vn++;
        }
        int tot = vp + fn + fp + vn;
        double acc = safe(vp + vn, tot);
        double pre = safe(vp, vp + fp);
        double sen = safe(vp, vp + fn);
        double f1 = safe(2 * pre * sen, pre + sen);
        return std::make_tuple(vp, fn, fp, vn, acc, pre, sen, f1);
    };

    // Cálculo da AP (Average Precision)
    auto calcAP = [&]() {
        int m = LIMIARES.size();
        std::vector<double> precisoes(m), sensibilidades(m);
        for (int i = 0; i < m; i++) {
            auto [vp, fn, fp, vn, acc, pre, sen, f1] = calcMetricas(LIMIARES[i]);
            precisoes[m - 1 - i] = pre;
            sensibilidades[m - 1 - i] = sen;
        }

        // Monotonicidade
        std::vector<double> prec_mono = precisoes;
        for (int j = m - 2; j >= 0; j--) {
            if (prec_mono[j] < prec_mono[j + 1]) prec_mono[j] = prec_mono[j + 1];
        }

        double AP = 0;
        for (int k = 1; k < m; k++) {
            AP += prec_mono[k - 1] * (sensibilidades[k] - sensibilidades[k - 1]);
        }

        return std::make_tuple(precisoes, prec_mono, sensibilidades, AP);
    };

    // Simulação dos cenários e exibição dos resultados
    std::cout << "=== SIMULADOR EP01_03: Curva Precisão-Sensibilidade & mAP ===" << std::endl;
    std::cout << "Cenário: Exemplo do EP" << std::endl;
    std::cout << "Amostras: ";
    for (const auto& a : amostras) {
        std::cout << "(" << a.first << "," << fmt2(a.second) << ") ";
    }
    std::cout << std::endl << std::endl;

    // Teste em diferentes limiares
    int thrIdx = 9;
    double thr = LIMIARES[thrIdx];

    std::cout << "MÉTRICAS NO LIMIAR " << fmt2(thr) << ":" << std::endl;
    auto [vp, fn, fp, vn, acc, pre, sen, f1] = calcMetricas(thr);
    std::cout << "Matriz de Confusão:" << std::endl;
    std::cout << "  VP: " << vp << "  FN: " << fn << std::endl;
    std::cout << "  FP: " << fp << "  VN: " << vn << std::endl;
    std::cout << std::endl;
    std::cout << "Métricas:" << std::endl;
    std::cout << "  Acurácia: " << fmt2(acc) << " (" << pct(acc) << "%)" << std::endl;
    std::cout << "  Precisão: " << fmt2(pre) << " (" << pct(pre) << "%)" << std::endl;
    std::cout << "  Sensibilidade: " << fmt2(sen) << " (" << pct(sen) << "%)" << std::endl;
    std::cout << "  F1: " << fmt2(f1) << " (" << pct(f1) << "%)" << std::endl;

    std::cout << std::endl;
    std::cout << "CURVA PRECISÃO-SENSIBILIDADE:" << std::endl;
    auto [precisoes, prec_mono, sensibilidades, AP] = calcAP();
    std::cout << "mAP = " << fmt2(AP) << std::endl << std::endl;

    std::cout << "Tabela de Limiares:" << std::endl;
    std::cout << "Limiar | Prec. | P.mono | Sensib." << std::endl;
    for (int i = 0; i < static_cast<int>(LIMIARES.size()); i++) {
        int idx = static_cast<int>(LIMIARES.size()) - 1 - i;
        std::cout << fmt2(LIMIARES[idx]) << "  | " 
                  << fmt2(precisoes[i]) << " | " 
                  << fmt2(prec_mono[i]) << " | " 
                  << fmt2(sensibilidades[i]) << std::endl;
    }

    std::cout << std::endl;
    std::cout << "Nota: A visualização gráfica (canvas) não é possível em modo texto." << std::endl;
    std::cout << "Este output representa os cálculos do simulador." << std::endl;
}

int main() {
    simuladorEP0103();
    return 0;
}

