    </div>

    <!-- Comparativo em 2 Linhas (Original, Magnitude, Gx, Gy) -->
    <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(220px, 1fr));gap:16px;align-items:start;margin-bottom:14px;">

      <!-- Imagem Original f -->
